    ["Loadout '%s' already equipped."] = "El conjunto “%s” ya está equipado.",
    ["Delete loadout '%s'?"] = "¿Borrar el conjunto “%s”?",
    ["Cannot change equipment in combat."] = "No se puede cambiar el equipo en combate.",
    ["Equipment swap API not available on this client."] = "La API de cambio de equipo no está disponible en este cliente.",
    ["No loadouts saved yet."] = "Todavía no hay conjuntos guardados.",
    ["|cffaaaaaaNo loadouts saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaaTodavía no hay conjuntos guardados. Usa el botón de arriba para guardar tu equipo actual.|r",
    ["Saved loadouts:"] = "Conjuntos guardados:",
    ["Usage: /loadout equip <name> | save <name> | delete <name> | list"] = "Uso: /loadout equip <name> | save <name> | delete <name> | list",
    ["Usage: /loadout delete <name>"] = "Uso: /loadout delete <name>",
    ["|cffaaaaaaSlash commands: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Short alias: /lo|r"] = "|cffaaaaaaComandos: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Alias corto: /lo|r",
    ["No account-wide loadouts to import."] = "No hay conjuntos de toda la cuenta que importar.",
    ["Imported %d account-wide loadout(s) onto this character."] = "Se han importado %d conjunto(s) de toda la cuenta a este personaje.",
    ["You have account-wide loadouts from an older version. Type /lo import to copy them onto this character."] = "Tienes conjuntos de toda la cuenta de una versión anterior. Escribe /lo import para copiarlos a este personaje.",
    ["Import from older version"] = "Importar de una versión anterior",
    ["|cffaaaaaaYou have gear sets saved account-wide by an older version. Loadouts are now per-character — import copies them onto THIS character.|r"] = "|cffaaaaaaTienes conjuntos de equipo guardados para toda la cuenta por una versión anterior. Ahora los conjuntos son por personaje: importar los copia a ESTE personaje.|r",
    ["Import account-wide loadouts"] = "Importar conjuntos de toda la cuenta",
    ["Head"] = "Cabeza",
    ["Chest"] = "Pecho",
    ["Feet"] = "Pies",
    ["Finger 1"] = "Dedo 1",
    ["Trinket 1"] = "Abalorio 1",
    ["Both trinkets"] = "Ambos abalorios",
    ["Set focus"] = "Fijar objetivo de atención",
    ["Healing potion"] = "Poción de curación",
    ["Macro Factory"] = "Fábrica de macros",
    ["|cffaaaaaaOne click builds a ready-made macro (per character). Then open |cffffffff/macro|r and drag it onto your action bar. Works on any client — uses item slots / IDs, no English needed.|r"] = "|cffaaaaaaUn clic crea una macro lista para usar (por personaje). Después abre |cffffffff/macro|r y arrástrala a tu barra de acción. Funciona en cualquier cliente: usa ranuras/ID de objeto, no hace falta el inglés.|r",
    ["Macro Factory: can't create macros in combat."] = "Fábrica de macros: no se pueden crear macros en combate.",
    ["Macro Factory: nothing to build (e.g. no healing potion in your bags)."] = "Fábrica de macros: nada que crear (p. ej., no hay poción de curación en tus bolsas).",
    ["Macro Factory: couldn't create it (character macro slots full?)."] = "Fábrica de macros: no se pudo crear (¿ranuras de macro de personaje llenas?).",
    ["Macro '%s' updated — drag it from |cffffffff/macro|r onto your action bar."] = "Macro “%s” actualizada: arrástrala desde |cffffffff/macro|r a tu barra de acción.",
    ["Macro '%s' created — open |cffffffff/macro|r and drag it onto your action bar."] = "Macro “%s” creada: abre |cffffffff/macro|r y arrástrala a tu barra de acción.",
    ["Back"] = "Espalda",
    ["Main Hand"] = "Mano derecha",
    ["Save All..."] = "Guardar todo...",
    ["Save Trinkets..."] = "Guardar abalorios...",
    ["Save Weapons..."] = "Guardar armas...",
    ["Save current as new..."] = "Guardar el actual como nuevo...",
    ["Save trinkets only..."] = "Guardar solo abalorios...",
    ["Save weapons only..."] = "Guardar solo armas...",
    ["Settings..."] = "Ajustes...",
    ["Minimap Button"] = "Botón del minimapa",
    ["Left-click for a quick set-switcher menu, right-click to open settings, drag to reposition."] = "Clic izquierdo para un menú rápido de cambio de conjunto, clic derecho para abrir los ajustes, arrastra para recolocarlo.",
    ["Left-click: switch set"] = "Clic izquierdo: cambiar conjunto",
    ["Right-click: settings"] = "Clic derecho: ajustes",
    ["Drag: reposition"] = "Arrastrar: recolocar",
    ["Auto-Switch on Stance/Form"] = "Cambio automático por actitud/forma",
    ["Enable auto-switching"] = "Activar cambio automático",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "Equipa automáticamente un conjunto cuando cambias de actitud/forma (actitudes de guerrero, formas de druida). Solo fuera de combate: si el cambio ocurre en combate, se pospone hasta que termine el combate.",
    ["Auto-equip on form"] = "Equipar automáticamente con la forma",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "Equipa este conjunto automáticamente cuando se active la actitud/forma elegida.",
    ["Auto-Switch on Dual Spec"] = "Cambio automático por doble especialización",
    ["Enable spec auto-switching"] = "Activar cambio automático por especialización",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "Equipa automáticamente un conjunto cuando cambias entre Especialización 1 y Especialización 2 (doble especialización). Asocia abajo cada conjunto a una especialización. Requiere tener la doble especialización activa.",
    ["Auto-equip on spec"] = "Equipar automáticamente con la especialización",
    ["Equip this loadout automatically when you switch to this spec."] = "Equipa este conjunto automáticamente cuando cambies a esta especialización.",
    ["None"] = "Ninguno",
    ["No Form"] = "Sin forma",
    ["Form %d"] = "Forma %d",
    ["Character Frame Sidebar"] = "Barra lateral del marco de personaje",
    ["Show sidebar on character frame"] = "Mostrar barra lateral en el marco de personaje",
    ["Attach a quick-access sidebar to the right of the character window. Click a set to select, double-click or button to equip, right-click for context menu."] = "Añade una barra lateral de acceso rápido a la derecha de la ventana de personaje. Haz clic en un conjunto para seleccionarlo, doble clic o el botón para equiparlo, clic derecho para el menú contextual.",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaaConsejo: con la ventana de personaje abierta, activa el modo de edición (Desbloquear) para arrastrar la barra lateral; haz clic derecho en la caja morada para restablecer su posición.|r",
    ["New Set"] = "Conjunto nuevo",
    ["Left-click: select"] = "Clic izquierdo: seleccionar",
    ["Double-click / Right-click menu: equip"] = "Doble clic / menú del clic derecho: equipar",
    ["Change icon..."] = "Cambiar icono...",
    ["Icon for: %s"] = "Icono de: %s",
    ["Bind to %s"] = "Asociar a %s",
    ["'%s' bound to %s."] = "“%s” asociado a %s.",
    ["'%s' unbound from spec."] = "“%s” desasociado de la especialización.",
    ["Replace: %s"] = "Sustituir: %s",
    ["Remove from set"] = "Quitar del conjunto",
    ["Loadout '%s': slot updated."] = "Conjunto “%s”: ranura actualizada.",
    ["SlotPicker module is required for editing item slots."] = "Se necesita el módulo SlotPicker para editar las ranuras de objeto.",
    ["Empty: %s"] = "Vacío: %s",
    ["in the bank"] = "en el banco",
    ["in bags, equip failed"] = "en las bolsas, no se pudo equipar",
    ["not found"] = "no encontrado",
    ["missing"] = "falta",
    ["Part of set: %s"] = "Parte del conjunto: %s",
    ["Add a slot"] = "Añadir una ranura",
    ["Re-adds an ignored slot to this set."] = "Vuelve a añadir a este conjunto una ranura ignorada.",
    ["Right-click: remove this slot from the set."] = "Clic derecho: quitar esta ranura del conjunto.",
    ["Left-click to pick an item from your bags"] = "Clic izquierdo para elegir un objeto de tus bolsas",
    ["(equipped)"] = "(equipado)",
    ["Slot Picker"] = "Selector de ranura",
    ["Enable slot picker"] = "Activar selector de ranura",
    ["|cffaaaaaaRight-click an equipment slot in the character window to see all compatible items from your bags and click one to equip it.|r"] = "|cffaaaaaaHaz clic derecho en una ranura de equipo de la ventana de personaje para ver todos los objetos compatibles de tus bolsas y equipar uno con un clic.|r",
    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "Pasa el cursor por una ranura de equipo del marco de personaje para ver una tira compacta de objetos de tus bolsas, o haz clic con el modificador para abrir un selector mayor y fijable. Haz clic en un objeto para equiparlo (fuera de combate).",
    ["Flyout on hover"] = "Desplegable al pasar el cursor",
    ["Hovering an equipment slot pops out a compact strip of items you can swap in — the paperdoll flyout look. Turn off to use only the modifier-click picker."] = "Al pasar el cursor por una ranura de equipo se despliega una tira compacta de objetos que puedes intercambiar, al estilo del desplegable del muñeco. Desactívalo para usar solo el selector con modificador.",
    ["Activation modifier"] = "Modificador de activación",
    ["Choose which key combination opens the item picker when you click an equipment slot."] = "Elige qué combinación de teclas abre el selector de objetos al hacer clic en una ranura de equipo.",
    ["Shift + Right-click"] = "Mayús + Clic derecho",
    ["Alt + Right-click"] = "Alt + Clic derecho",
    ["Ctrl + Right-click"] = "Ctrl + Clic derecho",
    ["Right-click only"] = "Solo clic derecho",
    ["Grid columns"] = "Columnas de la cuadrícula",
    ["How many item icons per row in the picker popup."] = "Cuántos iconos de objeto por fila en la ventana del selector.",
    ["Items for: %s"] = "Objetos para: %s",
    ["Close automatically on mouse-out"] = "Cerrar automáticamente al salir el cursor",
    ["The picker closes itself shortly after the mouse leaves it. Drag it once to pin it open until you close it manually."] = "El selector se cierra poco después de que el ratón salga de él. Arrástralo una vez para fijarlo abierto hasta que lo cierres a mano.",
    ["No matching items in your bags."] = "No hay objetos compatibles en tus bolsas.",
