    ["UI Language"] = "Idioma de la interfaz",
    ["Auto (client language)"] = "Automático (idioma del cliente)",
    ["Choose the language for the VuloClassicUI interface. 'Auto' uses your WoW client's language (German clients see German, all others see English).\n\n|cffaaaaaaRequires /reload to apply.|r"] = "Elige el idioma de la interfaz de VuloClassicUI. “Automático” usa el idioma de tu cliente de WoW (los clientes en alemán ven alemán, el resto ve inglés).\\n\\n|cffaaaaaaRequiere /reload para aplicarse.|r",
    ["Language changed. /reload required to apply the new language to all UI elements."] = "Idioma cambiado. Se requiere /reload para aplicar el nuevo idioma a todos los elementos de la interfaz.",
