    ["Character"] = "Personaje",
    ["World"] = "Mundo",
    ["Crisp portrait hit numbers"] = "Números de golpe nítidos en el retrato",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "Muestra los números de daño/sanación que aparecen en el retrato del jugador/mascota con una fuente fija y nítida en lugar de la animación creciente y borrosa de Blizzard.",
    ["Hit number size"] = "Tamaño de los números de golpe",
    ["Font size of the portrait hit numbers (when 'Crisp' is on)."] = "Tamaño de fuente de los números de golpe del retrato (cuando “Nítidos” está activado).",
    ["Auto-select single gossip option"] = "Elegir automáticamente la opción de diálogo única",
    ["Skips NPC dialog windows that only have a single option. Hold SHIFT to temporarily bypass."] = "Omite las ventanas de diálogo de PNJ que solo tienen una opción. Mantén MAYÚS pulsado para desactivarlo temporalmente.",
    ["Faster auto-loot"] = "Autobotín más rápido",
    ["Loots all items at once when auto-loot applies, instead of one by one."] = "Recoge todos los objetos de una vez cuando se aplica el autobotín, en lugar de uno por uno.",
    ["Max camera zoom"] = "Zoom máximo de cámara",
    ["Raises the maximum camera zoom-out distance far beyond the default."] = "Aumenta la distancia máxima de alejamiento de la cámara muy por encima del valor predeterminado.",
    ["Player & Target Frame"] = "Marco de jugador y objetivo",
    ["Elite dragon border for your player frame, plus real health, threat display and the rare-elite border for the target and focus frames."] = "Borde de dragón de élite para tu marco de jugador, además de vida real, indicador de amenaza y el borde de raro-élite para los marcos de objetivo y foco.",
    ["Target & Focus Frame"] = "Marco de objetivo y foco",
    ["|cffaaaaaaPuts the golden elite dragon (or the rare variants) around your player portrait — the look elite mobs have on the target frame.|r"] = "|cffaaaaaaColoca el dragón dorado de élite (o sus variantes de raro) alrededor de tu retrato de jugador: el aspecto que tienen los monstruos de élite en el marco de objetivo.|r",
    ["Frame style"] = "Estilo de marco",
    ["Elite (golden dragon)"] = "Élite (dragón dorado)",
    ["Rare-Elite (silver dragon)"] = "Raro-Élite (dragón plateado)",
    ["Rare (silver)"] = "Raro (plateado)",
    ["Off (default frame)"] = "Desactivado (marco predeterminado)",
    ["Cooldown Manager"] = "Gestor de reutilización",
    ["Cooldowns"] = "Reutilizaciones",
    ["Delete group"] = "Eliminar grupo",
    ["|cff888888Nothing in this group yet.|r"] = "|cff888888Aún no hay nada en este grupo.|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "Grupo de reutilización “%s” desbloqueado. Arrastra hechizos/objetos sobre él; |cff9b6cffarrastra|r para moverlo.",
    ["Cooldown group '%s' locked."] = "Grupo de reutilización “%s” bloqueado.",
    ["Group type"] = "Tipo de grupo",
    ["Buffs & Procs (only show while active)"] = "Beneficios y procs (mostrar solo mientras estén activos)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaaLos iconos aparecen solo mientras tienes su beneficio/proc; si no, la barra queda vacía. Añade el BENEFICIO (p. ej. Lanzamiento claro) por nombre o ID.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaaLos iconos muestran el tiempo de reutilización de cada hechizo/abalorio.|r",
    ["Size & offsets"] = "Tamaño y desplazamientos",
    ["Extra settings"] = "Ajustes adicionales",
    ["Friends List"] = "Lista de amigos",
    ["Dialog Popups"] = "Ventanas de diálogo",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Rediseña los diálogos de confirmación de Blizzard (cuenta atrás de salida, borrar objeto, resucitar, invitación a grupo) para que encajen con el aspecto oscuro.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaaRediseña los diálogos de confirmación de Blizzard (cuenta atrás de salida, borrar objeto, resucitar, invitación a grupo) para que encajen con el aspecto oscuro.|r",
    ["Accent strip"] = "Franja de acento",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "Dibuja un fino degradado de acento en el borde superior de cada diálogo.",
    ["Addon Skins"] = "Aspectos de AddOns",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "Rediseña las ventanas de los AddOns compatibles de terceros para que encajen con el aspecto oscuro: lista de errores, rastreador de misiones, navegador de botín, perfilador y más.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaaRediseña las ventanas de los AddOns compatibles con el aspecto oscuro. Los aspectos se aplican al cargarse el AddOn; desactivar uno requiere un /reload (el rastreador de misiones se restaura al instante).|r",
    ["not loaded"] = "no cargado",
    ["Dark window skin"] = "Aspecto oscuro de ventana",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "Rediseña toda la ventana de amigos en oscuro con acentos morados. Desactivarlo requiere un /reload para restaurar el marco de Blizzard.",
    ["Class color names"] = "Nombres con color de clase",
    ["Colors each online friend's name by their class."] = "Colorea el nombre de cada amigo conectado según su clase.",
    ["Show class icons"] = "Mostrar iconos de clase",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "Muestra un icono de clase junto a los amigos de WoW conectados (del juego y de Battle.net).",
    ["Class icon style"] = "Estilo de icono de clase",
    ["Blizzard crests"] = "Blasones de Blizzard",
    ["Circles"] = "Círculos",
    ["Squares"] = "Cuadrados",
    ["Show status dot"] = "Mostrar punto de estado",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "Un punto de color tras el nombre: verde conectado, amarillo ausente, rojo ocupado, gris desconectado.",
    ["Show friend notes"] = "Mostrar notas de amigos",
    ["Shows your saved note for the friend in grey under their name."] = "Muestra en gris la nota que has guardado del amigo bajo su nombre.",
    ["Faction"] = "Facción",
    ["Faction accent on realm line"] = "Acento de facción en la línea de reino",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "Tiñe la línea de reino/zona de rojo (Horda) o azul (Alianza).",
    ["Faction row tint"] = "Tinte de fila por facción",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "Añade un sutil tinte rojo/azul de fondo a la fila de cada amigo conectado.",
    ["Invites"] = "Invitaciones",
    ["Auto-accept Battle.net friend invites"] = "Aceptar automáticamente invitaciones de amistad de Battle.net",
    ["Automatically accepts incoming Battle.net friend requests."] = "Acepta automáticamente las solicitudes de amistad de Battle.net entrantes.",
    ["Auto-accept group invites from friends"] = "Aceptar automáticamente invitaciones de grupo de amigos",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "Te une automáticamente a un grupo cuando la invitación proviene de alguien de tu lista de amigos.",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "Nombres con color de clase, iconos de clase, puntos de estado, notas en línea, tinte de facción y aceptación automática opcional.",
    ["Highlight"] = "Resaltado",
