    ["Countdown text color..."] = "Color del texto de cuenta atrás...",
    ["Warn color under (sec)"] = "Color de aviso por debajo de (s)",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "Por debajo de estos segundos, la cuenta atrás cambia al color de aviso; 0 desactiva el color de aviso.",
    ["Warn color..."] = "Color de aviso...",
    ["Glow while ready"] = "Destello mientras esté lista",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "Un destello constante mientras la reutilización esté lista y, en el caso de los hechizos, solo mientras se pueda usar de verdad (maná suficiente, etc.).",
    ["Glow color"] = "Color del destello",
    ["Show keybinds"] = "Mostrar asignaciones de teclas",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "Muestra la tecla a la que está asignado el hechizo/objeto en tus barras de acción. Las macros no se reconocen; las páginas de actitud siguen a la barra principal.",
    ["Keybind color..."] = "Color de la asignación de teclas...",
    ["Keep inactive buffs visible (greyed out)"] = "Mantener visibles los beneficios inactivos (atenuados)",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "Los iconos se quedan en su sitio cuando acaba el beneficio, solo desaturados: la barra nunca da saltos.",
    ["Add (name / ID)"] = "Añadir (nombre / ID)",
    ["Tracked"] = "Rastreados",
    ["  |cff888888(item)|r"] = "  |cff888888(objeto)|r",
    ["Up"] = "Arriba",
    ["Icons per row"] = "Iconos por fila",
    ["Growth direction"] = "Dirección de crecimiento",
    ["Right"] = "Derecha",
    ["Left"] = "Izquierda",
    ["Down"] = "Abajo",
    ["Only show while on cooldown"] = "Mostrar solo mientras esté en reutilización",
    ["Hides ready icons; they reappear when on cooldown."] = "Oculta los iconos listos; reaparecen cuando entran en reutilización.",
    ["Show countdown text"] = "Mostrar texto de cuenta atrás",
    ["Show stacks"] = "Mostrar acumulaciones",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555(otra clase)|r",
    ["Edit mode — move the cooldown bars"] = "Modo de edición: mover las barras de reutilización",
    ["Stop editing — lock the cooldown bars"] = "Dejar de editar: bloquear las barras de reutilización",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "Desbloquea solo las barras de reutilización para que puedas arrastrarlas. Las flechas ajustan con precisión; clic derecho en un recuadro morado para X/Y. (Para mover TODAS las ventanas de VuloUI, usa “Modo de desbloqueo” en Global.)",
    ["Hide cooldowns under (sec)"] = "Ocultar reutilizaciones por debajo de (s)",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "Se ignoran las reutilizaciones iguales o inferiores a este valor. 1,5 oculta la reutilización global; súbelo para ocultar también las reutilizaciones cortas; 0 lo muestra todo.",
    ["Move earlier"] = "Mover antes",
    ["Move later"] = "Mover después",
    ["Stack / reagent position"] = "Posición de acumulaciones/reactivos",
    ["Stack / reagent size"] = "Tamaño de acumulaciones/reactivos",
    ["Stack / reagent color..."] = "Color de acumulaciones/reactivos...",
    ["Bottom right"] = "Abajo a la derecha",
    ["Bottom left"] = "Abajo a la izquierda",
    ["Top right"] = "Arriba a la derecha",
    ["Top left"] = "Arriba a la izquierda",
    ["Show reagent counts"] = "Mostrar recuento de reactivos",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "Muestra el recuento del reactivo PROPIO de cada hechizo: Fragmentos de alma en Fuego de alma, Piedra infernal en Infierno, etc. Los hechizos sin reactivo no muestran nada. Requiere “Mostrar acumulaciones” activado.",
    ["Anchor"] = "Anclaje",
    ["Anchor to"] = "Anclar a",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "Fija esta barra a un marco de unidad, al minimapa o a la barra de otro grupo: entonces se moverá con él. Arrastra la barra para soltarla.",
    ["Player Frame"] = "Marco de jugador",
    ["Focus Frame"] = "Marco de foco",
    ["Pet Frame"] = "Marco de mascota",
    ["None (free)"] = "Ninguno (libre)",
    ["Cooldown Manager: can't anchor there — it would loop."] = "Gestor de reutilización: no se puede anclar ahí, se crearía un bucle.",
    ["Side"] = "Lado",
    ["Below"] = "Debajo",
    ["Above"] = "Encima",
    ["Left of"] = "A la izquierda de",
    ["Right of"] = "A la derecha de",
    ["X offset"] = "Desplazamiento X",
    ["Y offset"] = "Desplazamiento Y",
    ["Icon shape"] = "Forma del icono",
    ["Square"] = "Cuadrado",
    ["Rounded"] = "Redondeado",
    ["Icon crop (%)"] = "Recorte del icono (%)",
    ["How much is cut off each edge of the icon. 0 shows the whole icon including the border baked into its artwork."] = "Cuánto se recorta de cada borde del icono. 0 muestra el icono completo, incluido el borde de su propia imagen.",
    ["Cooldown swipe darkness"] = "Oscuridad del barrido de reutilización",
    ["Only in combat"] = "Solo en combate",
    ["Only with a target"] = "Solo con un objetivo",
    ["Only with an attackable target"] = "Solo con un objetivo atacable",
    ["Hide while mounted"] = "Ocultar mientras montas",
    ["Only in instances"] = "Solo en instancias",
    ["Dim icon while on cooldown"] = "Atenuar el icono durante la reutilización",
    ["Flash when ready"] = "Destellar al estar listo",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "Guarda instantáneas con nombre de tus barras de acción, macros y asignaciones de teclas, y las restaura con un clic.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaaGuarda toda la configuración de tus barras (todas las ranuras de acción, macros y asignaciones de teclas) como un perfil con nombre y la restaura con un clic: por ejemplo, disposiciones de JcJ y de banda, o para copiar una configuración a un twink (almacenamiento para toda la cuenta).|r",
    ["Load"] = "Cargar",
    ["Save current setup"] = "Guardar la configuración actual",
    ["Please enter a profile name first."] = "Introduce primero un nombre de perfil.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888Aún no hay perfiles guardados.|r",
    ["Also restore macros"] = "Restaurar también las macros",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "Reescribe las macros guardadas por nombre (las existentes se actualizan y las que faltan se crean).",
    ["Also restore keybindings"] = "Restaurar también las asignaciones de teclas",
    ["Load profile"] = "Cargar perfil",
    ["Overwrite with current setup"] = "Sobrescribir con la configuración actual",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "Reemplaza el perfil seleccionado por tus barras/macros/asignaciones actuales.",
    ["Note: profile '%s' was saved on another class (%s)."] = "Nota: el perfil “%s” se guardó en otra clase (%s).",
    ["Flight Timer"] = "Temporizador de vuelo",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800La base de datos de rutas de vuelo no está cargada.|r Reinicia WoW por completo (un /reload no basta tras una actualización) para que funcionen los tiempos de vuelo.",
    ["Show flight time bar"] = "Mostrar la barra de tiempo de vuelo",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "Muestra el destino y el tiempo restante mientras viajas en transporte volador. El primer vuelo de una ruta se aprende y a partir de ahí tienes una cuenta atrás.",
    ["Flight: %s (%s)"] = "Vuelo: %s (%s)",
    ["Print flight time to chat"] = "Mostrar el tiempo de vuelo en el chat",
    ["After landing, prints the measured flight time."] = "Tras aterrizar, muestra el tiempo de vuelo medido.",
    ["Reset learned times"] = "Restablecer los tiempos aprendidos",
    ["Deletes all saved route durations."] = "Elimina todas las duraciones de ruta guardadas.",
    ["Learned flight times reset."] = "Tiempos de vuelo aprendidos restablecidos.",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffffTIEMPO DE VUELO|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "Temporizador de vuelo: x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor del temporizador de vuelo activo. |cff9b6cffArrastra|r o usa las |cff9b6cffflechas|r (MAYÚS = 5px).",
    ["Flight timer mover disabled."] = "Movedor del temporizador de vuelo desactivado.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "Depuración de vuelo activada — haz un vuelo y la resolución aparecerá en el chat.",
    ["Flight debug off."] = "Depuración de vuelo desactivada.",
    ["LazyVulo"] = "LazyVulo",
    ["Training"] = "Training",
    ["Group Board"] = "Tablón de grupos",
    ["Apexis Relic memory minigame helper (Ogri'la dailies): record the flashing color sequence, always see what to click next."] = "Ayudante del minijuego de memoria de la Reliquia de apexis (diarias de Ogri'la): registra la secuencia de colores que parpadea y ve siempre qué pulsar a continuación.",
    ["Green relic"] = "Reliquia verde",
    ["Yellow relic"] = "Reliquia amarilla",
    ["Blue relic"] = "Reliquia azul",
    ["Red relic"] = "Reliquia roja",
    ["Left click: remove this entry.\nRight click: remove this and all later entries."] = "Clic izquierdo: quitar esta entrada.\\nClic derecho: quitar esta y todas las posteriores.",
    ["Click to record this color."] = "Haz clic para registrar este color.",
    ["Hotkey: %s"] = "Tecla rápida: %s",
    ["LazyVulo is disabled."] = "LazyVulo está desactivado.",
    ["|cffaaaaaaHelper for the Apexis Relic memory minigame (Ogri'la dailies). Record the flashing sequence with the buttons or hotkeys; the first icon is always your next click. Correct clicks are consumed automatically, wrong clicks are restored.|r"] = "|cffaaaaaaAyudante para el minijuego de memoria de la Reliquia de apexis (diarias de Ogri'la). Registra la secuencia parpadeante con los botones o las teclas rápidas; el primer icono es siempre tu siguiente clic. Los clics correctos se consumen automáticamente y los erróneos se restauran.|r",
    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaaÁbrelo manualmente con /lazyvulo o /lv.|r",
    ["Auto-show at the Apexis Relic"] = "Mostrar automáticamente en la Reliquia de apexis",
    ["Opens the window automatically when you start the relic minigame."] = "Abre la ventana automáticamente cuando inicias el minijuego de la reliquia.",
    ["Enable hotkeys while the window is shown"] = "Activar las teclas rápidas mientras la ventana esté visible",
    ["Disable hotkeys while in combat"] = "Desactivar las teclas rápidas en combate",
    ["Hands the keys back to your action bars while you are in combat."] = "Devuelve las teclas a tus barras de acción mientras estás en combate.",
    ["Show help tooltips"] = "Mostrar descripciones de ayuda",
    ["Window scale"] = "Escala de la ventana",
    ["Hotkeys"] = "Teclas rápidas",
