    ["Block group invites from strangers"] = "Bloquear invitaciones de grupo de desconocidos",
    ["Auto-declines party/raid invites from players who are not in your guild or on your friends list."] = "Rechaza automáticamente las invitaciones de grupo/banda de jugadores que no estén en tu hermandad ni en tu lista de amigos.",
    ["Block trades from strangers"] = "Bloquear intercambios de desconocidos",
    ["Auto-closes trade windows opened by players who are not in your guild or on your friends list. Trades you start yourself are not affected."] = "Cierra automáticamente las ventanas de intercambio abiertas por jugadores que no estén en tu hermandad ni en tu lista de amigos. Los intercambios que inicias tú no se ven afectados.",
    ["|cffffd200[QoL]|r Blocked group invite from %s (not guild/friend)."] = "|cffffd200[Confort]|r Invitación de grupo de %s bloqueada (ni hermandad ni amigo).",
    ["|cffffd200[QoL]|r Blocked trade from %s (not guild/friend)."] = "|cffffd200[Confort]|r Intercambio de %s bloqueado (ni hermandad ni amigo).",
    ["Adds a tab to your spell book that lists the abilities you can still learn from your class trainer, grouped by level. Open the book icon below the spell schools."] = "Añade a tu libro de hechizos una pestaña con las habilidades que aún puedes aprender de tu entrenador de clase, agrupadas por nivel. Abre el icono de libro debajo de las escuelas de hechizos.",
    ["|cffaaaaaaAdds a tab to your spell book (the book icon on the side, below the spell schools) listing every ability you can still learn from your class trainer — grouped by status and coloured by level. No need to visit a trainer.|r"] = "|cffaaaaaaAñade a tu libro de hechizos una pestaña (el icono de libro del lateral, debajo de las escuelas de hechizos) con todas las habilidades que aún puedes aprender de tu entrenador de clase — agrupadas por estado y coloreadas por nivel. Sin necesidad de visitar al entrenador.|r",
    ["Available now"] = "Disponibles ahora",
    ["Available but Missing Requirements"] = "Disponibles, pero faltan requisitos",
    ["Upcoming"] = "Próximas",
    ["Not Yet Available"] = "Aún no disponibles",
    ["Missing Required Talents"] = "Faltan talentos necesarios",
    ["Already Known"] = "Ya aprendidas",
    ["Level %d"] = "Nivel %d",
    ["Cost: %s"] = "Coste: %s",
    ["What can I train?"] = "¿Qué puedo entrenar?",
    ["No results found"] = "No se han encontrado resultados",
    ["|cffffffffPOWER BAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRA DE PODER|r\\n|cffaaaaaaArrastra o usa las flechas|r",
    ["Power Bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Move' again to finish."] = "Movimiento de la barra de poder activo. |cff9b6cffArrastra la caja morada|r o usa las |cff9b6cffteclas de flecha|r (MAYÚS = 5 px). Vuelve a pulsar “Desbloquear / Mover” para terminar.",
    ["Power Bar mover disabled."] = "Movimiento de la barra de poder desactivado.",
    ["|cffaaaaaaResource bar that follows your class automatically (Mana / Rage / Energy). Druids switch with their form: Bear = Rage, Cat = Energy, otherwise Mana.|r"] = "|cffaaaaaaBarra de recursos que sigue a tu clase automáticamente (maná / furia / energía). Los druidas cambian según su forma: oso = furia, gato = energía, en el resto maná.|r",
    ["v%s loaded. /vcui to open."] = "v%s cargado. /vcui para abrir.",
    ["UI not loaded. Likely a Lua error during init. Enable /console scriptErrors 1 and /reload."] = "Interfaz no cargada. Probablemente un error de Lua durante el inicio. Activa /console scriptErrors 1 y haz /reload.",
    ["Not possible in combat."] = "No es posible en combate.",
    ["DB reset. UI reloading."] = "Base de datos reiniciada. Recargando la interfaz.",
    ["Debug = %s"] = "Depuración = %s",
    ["Registered modules:"] = "Módulos registrados:",
