    ["Gold Tracker not active."] = "El registro de oro no está activo.",
    ["|cffff5555Error while executing:|r %s"] = "|cffff5555Error al ejecutar:|r %s",
    ["|cffff5555Event handler error (%s):|r %s"] = "|cffff5555Error en el gestor de eventos (%s):|r %s",
    ["WARN: Module '%s' already registered."] = "AVISO: el módulo “%s” ya está registrado.",
    ["|cffff5555Error enabling module '%s':|r %s"] = "|cffff5555Error al activar el módulo “%s”:|r %s",
    ["|cffff5555Error disabling '%s':|r %s"] = "|cffff5555Error al desactivar “%s”:|r %s",
    ["Module '%s' disabled. /reload recommended for full effect."] = "Módulo “%s” desactivado. Se recomienda /reload para que surta pleno efecto.",
    ["|cffff5555LibSharedMedia-3.0 not found, Media Registry will be skipped.|r"] = "|cffff5555No se encontró LibSharedMedia-3.0; se omitirá el registro de medios.|r",
    ["Profiles"] = "Perfiles",
    ["Manage profiles with different settings. A default profile can be assigned per class and is loaded automatically on login."] = "Gestiona perfiles con distintos ajustes. Se puede asignar un perfil predeterminado por clase que se carga automáticamente al iniciar sesión.",
    ["Active Profile"] = "Perfil activo",
    ["You are currently using: |cff9b6cff%s|r  (Class: %s)"] = "Estás usando: |cff9b6cff%s|r  (Clase: %s)",
    ["Switch Profile"] = "Cambiar de perfil",
    ["Profile for this character"] = "Perfil para este personaje",
    ["|cffaaaaaaPins a profile to THIS character only. At login it beats the class assignment and the account-wide selection - so every character can keep its own minimap, bars and window settings.|r"] = "|cffaaaaaaFija un perfil SOLO a ESTE personaje. Al iniciar sesión tiene prioridad sobre la asignación por clase y la selección de toda la cuenta, así que cada personaje puede conservar sus propios ajustes de minimapa, barras y ventanas.|r",
    ["This character"] = "Este personaje",
    ["Create New Profile"] = "Crear perfil nuevo",
    ["Name"] = "Nombre",
    ["Copy Settings From"] = "Copiar ajustes de",
    ["- empty profile (defaults) -"] = "- perfil vacío (predeterminados) -",
