    ["Create Profile"] = "Crear perfil",
    ["|cffff5555Please enter a name.|r"] = "|cffff5555Introduce un nombre.|r",
    ["|cffff5555Please enter a new name.|r"] = "|cffff5555Introduce un nombre nuevo.|r",
    ["Error."] = "Error.",
    ["Share Profile"] = "Compartir perfil",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaaExporta el perfil actual como texto, ya sea como copia de seguridad o para compartirlo. Al importar siempre se crea un perfil NUEVO y nunca se sobrescribe nada.|r",
    ["Export as string"] = "Exportar como texto",
