    ["Delete profile '%s'? This cannot be undone."] = "¿Eliminar el perfil “%s”? Esto no se puede deshacer.",
    ["Reset profile '%s' to the default settings? This cannot be undone."] = "¿Restablecer el perfil “%s” a los ajustes predeterminados? Esto no se puede deshacer.",
    ["Profile changed. Reload the UI now so every module picks it up?"] = "Perfil cambiado. ¿Recargar la interfaz ahora para que todos los módulos lo apliquen?",
    ["|cffff5555Profile '%s' could not be loaded:|r %s"] = "|cffff5555No se pudo cargar el perfil “%s”:|r %s",
    ["Rename to"] = "Renombrar a",
    ["Rename"] = "Renombrar",
    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555El perfil predeterminado no se puede eliminar.|r",
    ["Apply to Active Class"] = "Aplicar a la clase actual",
    ["Sets the current profile as the default for %s."] = "Establece el perfil actual como predeterminado para %s.",
    ["'%s' is now the default profile for %s."] = "“%s” ya es el perfil predeterminado de %s.",
    ["Per-class profile (quick setup)"] = "Perfil por clase (configuración rápida)",
    ["|cffaaaaaaOne click: makes a profile named after your class (copied from the current one) and loads it for this class automatically. Run it once on each character — every class then keeps its own cooldown bars, frames and settings.|r"] = "|cffaaaaaaUn clic: crea un perfil con el nombre de tu clase (copiado del actual) y lo carga automáticamente para esa clase. Ejecútalo una vez en cada personaje; así cada clase conserva sus propias barras de tiempo de reutilización, marcos y ajustes.|r",
    ["Set up a %s profile"] = "Crear un perfil de %s",
    ["'%s' is now the %s profile. |cffffff00/reload|r to apply."] = "“%s” ya es el perfil de %s. |cffffff00/reload|r para aplicarlo.",
    ["Profile Assignment per Class"] = "Asignación de perfil por clase",
    ["Choose a default profile for each class. When logging in with a character of that class, the profile will be loaded automatically."] = "Elige un perfil predeterminado para cada clase. Al iniciar sesión con un personaje de esa clase, el perfil se cargará automáticamente.",
    ["Settings migrated to profile system (all settings are in profile '%s')."] = "Ajustes migrados al sistema de perfiles (todos los ajustes están en el perfil “%s”).",
    ["|cffff5555Profile '%s' does not exist.|r"] = "|cffff5555El perfil “%s” no existe.|r",
    ["Profile '%s' created%s."] = "Perfil “%s” creado%s.",
    [" (copy of '%s')"] = " (copia de “%s”)",
    ["Name cannot be empty."] = "El nombre no puede estar vacío.",
    ["Profile already exists."] = "El perfil ya existe.",
    ["Default profile cannot be deleted."] = "El perfil predeterminado no se puede eliminar.",
    ["Profile does not exist."] = "El perfil no existe.",
    ["Active profile deleted. Default loaded. /reload recommended."] = "Perfil activo eliminado. Se cargó el predeterminado. Se recomienda /reload.",
    ["Profile '%s' deleted."] = "Perfil “%s” eliminado.",
