    ["New name already exists."] = "El nombre nuevo ya existe.",
    ["Profile '%s' renamed to '%s'."] = "Perfil “%s” renombrado a “%s”.",
    ["Profile '%s' loaded. |cffffff00/reload|r recommended so all modules use the new settings."] = "Perfil “%s” cargado. Se recomienda |cffffff00/reload|r para que todos los módulos usen los ajustes nuevos.",
