    ["Max Camera Distance"] = "Distancia máxima de cámara",
    ["Maximum camera distance (CVar cameraDistanceMaxZoomFactor)."] = "Distancia máxima de la cámara (CVar cameraDistanceMaxZoomFactor).",
    ["Show Minimap Button"] = "Mostrar botón del minimapa",
    ["Toggle the VuloClassicUI button on the minimap."] = "Activa o desactiva el botón de VuloClassicUI en el minimapa.",
    ["Show CPU Usage in Header"] = "Mostrar el uso de CPU en la cabecera",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "Muestra el uso total de CPU de todos los addons activos (más la parte propia de VuloClassicUI) en la parte superior de la cabecera de configuración.\\n\\n|cffaaaaaaRequiere /reload tras cambiarlo.\\n\\nNota: activa el CVar scriptProfile de WoW, que cuesta un ~3-5% en rendimiento; ese es el precio de que WoW recopile estos datos.|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "Perfilado de scripts cambiado. Se requiere /reload para que se actualice el indicador de CPU.",
    ["Reload now"] = "Recargar ahora",
    ["Later"] = "Más tarde",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "Muestra un botón en el minimapa para abrir VuloClassicUI rápidamente. Mayús+arrastrar mueve el botón.",
    ["UI is not loaded yet."] = "La interfaz aún no está cargada.",
    ["|cffffffffLeft click:|r Open options"] = "|cffffffffClic izquierdo:|r abrir opciones",
    ["|cffffffffRight click:|r Quick module selection"] = "|cffffffffClic derecho:|r selección rápida de módulos",
    ["|cffffffffShift+drag:|r Move button"] = "|cffffffffShift+arrastrar:|r mover el botón",
    ["Open Options"] = "Abrir opciones",
    ["Show button on minimap"] = "Mostrar el botón en el minimapa",
    ["If off, the button is completely hidden."] = "Si está desactivado, el botón se oculta por completo.",
    ["Distance from center"] = "Distancia desde el centro",
    ["Angle (degrees)"] = "Ángulo (grados)",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "Consejo: también puedes mover el botón directamente en el minimapa; mantén Mayús y arrástralo a la posición deseada.",
    ["Font Bars"] = "Fuentes de barras",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "Tamaños de fuente más pequeños en las barras de salud y maná de jugador/objetivo/mascota; opcionalmente oculta TargetFrameBackground.",
    ["Health Bar Text"] = "Texto de la barra de salud",
    ["Font size on health bars (Player/Target/Pet)."] = "Tamaño de fuente en las barras de salud (jugador/objetivo/mascota).",
    ["Power Bar Text"] = "Texto de la barra de poder",
    ["Font size on mana/power bars."] = "Tamaño de fuente en las barras de maná/poder.",
    ["Pet Combat Feedback Text"] = "Texto de combate de la mascota",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "Tamaño de fuente de “Daño”, “Esquiva”, “Fallo” en la mascota.",
    ["Only affect Player/Target/Pet bars"] = "Afectar solo a las barras de jugador/objetivo/mascota",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "Si está desactivado: todas las TextStatusBars de la interfaz se sobrescriben con los tamaños de arriba (puede interferir con otros addons).",
    ["Hide TargetFrame background"] = "Ocultar el fondo de TargetFrame",
    ["Permanently hides the dark background element of the TargetFrame."] = "Oculta permanentemente el elemento de fondo oscuro de TargetFrame.",
    ["Target Frame"] = "Marco de objetivo",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaaAñade los extras modernos de los marcos de objetivo/foco que faltan en la interfaz predeterminada de Anniversary: todo cosmético, sin corromper el código protegido.|r",
    ["Numeric threat %"] = "Amenaza numérica en %",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "Muestra tu porcentaje de amenaza sobre el objetivo (y el foco) encima del marco, coloreado según el estado de amenaza.",
    ["Threat glow"] = "Resplandor de amenaza",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "Ilumina el marco de objetivo (y de foco) en amarillo/naranja/rojo a medida que sube tu amenaza.",
    ["Rare-Elite border"] = "Borde de Raro Élite",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "Muestra el borde alado de dragón plateado de Raro Élite en los PNJ raros élite.",
    ["Class icon on player targets"] = "Icono de clase en objetivos jugadores",
    ["Shows the target's class crest on the frame when you target a player."] = "Muestra el emblema de clase del objetivo en el marco cuando seleccionas a un jugador.",
    ["Also apply to the Focus frame"] = "Aplicar también al marco de foco",
    ["Health"] = "Salud",
    ["Show real NPC health"] = "Mostrar la salud real de los PNJ",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "Muestra el valor real de salud en los PNJ en lugar del porcentaje ofuscado (los jugadores enemigos siguen en %).",
    ["Player Castbar"] = "Barra de lanzamiento del jugador",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "Barra de lanzamiento del jugador con dos modos: Original (barra de Blizzard ampliada) o Barra personalizada (estilo VUI).",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRA DE LANZAMIENTO|r\\n|cffaaaaaaArrastra o usa las flechas|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "Posición de la barra de lanzamiento: x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cffTortura mental|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Movimiento de la barra de lanzamiento activo. |cff9b6cffArrastra la caja morada|r o usa las |cff9b6cffteclas de flecha|r (MAYÚS = 5 px). Vuelve a pulsar “Desbloquear / Probar” para terminar.",
    ["Castbar mover disabled."] = "Movimiento de la barra de lanzamiento desactivado.",
    ["Castbar Variant"] = "Variante de barra de lanzamiento",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "Cambia entre Original (barra de Blizzard ampliada) y Barra personalizada (estilo VUI con icono y nombre del hechizo bajo la barra).",
    ["Original (Blizzard bar extended)"] = "Original (barra de Blizzard ampliada)",
    ["Custom Castbar (VUI style)"] = "Barra personalizada (estilo VUI)",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "Modo de barra de lanzamiento cambiado a |cff9b6cffOriginal|r. Se recomienda |cffffff00/reload|r para que la barra predeterminada vuelva a funcionar con normalidad.",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "Modo de barra de lanzamiento cambiado a |cff9b6cffestilo VUI|r.",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaaCambio de modo: puede que se necesite un /reload después de cambiar para que la barra predeterminada vuelva a funcionar con normalidad.|r",
    ["Show spell name"] = "Mostrar el nombre del hechizo",
    ["Show cast timer"] = "Mostrar el temporizador de lanzamiento",
    ["Show channel ticks"] = "Mostrar los pulsos de canalización",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "Muestra líneas verticales en los puntos de pulso (Tortura mental, Drenar alma, Fuego infernal, etc.)",
    ["Show clip window"] = "Mostrar la ventana de corte",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "Sombrea tu latencia al final de la barra: en canalizaciones, el momento de relanzar sin perder el último pulso; en lanzamientos, la ventana de cola de hechizos en la que ya se puede pulsar el siguiente.",
    ["Timer format"] = "Formato del temporizador",
    ["Remaining / total (1.5 / 2.0)"] = "Restante / total (1.5 / 2.0)",
    ["Remaining only (1.5)"] = "Solo restante (1.5)",
    ["Whole seconds (2)"] = "Segundos enteros (2)",
    ["Show pushback"] = "Mostrar el retroceso",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "Muestra brevemente en rojo, encima de la barra, el tiempo perdido por retroceso de lanzamiento.",
    ["Merge crafting casts"] = "Unificar lanzamientos de fabricación",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "Al fabricar varios objetos seguidos, la barra muestra un contador como 3/20 en lugar de lanzamientos sueltos.",
    ["Fill color"] = "Color de relleno",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "Las texturas de barra son el arte clásico amarillo/verde. El color de acento o el de clase tiñen en su lugar una barra neutra.",
    ["Bar textures (yellow/green)"] = "Texturas de barra (amarillo/verde)",
    ["Accent color"] = "Color de acento",
    ["VUI Style: Position & Size"] = "Estilo VUI: posición y tamaño",
    ["Unlock / Test"] = "Desbloquear / Probar",
    ["Center Position"] = "Posición del centro",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaaConsejo: mantén |cffffffffSHIFT|r y arrastra la barra de lanzamiento con el botón izquierdo durante un lanzamiento para moverla. O usa “Desbloquear / Probar” para tener una barra de prueba permanente y colocarla.|r",
    ["Show icon"] = "Mostrar el icono",
    ["Icon Size"] = "Tamaño del icono",
    ["Icon X Offset"] = "Desplazamiento X del icono",
    ["Icon Y Offset"] = "Desplazamiento Y del icono",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "Mueve el icono horizontalmente. Negativo = izquierda, positivo = derecha.",
    ["Moves the icon vertically. Positive = up, negative = down."] = "Mueve el icono verticalmente. Positivo = arriba, negativo = abajo.",
    ["Test only available in 'Custom Castbar' mode."] = "La prueba solo está disponible en el modo “Barra personalizada”.",
    ["Cooldown Pulse"] = "Pulso de reutilización",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center."] = "Muestra el icono de un tiempo de reutilización que acaba de terminar como una breve animación pulsante en el centro de la pantalla.",
    ["Test Spell"] = "Hechizo de prueba",
    ["Cooldown Pulse position reset."] = "Posición del pulso de reutilización restablecida.",
    ["Test Pulse"] = "Probar pulso",
    ["Plays a test animation."] = "Reproduce una animación de prueba.",
    ["Reset Position"] = "Restablecer posición",
    ["Max Opacity"] = "Opacidad máxima",
    ["Animation Scale"] = "Escala de la animación",
    ["Fade-In Time (s)"] = "Tiempo de aparición (s)",
    ["Hold Time (s)"] = "Tiempo de permanencia (s)",
    ["Fade-Out Time (s)"] = "Tiempo de desvanecimiento (s)",
    ["Show Before Available (s)"] = "Mostrar antes de estar listo (s)",
    ["Triggers the animation X seconds BEFORE the cooldown expires. 0 = exactly at cooldown end."] = "Activa la animación X segundos ANTES de que termine el tiempo de reutilización. 0 = justo al terminar.",
    ["Spell Filter"] = "Filtro de hechizos",
    ["Show spell names"] = "Mostrar los nombres de los hechizos",
    ["Shows the name of the spell under the icon."] = "Muestra el nombre del hechizo debajo del icono.",
    ["Invert filter (whitelist instead of blacklist)"] = "Invertir el filtro (lista blanca en vez de lista negra)",
    ["Off: List = ignored spells. On: List = show ONLY these spells."] = "Desactivado: la lista = hechizos ignorados. Activado: la lista = mostrar SOLO estos hechizos.",
    ["Spell List (comma-separated)"] = "Lista de hechizos (separados por comas)",
    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "Nombres de hechizo exactamente como aparecen en el juego, separados por comas. También funcionan los ID de hechizo.",
    ["Arena Frames"] = "Marcos de arena",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "Mejora los marcos de enemigos de arena: mover/escalar, colores de clase, iconos de clase, reutilización del abalorio JcJ, seguimiento de DR, barra de lanzamiento y disposición con arrastrar y soltar.",
    ["|cffff5555ArenaFrames submodule error:|r %s"] = "|cffff5555Error del submódulo ArenaFrames:|r %s",
    ["|cffff5555Arena submodule OnEnable error:|r %s"] = "|cffff5555Error en OnEnable del submódulo de arena:|r %s",
    ["Layout"] = "Disposición",
    ["Class Color"] = "Color de clase",
    ["PvP Trinket"] = "Abalorio JcJ",
    ["DR Tracker"] = "Rastreador de DR",
    ["Castbar"] = "Barra de lanzamiento",
    ["ArenaPlayer"] = "ArenaPlayer",
    ["Reset position"] = "Restablecer posición",
    ["Position reset."] = "Posición restablecida.",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "En modo desbloqueo aparece una capa morada sobre los marcos. Clic + arrastrar para mover, rueda del ratón para escalar.",
    ["Layout (Order)"] = "Disposición (orden)",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "Orden de los marcos de arena. Usa arriba/abajo para mover las ranuras 1-5.",
    ["|cff9b6cff%d.|r  Arena Slot %d"] = "|cff9b6cff%d.|r  Ranura de arena %d",
    ["Move up"] = "Subir",
    ["Move down"] = "Bajar",
    ["Spacing between frames"] = "Espaciado entre marcos",
    ["Grow direction"] = "Dirección de crecimiento",
    ["Downward"] = "Hacia abajo",
    ["Upward"] = "Hacia arriba",
    ["Reset order"] = "Restablecer el orden",
    ["Class Visuals"] = "Aspecto de clase",
    ["Class-colored health bars"] = "Barras de salud con color de clase",
    ["Colors the health bar in the player's class color."] = "Colorea la barra de salud con el color de clase del jugador.",
    ["Class-colored name"] = "Nombre con color de clase",
    ["Class icon instead of portrait"] = "Icono de clase en lugar del retrato",
    ["Replaces the 3D portrait with a class symbol."] = "Sustituye el retrato 3D por un símbolo de clase.",
    ["PvP Trinket Tracker"] = "Rastreador de abalorio JcJ",
    ["Show PvP trinket cooldown"] = "Mostrar el tiempo de reutilización del abalorio JcJ",
    ["Shows an icon with cooldown spiral next to the arena frame when the opponent used their PvP trinket."] = "Muestra un icono con espiral de reutilización junto al marco de arena cuando el rival usa su abalorio JcJ.",
    ["Icon size"] = "Tamaño del icono",
    ["Left of frame"] = "A la izquierda del marco",
    ["Right of frame"] = "A la derecha del marco",
    ["Offset X"] = "Desplazamiento X",
    ["Offset Y"] = "Desplazamiento Y",
    ["Diminishing Returns Tracker"] = "Rastreador de reducción de efectos (DR)",
    ["Shows icons next to each arena frame for active DR categories (Stun, Fear, Polymorph etc.) with color indicator: |cff00ff00green|r = full, |cffffff00yellow|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000red|r = immune."] = "Muestra iconos junto a cada marco de arena para las categorías de DR activas (aturdimiento, miedo, polimorfia, etc.) con indicador de color: |cff00ff00verde|r = completo, |cffffff00amarillo|r = 1/2, |cffff8000naranja|r = 1/4, |cffff0000rojo|r = inmune.",
    ["Enable DR tracking"] = "Activar el seguimiento de DR",
    ["INTERRUPTED"] = "INTERRUMPIDO",
    ["Castbar for arena opponents"] = "Barra de lanzamiento de los rivales de arena",
    ["Shows a castbar below the frame when the opponent casts or channels."] = "Muestra una barra de lanzamiento bajo el marco cuando el rival lanza o canaliza un hechizo.",
    ["Collection of simple quality-of-life toggles: auto-accept (quest, res, summon), auto-sell, repair, hide UI spam, text sizes."] = "Conjunto de opciones sencillas de comodidad: aceptación automática (misión, resurrección, invocación), venta automática, reparación, ocultar avisos de la interfaz y tamaños de texto.",
    ["Auto-sold: %d items, +%s"] = "Venta automática: %d objetos, +%s",
    ["Auto-sold: %d items."] = "Venta automática: %d objetos.",
    ["Repair exceeds gold (%d < %d)."] = "La reparación supera tu oro (%d < %d).",
    ["Auto-repaired (%dg %ds)."] = "Reparado automáticamente (%do %dp).",
    ["MAX"] = "MÁX",
    ["General - Auto Actions"] = "General - Acciones automáticas",
    ["|cffaaaaaaSimple on/off switches for common QoL actions. Take effect immediately, no /reload needed.|r"] = "|cffaaaaaaInterruptores sencillos para acciones de comodidad habituales. Se aplican al instante, sin necesidad de /reload.|r",
    ["Auto-accept quests"] = "Aceptar misiones automáticamente",
    ["Automatically accepts quests when clicking an NPC."] = "Acepta automáticamente las misiones al hacer clic en un PNJ.",
    ["Auto-turn in quests"] = "Entregar misiones automáticamente",
    ["Automatically completes finished quests. Waits for user choice on multi-reward quests (no auto-pick)."] = "Completa automáticamente las misiones terminadas. Espera tu elección en las misiones con varias recompensas (sin selección automática).",
    ["Auto-accept resurrect"] = "Aceptar resurrecciones automáticamente",
    ["Automatically clicks 'Accept' on resurrect popups (not in combat)."] = "Pulsa automáticamente “Aceptar” en las ventanas de resurrección (no en combate).",
    ["Auto-accept summon"] = "Aceptar invocaciones automáticamente",
    ["Automatically clicks 'Accept' on warlock/stone summon popups."] = "Pulsa automáticamente “Aceptar” en las ventanas de invocación de brujo/piedra.",
    ["Auto-release spirit in PvP/Arena"] = "Liberar espíritu automáticamente en JcJ/arena",
    ["Releases instantly on death in BG or arena."] = "Libera el espíritu al instante al morir en campo de batalla o arena.",
    ["Auto-sell junk (grey)"] = "Vender basura automáticamente (gris)",
    ["Sells all grey items when opening a vendor. Earnings shown in chat."] = "Vende todos los objetos grises al abrir un vendedor. Las ganancias se muestran en el chat.",
    ["Auto-repair"] = "Reparación automática",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "Repara todo el equipo en el vendedor si tienes oro suficiente.",
    ["Stack-split popup: MAX button"] = "Ventana de dividir montón: botón MÁX",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "Añade un botón “MÁX” a la ventana de cantidad. Clic = comprar el montón completo (en el vendedor) o dividirlo por completo (objetos de la bolsa).",
    ["Stack-split popup: VuloUI look"] = "Ventana de dividir montón: aspecto VuloUI",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "Aplica el aspecto del addon a la ventana de cantidad (comprar/dividir montones): panel oscuro, botones y flechas limpios. Desactivarlo requiere un /reload.",
    ["Hide UI error messages"] = "Ocultar los mensajes de error de la interfaz",
    ["Hides the red error messages in the screen center."] = "Oculta los mensajes de error rojos del centro de la pantalla.",
    ["Hide zone text"] = "Ocultar el nombre de zona",
    ["Hides the large zone name when entering new areas."] = "Oculta el nombre grande de la zona al entrar en zonas nuevas.",
    ["Hide level numbers on portrait"] = "Ocultar el nivel en el retrato",
    ["Hides the level display on the Player/Target/Pet portrait."] = "Oculta la indicación de nivel en el retrato de jugador/objetivo/mascota.",
    ["Hide keybind text on action buttons"] = "Ocultar el texto de atajos en los botones de acción",
    ["Hides the small key labels (1, F1, etc.) on the action buttons."] = "Oculta las etiquetas pequeñas de tecla (1, F1, etc.) en los botones de acción.",
    ["Hide macro/spell names on action buttons"] = "Ocultar los nombres de macro/hechizo en los botones de acción",
    ["Hides the text labels under the action buttons."] = "Oculta las etiquetas de texto bajo los botones de acción.",
    ["Hide stack/charge numbers on action buttons"] = "Ocultar los números de montón/cargas en los botones de acción",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "Oculta los recuadros pequeños con números de la esquina superior derecha (montones de objetos, cargas, segundos de reutilización en tiempos largos).",
    ["Hide raid group labels"] = "Ocultar las etiquetas de grupo de banda",
    ["Hides the 'Group 1'/'Group 2' labels above the compact raid frames."] = "Oculta las etiquetas “Grupo 1”/“Grupo 2” sobre los marcos compactos de banda.",
    ["Mail Text Size"] = "Tamaño del texto de correo",
    ["Font size in mail body (opened + sent mail)."] = "Tamaño de fuente en el cuerpo del correo (correo abierto y enviado).",
    ["Quest Text Size"] = "Tamaño del texto de misión",
    ["Font size in quest descriptions + quest log."] = "Tamaño de fuente en las descripciones de misión y el registro de misiones.",
    ["Book Text Size"] = "Tamaño del texto de libros",
    ["Font size in readable books and letters from item text."] = "Tamaño de fuente en libros y cartas legibles a partir del texto del objeto.",
    ["Queue Timer"] = "Temporizador de cola",
    ["Shows a countdown on the PvP/PvE queue pop dialog. Optional sound warning at 5 seconds."] = "Muestra una cuenta atrás en la ventana de aviso de cola JcJ/JcE. Aviso sonoro opcional a los 5 segundos.",
    ["Queue expires in"] = "La cola expira en",
    ["|cff00c0ffQueueTimer:|r "] = "|cff00c0ffQueueTimer:|r ",
    ["Dungeon queue popped instantly!"] = "¡La cola de mazmorra saltó al instante!",
    ["Dungeon queue popped after %s"] = "La cola de mazmorra saltó tras %s",
    ["Dungeon queue popped."] = "La cola de mazmorra saltó.",
    ["Queue popped instantly!"] = "¡La cola saltó al instante!",
    ["Queue popped after %s"] = "La cola saltó tras %s",
    ["Sound on queue pop"] = "Sonido al saltar la cola",
    ["Plays a sound as soon as the queue pops."] = "Reproduce un sonido en cuanto salta la cola.",
    ["5-second warning"] = "Aviso a los 5 segundos",
    ["Plays 3 quick sounds when only 5 seconds remain to accept."] = "Reproduce 3 sonidos rápidos cuando solo quedan 5 segundos para aceptar.",
    ["Hide other timers (e.g. BigWigs)"] = "Ocultar otros temporizadores (p. ej. BigWigs)",
    ["Hides foreign StatusBars on the LFG ready popup so only our timer is visible."] = "Oculta las StatusBars ajenas en la ventana de aceptación de LFG para que solo se vea nuestro temporizador.",
    ["Tooltip IDs"] = "ID en tooltips",
    ["Shows SpellID, ItemID, NPC ID and many other IDs in tooltips (based on idTip by silverwind)."] = "Muestra SpellID, ItemID, ID de PNJ y muchos otros ID en los tooltips (basado en idTip de silverwind).",
    ["|cff9b6cffTalents:|r "] = "|cff9b6cffTalentos:|r ",
    ["|cff9b6cffiLvL:|r %d"] = "|cff9b6cffNvO:|r %d",
    ["  |cff888888(off by default)|r"] = "  |cff888888(desactivado por defecto)|r",
    ["Shows %s in tooltips."] = "Muestra %s en los tooltips.",
    ["Shows additional ID lines in tooltips, e.g. spell, item or NPC IDs."] = "Muestra líneas de ID adicionales en los tooltips, p. ej. ID de hechizo, objeto o PNJ.",
    ["Quick Select"] = "Selección rápida",
    ["All on"] = "Activar todo",
    ["All off"] = "Desactivar todo",
    ["Defaults"] = "Predeterminados",
    ["Player Tooltip (Inspect-based)"] = "Tooltip de jugador (basado en inspección)",
    ["|cffaaaaaaWhen you hover over a player, their average iLvL + talent distribution (e.g. 14/0/47) is shown in the tooltip. Data is cached 60s per player, inspect throttle 1/s.|r"] = "|cffaaaaaaAl pasar el cursor sobre un jugador se muestra en el tooltip su nivel de objeto medio + la distribución de talentos (p. ej. 14/0/47). Los datos se guardan 60 s por jugador, con un límite de inspección de 1/s.|r",
    ["Show average iLvL"] = "Mostrar el nivel de objeto medio",
    ["Show talent distribution (e.g. 14/0/47)"] = "Mostrar la distribución de talentos (p. ej. 14/0/47)",
    ["ID Types"] = "Tipos de ID",
    ["Auto Item Buy"] = "Compra automática de objetos",
    ["Automatically buys configured items at configured vendors. Shift when opening the merchant window = emergency stop."] = "Compra automáticamente los objetos configurados en los vendedores configurados. Mantén Mayús al abrir la ventana del vendedor = parada de emergencia.",
    ["|cffffd200[AutoItemBuy]|r "] = "|cffffd200[AutoItemBuy]|r ",
    ["Buying: "] = "Comprando: ",
    ["Close merchant window after purchase"] = "Cerrar la ventana del vendedor tras la compra",
    ["Closes the merchant window automatically ~0.2s after purchase."] = "Cierra la ventana del vendedor automáticamente ~0,2 s después de la compra.",
    ["Chat message on each purchase"] = "Mensaje de chat en cada compra",
    ["|cffaaaaaaTip: Hold SHIFT when opening the merchant window to skip automatic purchase once.|r"] = "|cffaaaaaaConsejo: mantén Mayús al abrir la ventana del vendedor para omitir la compra automática una vez.|r",
    ["Add Vendor"] = "Añadir vendedor",
    ["Vendor Name"] = "Nombre del vendedor",
    ["Add"] = "Añadir",
    ["|cffff5555Please enter a vendor name.|r"] = "|cffff5555Introduce un nombre de vendedor.|r",
    ["|cffff5555Vendor '%s' already exists.|r"] = "|cffff5555El vendedor “%s” ya existe.|r",
    ["Vendor '%s' added."] = "Vendedor “%s” añadido.",
    ["Manage Vendors"] = "Gestionar vendedores",
    ["|cffaaaaaaNo vendors added yet. Add a vendor above, then select it here to configure items.|r"] = "|cffaaaaaaAún no hay vendedores añadidos. Añade un vendedor arriba y selecciónalo aquí para configurar objetos.|r",
    ["Currently selected vendor"] = "Vendedor seleccionado actualmente",
    ["Delete this vendor"] = "Eliminar este vendedor",
    ["Vendor '%s' removed."] = "Vendedor “%s” eliminado.",
    ["Items at '%s'"] = "Objetos en “%s”",
    ["Anchor to window..."] = "Anclar a ventana...",
    ["WIDTH LIKE"] = "ANCHURA COMO",
    ["HEIGHT LIKE"] = "ALTURA COMO",
    ["Takes its width from another window and keeps it."] = "Toma su anchura de otra ventana y la mantiene.",
    ["Takes its height from another window and keeps it."] = "Toma su altura de otra ventana y la mantiene.",
    ["This window sets its own size - the match will not stick."] = "Esta ventana define su propio tamaño: la coincidencia no se mantendrá.",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Hold Shift while dragging to lock one axis. Shift+right-click hides a box that is in the way."] = "Arrastra un recuadro, o pásale el ratón por encima y usa las flechas (Mayús = 5 px). Mantén Mayús al arrastrar para bloquear un eje. Mayús+clic derecho oculta un recuadro que estorbe.",
    ["Then click any window to anchor this one to it."] = "Después haz clic en cualquier ventana para anclar esta a ella.",
    ["Click a window to anchor it (right-click to cancel)."] = "Haz clic en una ventana para anclarla (clic derecho para cancelar).",
    ["ANCHOR SIDE"] = "LADO DE ANCLAJE",
    ["Centered"] = "Centrado",
    ["Top of"] = "Encima de",
    ["Bottom of"] = "Debajo de",
    ["Discard"] = "Descartar",
    ["Pin this frame to a screen edge/corner so it stays put across resolution changes. Off keeps it centred."] = "Fija este marco a un borde o esquina de la pantalla para que no se mueva al cambiar de resolución. Desactivado lo mantiene centrado.",
    ["Leave this window unlocked so you can still drag it after closing Edit Mode. Stays unlocked through /reload."] = "Deja esta ventana desbloqueada para poder seguir arrastrándola tras cerrar el modo Edición. Sigue desbloqueada tras un /reload.",
    ["LAYOUTS"] = "DISPOSICIONES",
    ["Layouts"] = "Disposiciones",
    ["SAVED"] = "GUARDADAS",
    ["No layouts saved"] = "No hay disposiciones guardadas",
    ["No layout selected."] = "Ninguna disposición seleccionada.",
    ["Save, load, export and import named window layouts."] = "Guarda, carga, exporta e importa disposiciones de ventanas con nombre.",
    ["Save your window arrangement, then load or share it any time."] = "Guarda tu distribución de ventanas y cárgala o compártela cuando quieras.",
    ["Pick a saved layout to load, delete or export."] = "Elige una disposición guardada para cargar, borrar o exportar.",
    ["Save current as..."] = "Guardar actual como...",
    ["Name for this layout:"] = "Nombre de esta disposición:",
    ["Delete layout '%s'?"] = "¿Borrar la disposición “%s”?",
    ["Layout '%s' saved."] = "Disposición “%s” guardada.",
    ["Applied layout '%s' (%d frames)."] = "Disposición “%s” aplicada (%d marcos).",
    ["Layout '%s' imported."] = "Disposición “%s” importada.",
    ["Import"] = "Importar",
    ["Export"] = "Exportar",
    ["Imported"] = "Importada",
    ["Import failed (%s)."] = "Error al importar (%s).",
    ["Paste a layout string and confirm:"] = "Pega una cadena de disposición y confirma:",
    ["Copy this string (Ctrl+A, Ctrl+C):"] = "Copia esta cadena (Ctrl+A, Ctrl+C):",
    ["Move it in the unified Edit Mode (/vedit)."] = "Muévelo en el modo Edición unificado (/vedit).",
    ["Drag the combat-text box in the unified Edit Mode (/vedit)."] = "Arrastra el recuadro del texto de combate en el modo Edición unificado (/vedit).",
    ["|cffffffffARENA FRAMES|r"] = "|cffffffffMARCOS DE ARENA|r",
    ["|cff44ff44Edit Mode is ON.|r Close this window to reach the boxes."] = "|cff44ff44El modo Edición está ACTIVO.|r Cierra esta ventana para acceder a los recuadros.",
    ["|cffaaaaaaMove everything in one editor: VuloUI windows and Blizzard's frames (player, target, focus, minimap, buffs). They snap to a shared grid.|r"] = "|cffaaaaaaMueve todo en un solo editor: las ventanas de VuloUI y los marcos de Blizzard (jugador, objetivo, foco, minimapa, beneficios). Se ajustan a una cuadrícula común.|r",
    ["|cff888888• Drag a purple box to move that frame.|n• Hover a box, then arrow keys fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/vedit|r toggles Edit Mode too.|r"] = "|cff888888• Arrastra un recuadro morado para mover ese marco.|n• Pasa el ratón sobre un recuadro y ajusta con las flechas (MAYÚS = 5 px).|n• Clic derecho en un recuadro para X / Y exactas.|n• |cffffffff/vedit|r también alterna el modo Edición.|r",
    ["Enable 'Target and Focus' in Blizzard's Edit Mode settings, then /reload, so VuloUI can move the target/focus frame."] = "Activa “Objetivo y foco” en los ajustes del modo Edición de Blizzard y luego haz /reload para que VuloUI pueda mover el marco de objetivo/foco.",
    ["Dark Mode"] = "Modo oscuro",
    ["Desaturate (greyscale)"] = "Desaturar (escala de grises)",
    ["Strips the colour out of the artwork before tinting, for a true greyscale look. Off keeps a hint of the original hue."] = "Quita el color de las texturas antes de tintarlas, para un gris puro. Desactivado conserva un matiz del tono original.",
    ["Tint colour"] = "Color de tinte",
    ["Unit frames"] = "Marcos de unidad",
    ["Player, target, focus, pet and party frame borders."] = "Bordes de los marcos de jugador, objetivo, foco, mascota y grupo.",
    ["Minimap border, compass, zoom and tracking buttons."] = "Borde del minimapa, brújula, zoom y botones de rastreo.",
    ["Action bar artwork"] = "Texturas de la barra de acción",
    ["The gryphons and the metal action-bar background."] = "Los grifos y el fondo metálico de la barra de acción.",
    ["Action button borders"] = "Bordes de los botones de acción",
    ["Also tints the border ring around every action button. Optional — leave off if it looks too flat."] = "También tinta el anillo del borde de cada botón de acción. Opcional: déjalo desactivado si queda demasiado plano.",
    ["Bag slots"] = "Ranuras de bolsa",
    ["Tints the backpack, bag and keyring button borders."] = "Tinta los bordes de los botones de la mochila, las bolsas y el llavero.",
    ["|cffaaaaaaNote: if the Player & Target Frame module's |cffffffffThreat glow|r is on, threat colouring takes over the target/focus border while you have aggro — that's intended.|r"] = "|cffaaaaaaNota: si el |cffffffffResplandor de amenaza|r del módulo Marco de jugador y objetivo está activo, el color de amenaza toma el control del borde de objetivo/foco mientras tengas aggro; es intencionado.|r",
    ["Chat"] = "Chat",
    ["Polishes Blizzard's chat: a dark panel with an icon sidebar, timestamps, class-coloured names, clickable links, dark tabs, idle fade and history that survives a /reload. Every part is optional."] = "Pule el chat de Blizzard: un panel oscuro con barra lateral de iconos, marcas de tiempo, nombres con color de clase, enlaces clicables, pestañas oscuras, desvanecido por inactividad e historial que sobrevive a un /reload. Cada parte es opcional.",
    ["|cffaaaaaaPolishes Blizzard's own chat — nothing is replaced, so it stays light and compatible. Every option below is independent.|r"] = "|cffaaaaaaPule el propio chat de Blizzard: no se sustituye nada, así que sigue siendo ligero y compatible. Cada opción de abajo es independiente.|r",
    ["Timestamps"] = "Marcas de tiempo",
    ["Show timestamps"] = "Mostrar marcas de tiempo",
    ["Prefixes each line with the time, using the game's own timestamp setting."] = "Antepone la hora a cada línea, usando el propio ajuste de marca de tiempo del juego.",
    ["Time format"] = "Formato de hora",
    ["Names & links"] = "Nombres y enlaces",
    ["Class-coloured names"] = "Nombres con color de clase",
    ["Colours player names by their class in say, party, raid, guild, whisper and channels."] = "Colorea los nombres de jugador según su clase en decir, grupo, banda, hermandad, susurro y canales.",
    ["Clickable links"] = "Enlaces clicables",
    ["Turns web links into clickable links that open a copy box."] = "Convierte los enlaces web en enlaces clicables que abren un cuadro para copiar.",
    ["Style chat tabs"] = "Estilizar las pestañas del chat",
    ["Flat dark tab background with an accent underline on the active tab."] = "Fondo de pestaña oscuro y plano con una línea de acento bajo la pestaña activa.",
    ["Tab label size"] = "Tamaño del texto de pestaña",
    ["One uniform font size for every chat tab label."] = "Un tamaño de fuente uniforme para el texto de todas las pestañas del chat.",
    ["Chat font size (0 = Blizzard)"] = "Tamaño de fuente del chat (0 = Blizzard)",
    ["Scrollback (lines per window)"] = "Historial visible (líneas por ventana)",
    ["How many lines each chat window keeps for scrolling (Blizzard default: 128). More lines use a little more memory; changing this clears the currently shown lines once."] = "Cuántas líneas guarda cada ventana de chat para desplazarse (por defecto de Blizzard: 128). Más líneas usan algo más de memoria; cambiar esto borra una vez las líneas mostradas.",
    ["Item levels in chat links"] = "Niveles de objeto en los enlaces del chat",
    ["Appends the item level to equipment links: [Sword] becomes [Sword (45)]."] = "Añade el nivel de objeto a los enlaces de equipo: [Espada] pasa a ser [Espada (45)].",
    ["Panel opacity (%)"] = "Opacidad del panel (%)",
    ["Transparency of the dark background panel behind the chat."] = "Transparencia del panel de fondo oscuro que hay tras el chat.",
    ["Indent wrapped lines"] = "Sangrar las líneas continuadas",
    ["Wraps long messages with continuation lines indented under the message start, for a cleaner column."] = "Ajusta los mensajes largos con las líneas de continuación sangradas bajo el inicio del mensaje, para una columna más limpia.",
    ["Idle fade"] = "Desvanecido por inactividad",
    ["Fade chat when idle"] = "Desvanecer el chat al estar inactivo",
    ["Dims the chat after a while with no activity. A new message, hovering it or typing brings it back."] = "Atenúa el chat tras un rato sin actividad. Un mensaje nuevo, pasar el ratón por encima o escribir lo devuelve.",
    ["Idle delay (seconds)"] = "Retardo de inactividad (segundos)",
    ["Faded opacity (%)"] = "Opacidad atenuada (%)",
    ["History"] = "Historial",
    ["Keep chat history"] = "Guardar el historial del chat",
    ["Remembers recent chat per character and re-shows it after a /reload."] = "Recuerda el chat reciente por personaje y lo vuelve a mostrar tras un /reload.",
    ["Lines to keep"] = "Líneas a guardar",
    ["Clear history"] = "Borrar historial",
    ["Chat history cleared."] = "Historial del chat borrado.",
    ["--- chat history ---"] = "--- historial de chat ---",
    ["Copy"] = "Copiar",
    ["Copy chat"] = "Copiar chat",
    ["Link"] = "Enlace",
    ["Ctrl+A to select all, Ctrl+C to copy."] = "Ctrl+A para seleccionar todo, Ctrl+C para copiar.",
    ["Scroll to bottom"] = "Desplazar al final",
    ["|cffaaaaaaThe panel, input and sidebar reposition Blizzard's chat. Turning them off here hides them immediately; a |cffffffff/reload|r restores the exact original positions.|r"] = "|cffaaaaaaEl panel, la línea de entrada y la barra lateral reposicionan el chat de Blizzard. Desactivarlos aquí los oculta al instante; un |cffffffff/reload|r restaura las posiciones originales exactas.|r",
    ["Dark background panel"] = "Panel de fondo oscuro",
    ["A dark panel behind the chat and input line, with the tab bar above it — one cohesive block."] = "Un panel oscuro tras el chat y la línea de entrada, con la barra de pestañas encima: un bloque cohesionado.",
    ["Top fade"] = "Desvanecido superior",
    ["Fades old lines into the panel at the top edge of the chat."] = "Desvanece las líneas antiguas hacia el panel en el borde superior del chat.",
    ["Icon sidebar"] = "Barra lateral de iconos",
    ["A slim bar left of the chat with copy, settings, new-window and scroll-to-bottom icons."] = "Una barra estrecha a la izquierda del chat con iconos de copiar, ajustes, ventana nueva e ir al final.",
    ["Show online friends"] = "Mostrar amigos conectados",
    ["Show how many friends are online at the top of the sidebar; click the icon to open the friends list."] = "Muestra cuántos amigos están conectados en la parte superior de la barra lateral; haz clic en el icono para abrir la lista de amigos.",
    ["Friends online"] = "Amigos conectados",
    ["New chat window"] = "Ventana de chat nueva",
    ["Create new chat window"] = "Crear una ventana de chat nueva",
    ["This client can't create extra chat windows."] = "Este cliente no puede crear ventanas de chat adicionales.",
    ["Use VuloUI font"] = "Usar la fuente de VuloUI",
    ["Applies the VuloUI font to the chat text, tabs and input line."] = "Aplica la fuente de VuloUI al texto, las pestañas y la línea de entrada del chat.",
    ["Copy button (standalone)"] = "Botón de copiar (independiente)",
    ["A small copy button above the chat. Off by default since the sidebar already has a copy icon; turn the sidebar off to use this instead."] = "Un pequeño botón de copiar sobre el chat. Desactivado por defecto porque la barra lateral ya tiene un icono de copiar; desactiva la barra lateral para usar este en su lugar.",
    ["Bags"] = "Bolsas",
    ["Inventory"] = "Inventario",
    ["Items"] = "Objetos",
    ["Hide"] = "Ocultar",
    ["Show"] = "Mostrar",
    ["Color item levels by quality"] = "Colorear los niveles de objeto por calidad",
    ["Tints the item level number in the item's quality color instead of plain white."] = "Tinta el número del nivel de objeto con el color de calidad del objeto en lugar de blanco liso.",
    ["%d free"] = "%d libres",
    ["|cffaaaaaaOne window for all your bags. Press your bag key (default B) to open it. Type in the search box to find items; click the sort button to tidy up. At a banker, your bank opens in a matching window.|r"] = "|cffaaaaaaUna sola ventana para todas tus bolsas. Pulsa tu tecla de bolsa (B por defecto) para abrirla. Escribe en el cuadro de búsqueda para encontrar objetos; pulsa el botón de ordenar para organizarlas. En un banquero, tu banco se abre en una ventana a juego.|r",
    ["Quality borders"] = "Bordes de calidad",
    ["Colour each item's border by its rarity."] = "Colorea el borde de cada objeto según su rareza.",
    ["Item count text size"] = "Tamaño del texto de cantidad",
    ["Reset bag position"] = "Restablecer la posición de las bolsas",
    ["Search & sorting"] = "Búsqueda y ordenación",
    ["Show search box"] = "Mostrar el cuadro de búsqueda",
    ["A search field in the window header. Dims items that don't match."] = "Un campo de búsqueda en la cabecera de la ventana. Atenúa los objetos que no coinciden.",
    ["Show sort button"] = "Mostrar el botón de ordenar",
    ["A sort button in the window header. Right-click it to reverse the order."] = "Un botón de ordenar en la cabecera de la ventana. Haz clic derecho para invertir el orden.",
    ["Reverse sort order"] = "Invertir el orden",
    ["Sort bags"] = "Ordenar bolsas",
    ["Bank contents"] = "Contenido del banco",
    ["Shows what your bank holds - from the last bank visit, viewable anywhere."] = "Muestra lo que guardas en el banco, según la última visita, consultable desde cualquier sitio.",
    ["As of: %s"] = "A fecha de: %s",
    ["%d free slots"] = "%d ranuras libres",
    ["No bank visit recorded on this character yet."] = "Este personaje aún no ha registrado ninguna visita al banco.",
    ["Right-click to toggle sort order."] = "Clic derecho para alternar el orden.",
    ["Can't sort bags in combat."] = "No se pueden ordenar las bolsas en combate.",
    ["Sort order: reversed"] = "Orden: invertido",
    ["Sort order: normal"] = "Orden: normal",
    ["Sort order"] = "Orden",
    ["How the sort button arranges items. 'Blizzard' groups by category like the default UI; the others are a flat order."] = "Cómo coloca los objetos el botón de ordenar. “Blizzard” agrupa por categoría como la interfaz por defecto; los demás son un orden plano.",
    ["Blizzard (category)"] = "Blizzard (categoría)",
    ["Quality"] = "Calidad",
    ["Item type"] = "Tipo de objeto",
    ["Sort in the opposite direction."] = "Ordenar en sentido contrario.",
    ["Item level"] = "Nivel de objeto",
    ["Off"] = "Desactivado",
    ["Sort categories by"] = "Ordenar categorías por",
    ["Display-only ordering of the items inside each category section. Never moves anything in your bags."] = "Orden solo visual de los objetos dentro de cada sección de categoría. Nunca mueve nada en tus bolsas.",
    ["Show free slots (OneBag)"] = "Mostrar ranuras libres (OneBag)",
    ["OneBag view: show the empty bag slots after the items, so you can drop things onto them directly."] = "Vista OneBag: muestra las ranuras vacías después de los objetos, para poder soltar cosas directamente en ellas.",
    ["Fixed slot order (OneBag)"] = "Orden de ranuras fijo (OneBag)",
    ["Shows every slot in its natural bag order with the empty slots inline — items stay visually where you drop them, like one big real bag. Needs the free-slots option above."] = "Muestra cada ranura en su orden natural de bolsa con las ranuras vacías intercaladas: los objetos se quedan visualmente donde los sueltas, como una única bolsa real. Necesita la opción de ranuras libres de arriba.",
