    ["Racial Cooldowns"] = "Tiempos de reutilización raciales",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "Muestra la habilidad racial del rival y su tiempo de reutilización en cuanto la usa. Son los tiempos de esta expansión, y todavía ninguna racial lo comparte con el abalorio de JcJ.",
    ["Show racial cooldown"] = "Mostrar el tiempo de reutilización racial",
    ["Shadow Sight"] = "Visión de las Sombras",
    ["Shadow Sight up"] = "Visión de las Sombras disponible",
    ["Shadow Sight up - next in %d s"] = "Visión de las Sombras disponible: siguiente en %d s",
    ["Shadow Sight in %d s"] = "Visión de las Sombras en %d s",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "Cuenta atrás para los orbes de arena: el primer par aparece 95 segundos tras abrirse las puertas, y cada uno vuelve 122 segundos después de recogerlo.",
    ["Show Shadow Sight timer"] = "Mostrar el temporizador de Visión de las Sombras",
    ["Aura on the class icon"] = "Aura en el icono de clase",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "Coloca el aura más relevante en el icono de clase del rival: una inmunidad tiene prioridad sobre el control de masas, este sobre una defensiva y esta sobre un tiempo de reutilización ofensivo.",
    ["Show aura on the class icon"] = "Mostrar el aura en el icono de clase",
    ["Crowd control only"] = "Solo control de masas",
    ["Dispels"] = "Disipaciones",
    ["Dispel Cooldowns"] = "Tiempos de reutilización de disipación",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaaLa mayoría de las disipaciones no tienen tiempo de reutilización en esta expansión, así que aquí solo pueden aparecer Disipación en masa y Devorar magia del manáfago.|r",
    ["Show dispel cooldown"] = "Mostrar el tiempo de reutilización de disipación",
    ["Range"] = "Alcance",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "Atenúa el marco mientras el rival está fuera de alcance, medido con un hechizo que conoce tu clase en lugar de una distancia fija.",
    ["Fade out-of-range opponents"] = "Atenuar a los rivales fuera de alcance",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "Descarta los cambios y devuelve cada ventana al último punto de guardado, o a como estaba al abrir el modo Edición.",
    ["Discard all changes made since the last save?"] = "¿Descartar todos los cambios hechos desde el último guardado?",
    ["Grey out when you walk out of range"] = "Atenuar en gris al salir del alcance",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "Quita el color mientras estás fuera del radio de un tótem y lo restaura al volver a entrar. Se reconoce por el beneficio que el tótem te otorga, así que los tótems que no dan ninguno (Abrasador, Magma, Temblor, ...) siempre quedan iluminados.",
    ["Limit to"] = "Limitar a",
    ["Everything"] = "Todo",
    ["Only mine"] = "Solo los míos",
    ["Only removable"] = "Solo los eliminables",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "Restringe esta fila a las auras que lanzas tú o a las que se pueden eliminar.",
    ["Show who interrupted"] = "Mostrar quién interrumpió",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "El destello de interrupción muestra el nombre de quien la logró.",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "Activado: 9.9, 3.4 … Desactivado: segundos enteros (9, 3).",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "Moderno coloca los botones de bolsa reales en una tira oscura plana con el aspecto de VuloUI: abrir, intercambiar y las descripciones no cambian.",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "Moderno sustituye los botones de Blizzard por una tira oscura plana de iconos con el aspecto de VuloUI. Los clics y las descripciones no cambian.",
    ["Classic (Blizzard buttons)"] = "Clásico (botones de Blizzard)",
    ["Modern (flat icon strip)"] = "Moderno (tira plana de iconos)",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "Oculta la fila de botones de menú (personaje, libro de hechizos, …).",
    ["Hide the bag bar"] = "Ocultar la barra de bolsas",
    ["Hides the backpack and bag slots."] = "Oculta la mochila y las ranuras de bolsa.",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cffEl micromenú, la barra de bolsas, la barra de FPS/latencia y la barra de experiencia de abajo se pueden mover en el modo Edición (/vedit) como las barras de acción.|r",
    ["Micro menu"] = "Micromenú",
    ["Bag bar"] = "Barra de bolsas",
    ["FPS / latency bar"] = "Barra de FPS / latencia",
    ["XP bar"] = "Barra de experiencia",
    ["Show a custom XP bar"] = "Mostrar una barra de experiencia propia",
    ["Colour"] = "Color",
    ["Bar opacity"] = "Opacidad de la barra",
    ["Show empty buttons"] = "Mostrar los botones vacíos",
    ["Off hides empty slots; they reappear automatically while you drag an ability."] = "Desactivado oculta las ranuras vacías; reaparecen automáticamente mientras arrastras una habilidad.",
    ["Click through"] = "Clic a través",
    ["The bar ignores the mouse entirely — clicks go through it. Keybinds still work."] = "La barra ignora por completo el ratón: los clics la atraviesan. Las teclas asignadas siguen funcionando.",
    ["Keybind text size"] = "Tamaño del texto de teclas",
    ["Macro text size"] = "Tamaño del texto de macro",
    ["Count text size"] = "Tamaño del texto de cantidad",
    ["Cooldown text size"] = "Tamaño del texto de reutilización",
    ["0 = default size."] = "0 = tamaño predeterminado.",
    ["0 = default size. Requires cooldown numbers to be enabled in the game options."] = "0 = tamaño predeterminado. Requiere activar los números de reutilización en las opciones del juego.",
    ["Cooldown & look"] = "Reutilización y aspecto",
    ["|cffff5555Quick keybind mode is not available on this client.|r"] = "|cffff5555El modo de asignación rápida de teclas no está disponible en este cliente.|r",
    ["Modifier paging"] = "Paginado con modificador",
    ["Click: open these settings"] = "Clic: abrir estos ajustes",
    ["Crowd Control"] = "Control de masas",
    ["Addon font (default)"] = "Fuente del AddOn (predeterminada)",
    ["0 = uses the general text size."] = "0 = usa el tamaño de texto general.",
    ["Cast text size"] = "Tamaño del texto de lanzamiento",
    ["Cast background colour"] = "Color de fondo del lanzamiento",
    ["0 = uses the global background opacity."] = "0 = usa la opacidad de fondo global.",
    ["Icon scale"] = "Escala del icono",
    ["Icon on the right"] = "Icono a la derecha",
    ["Icon offset X"] = "Desplazamiento X del icono",
    ["Icon offset Y"] = "Desplazamiento Y del icono",
    ["Marks the spot on the enemy cast bar where YOUR interrupt comes off cooldown — everything after the tick is kickable."] = "Marca el punto de la barra de lanzamiento enemiga en el que TU interrupción queda lista: todo lo que venga tras la marca se puede interrumpir.",
    ["Tick colour"] = "Color de la marca",
    ["Cast text colour"] = "Color del texto de lanzamiento",
    ["Timer side"] = "Lado del temporizador",
    ["Timer colour"] = "Color del temporizador",
    ["Hide name while casting"] = "Ocultar el nombre al lanzar",
    ["Cast timer size"] = "Tamaño del temporizador de lanzamiento",
    ["NPC title size"] = "Tamaño del título del PNJ",
    ["0 = slightly smaller than the name."] = "0 = un poco más pequeño que el nombre.",
    ["CC icon width"] = "Anchura del icono de control",
    ["CC icon height"] = "Altura del icono de control",
    ["0 = square (uses the icon size)."] = "0 = cuadrado (usa el tamaño del icono).",
    ["Point shape"] = "Forma del indicador",
    ["Diamond"] = "Rombo",
    ["Triangle"] = "Triángulo",
    ["Below the bar"] = "Debajo de la barra",
    ["Above the bar"] = "Encima de la barra",
    ["Execute line"] = "Línea de Ejecutar",
    ["A thin marker line on the bar at the chosen health percentage (e.g. 20 for Execute)."] = "Una línea fina en la barra al porcentaje de vida elegido (p. ej. 20 para Ejecutar).",
    ["Execute line only on your target"] = "Línea de Ejecutar solo en tu objetivo",
    ["Execute line colour"] = "Color de la línea de Ejecutar",
    ["Execute line percent"] = "Porcentaje de la línea de Ejecutar",
    ["Your current target's health bar uses this colour instead of reaction / class / threat colours."] = "La barra de vida de tu objetivo actual usa este color en lugar de los colores de reacción, clase o amenaza.",
    ["Target bar colour"] = "Color de la barra del objetivo",
    ["Lightens the health bar of the plate under your mouse cursor."] = "Aclara la barra de vida de la placa que está bajo el cursor.",
    ["Target plate scale"] = "Escala de la placa del objetivo",
    ["Your target's plate is drawn this much larger (100 = off)."] = "La placa de tu objetivo se dibuja este porcentaje más grande (100 = desactivado).",
    ["Behaviour"] = "Comportamiento",
    ["Overlapping"] = "Superpuestas",
    ["Stacking"] = "Apiladas",
    ["Stacked spacing"] = "Separación al apilar",
    ["Vertical distance between stacked plates (a tenth of the game value)."] = "Distancia vertical entre placas apiladas (una décima del valor del juego).",
    ["Line-of-sight opacity"] = "Opacidad sin línea de visión",
    ["Opacity of plates whose unit is out of your line of sight."] = "Opacidad de las placas cuya unidad está fuera de tu línea de visión.",
    ["Plate view distance"] = "Distancia de visión de las placas",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaaMientras mantengas la tecla (o tu objetivo coincida), la barra principal muestra en su lugar las habilidades de la barra elegida. Totalmente seguro: funciona en combate.|r",
    ["Shift held"] = "Mayús mantenido",
    ["Ctrl held"] = "Ctrl mantenido",
    ["Alt held"] = "Alt mantenido",
    ["Friendly target"] = "Objetivo amistoso",
    ["Hostile target"] = "Objetivo hostil",
    ["Group visibility"] = "Visibilidad según grupo",
    ["Always"] = "Siempre",
    ["Only in a group"] = "Solo en grupo o banda",
    ["Only in a party"] = "Solo en grupo",
    ["Only solo"] = "Solo en solitario",
    ["Hide when mounted"] = "Ocultar al montar",
    ["Hide without target"] = "Ocultar sin objetivo",
    ["Hide without enemy target"] = "Ocultar sin objetivo enemigo",
    ["Quick keybind mode (/vkb)"] = "Modo de asignación rápida de teclas (/vkb)",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "Pasa el ratón sobre un botón de acción y pulsa una tecla para asignarla. Las barras ocultas se muestran mientras asignas.",
    ["Swipe colour"] = "Color del barrido",
    ["Icon opacity on cooldown"] = "Opacidad del icono en reutilización",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "Atenúa todo el icono mientras la habilidad está en reutilización (100 = desactivado).",
    ["Show cooldown numbers"] = "Mostrar los números de reutilización",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "Los números de cuenta atrás propios del juego en las reutilizaciones (un ajuste del juego, cambiado en vivo).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaaSe aplica a todas las barras de acción.|r",
    ["Cooldown swipe opacity"] = "Opacidad del barrido de reutilización",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "Cómo de oscura es la capa de barrido de reutilización (0 = invisible).",
    ["Desaturate icons on cooldown"] = "Desaturar los iconos en reutilización",
    ["Out-of-range colouring"] = "Coloreado fuera de alcance",
    ["Tints the whole icon while your target is out of range."] = "Tiñe todo el icono mientras tu objetivo está fuera de alcance.",
    ["Tooltips"] = "Descripciones emergentes",
    ["Hide in combat"] = "Ocultar en combate",
    ["Hide always"] = "Ocultar siempre",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "Una barra de experiencia móvil y redimensionable con capa de descanso. Se oculta al nivel máximo. Sustituye la barra de Blizzard mientras esté activa.",
    ["Hide Blizzard's XP / reputation bar"] = "Ocultar la barra de experiencia / reputación de Blizzard",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "Elimina la barra azul de experiencia / reputación que queda bajo la barra de acción.",
    ["Stance bar"] = "Barra de actitudes",
    ["Pet bar"] = "Barra de mascota",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "Toma el control de todas las barras de acción con marcos propios y móviles: mostrar/ocultar real por combate o ratón, escala y disposición en cuadrícula por barra, paginado correcto de la barra principal (formas de druida/pícaro/guerrero/sacerdote) y tus asignaciones de teclas. EXPERIMENTAL: prueba los clics de habilidad y el paginado en combate; /reload tras desactivarlo.",
    ["Standard action bars are back. Reload the interface to restore every last piece of the default layout."] = "Las barras de acción estándar han vuelto. Recargar la interfaz restaura hasta el último detalle del diseño predeterminado.",
    ["Buttons per row"] = "Botones por fila",
    ["Button spacing"] = "Separación entre botones",
    ["Item name (exactly as in-game)"] = "Nombre del objeto (exactamente como en el juego)",
    ["|cffff5555Please enter an item name.|r"] = "|cffff5555Introduce un nombre de objeto.|r",
    ["Item '%s' added at vendor '%s'."] = "Objeto '%s' añadido al vendedor '%s'.",
    ["|cffaaaaaaItem names must match the in-game name exactly (including case and special characters).|r"] = "|cffaaaaaaLos nombres deben coincidir exactamente con el nombre del juego (incluidas mayúsculas y caracteres especiales).|r",
    ["|cffaaaaaaNo items configured. Add items above that should be bought automatically at this vendor.|r"] = "|cffaaaaaaNo hay objetos configurados. Añade arriba los objetos que se comprarán automáticamente en este vendedor.|r",
    ["Remove"] = "Quitar",
    ["Item '%s' removed."] = "Objeto '%s' eliminado.",
    ["Inspect Fix"] = "Arreglo de inspección",
    ["Inspect state manually reset. Try again now."] = "Estado de inspección restablecido manualmente. Prueba de nuevo.",
    ["|cffffff00[VuloClassicUI]|r Inspect state reset."] = "|cffffff00[VuloClassicUI]|r Estado de inspección restablecido.",
    ["Auto-reset on timeout"] = "Restablecer al agotar el tiempo",
    ["If no response from the server comes after X seconds, the pending inspect state is automatically reset — so the next inspect attempt works again."] = "Si el servidor no responde tras X segundos, el estado de inspección pendiente se restablece automáticamente, de modo que el siguiente intento vuelve a funcionar.",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 5 seconds is the new default for Anniversary — fast enough to recover quickly."] = "Cuánto esperar a INSPECT_READY antes de restablecer automáticamente. 5 segundos es el nuevo valor por defecto en Anniversary: lo bastante rápido para recuperarse pronto.",
    ["|cffaaaaaaSlash commands: /inspectreset (force-reset), /inspectstate (debug info in chat)|r"] = "|cffaaaaaaComandos: /inspectreset (forzar restablecimiento), /inspectstate (información de depuración en el chat)|r",
    ["Timeout (seconds)"] = "Tiempo de espera (segundos)",
    ["Manual Reset"] = "Restablecimiento manual",
    ["Reset inspect state now"] = "Restablecer el estado de inspección ahora",
    ["Inspect state manually reset."] = "Estado de inspección restablecido manualmente.",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "Enganche NotifyInspect: %s\\nEnganche InspectFrame: %s",
    ["|cff66ff66active|r"] = "|cff66ff66activo|r",
    ["|cffff8800waiting|r"] = "|cffff8800esperando|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800esperando a Blizzard_InspectUI|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaaQué hace el arreglo: registra las inspecciones activas con una marca de tiempo, redibuja los datos de objetos que llegan tarde, vuelve a pedir una vez la inspección si sale vacía y llama a ClearInspectPlayer() al cerrar y al agotar el tiempo. Evita que un estado bloqueado impida todas las inspecciones siguientes.|r",
    ["Auto-retry empty inspects"] = "Reintentar inspecciones vacías",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "Tras la respuesta del servidor, las ranuras de objeto se redibujan poco después (los datos suelen llegar tarde). Si la ventana sigue completamente vacía, la inspección se solicita una vez más automáticamente.",
    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaaEstado: %s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66Enganche activo|r",
    ["LFG Browse Nil Fix"] = "Arreglo nil de la búsqueda LFG",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "Captura errores de Lua en el Buscador de grupos de Anniversary (LFGBrowseSearchEntry_Update con resultIDs obsoletos). Evita el spam en el chat y las listas de búsqueda rotas.",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r Error de búsqueda LFG de Blizzard capturado (entrada obsoleta omitida).",
    ["Chat message on first error"] = "Mensaje en el chat al primer error",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "Muestra un mensaje breve una vez por sesión en el chat cuando se captura un error de búsqueda LFG.",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "Este arreglo envuelve la función |cffffffffLFGBrowseSearchEntry_Update|r de Blizzard en una llamada protegida (xpcall). Cuando la entrada falla por un resultID obsoleto (“searchResultInfo nil”), el error se descarta: la siguiente actualización de Blizzard limpia la entrada de la lista automáticamente.",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "esperando a Blizzard_GroupFinder_VanillaStyle",
    ["Guild News Nil Fix"] = "Arreglo nil de las noticias de hermandad",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "Captura errores de Lua en las entradas de noticias de hermandad (normalmente “formatString” o “GuildUtil”) y sustituye las entradas rotas por un texto alternativo en lugar de romper todo el panel.",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080Entrada de noticias de hermandad no válida|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r Error de noticias de hermandad de Blizzard capturado (texto alternativo aplicado).",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "Muestra un mensaje breve una vez por sesión en el chat cuando se captura un error de noticias de hermandad.",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "Este arreglo envuelve la función |cffffffffGuildNewsButton_SetNews|r de Blizzard en una llamada protegida (xpcall). Cuando una entrada lanza un error conocido (“formatString” o “GuildUtil”), se sustituye por el texto alternativo “Entrada de noticias de hermandad no válida”: el panel sigue siendo utilizable.",
    ["waiting for Blizzard_Communities"] = "esperando a Blizzard_Communities",
    ["Auction Price Fix"] = "Arreglo del precio en subastas",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "Corrige un error nil en la interfaz alemana de la casa de subastas (PriceDropdown no definido).",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "Este arreglo soluciona un fallo conocido de la localización alemana de WoW: la interfaz de la casa de subastas hace referencia a un elemento “PriceDropdown” que nunca se definió, lo que provoca errores de Lua al abrir la casa de subastas.",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaaIdioma actual: %s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaaEl arreglo solo se aplica en clientes alemanes (deDE). En otros idiomas el módulo está inactivo.|r",
    ["|cff66ff66applied|r"] = "|cff66ff66aplicado|r",
    ["skipped (deDE-only)"] = "omitido (solo deDE)",
    ["not applied"] = "no aplicado",
