    ["Missed"] = "Fallado",
    ["Blocked"] = "Bloqueado",
    ["Absorbed"] = "Absorbido",
    ["|cffffffffCOMBAT TEXT|r"] = "|cffffffffTEXTO DE COMBATE|r",
    ["Flashing combat notifications (with live preview) plus a scrolling combat-log text engine."] = "Notificaciones de combate parpadeantes (con vista previa en vivo) y un motor de texto desplazable para el registro de combate.",
    ["Show Preview"] = "Mostrar vista previa",
    ["Text"] = "Texto",
    ["Thick Outline"] = "Contorno grueso",
    ["Also apply font to Blizzard mob FCT"] = "Aplicar también la fuente al FCT de criaturas de Blizzard",
    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "Además define DAMAGE_TEXT_FONT de forma global: cambia la fuente de los números de daño sobre criaturas y mascotas. Requiere /reload para aplicarse.",
    ["Interrupted"] = "Interrumpido",
    ["Parried/Dodged/Missed"] = "Parado/Esquivado/Fallado",
    ["Engine FCT (above mob/pet)"] = "FCT del motor (sobre criatura/mascota)",
    ["Sharper hit indicator font (Friz Quadrata)"] = "Fuente de impactos más nítida (Friz Quadrata)",
    ["Engine FCT Scale"] = "Escala del FCT del motor",
    ["Damage numbers above mob/pet — bitmap scaling."] = "Números de daño sobre criatura/mascota: escalado de mapa de bits.",
    ["Center"] = "Centrar",
    ["Unlock / Position"] = "Desbloquear / Posición",
    ["Trinkets"] = "Abalorios",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "Dos ranuras de abalorio en pantalla con tiempo de reutilización, selección desplegable y cola automática.",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaaDos ranuras de abalorio con tiempo de reutilización, selección desplegable y cola automática.|nClic izquierdo = usar, clic derecho = desplegable.|r",
    ["Show frame"] = "Mostrar marco",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "Oculta o muestra las dos ranuras de abalorio. La cola automática sigue funcionando aunque estén ocultas.",
    ["Position locked"] = "Posición bloqueada",
    ["If on, the frame cannot be accidentally moved."] = "Si está activo, el marco no se puede mover accidentalmente.",
    ["Size"] = "Tamaño",
    ["Scales the trinket slots."] = "Escala las ranuras de abalorio.",
    ["Character Panel"] = "Panel de personaje",
    ["Dark Skin"] = "Aspecto oscuro",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "El look oscuro de la interfaz en un solo sitio: un aspecto oscuro integrado para los botones de acción y los iconos de WeakAuras, más un Modo oscuro opcional que oscurece los marcos, el minimapa y las barras por defecto de Blizzard.",
    ["The dark action-bar button skin."] = "El aspecto oscuro de los botones de la barra de acción.",
    ["Enable Dark Mode"] = "Activar Modo oscuro",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "Retiñe de un tono oscuro los marcos, el minimapa y las texturas de la barra de acción por defecto de Blizzard. Desactivado por defecto.",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaOpcional: oscurece y desatura las texturas por defecto de Blizzard (marcos de unidad, minimapa y barras de acción) hasta un tono oscuro neutro. Reversible: desactívalo y vuelve el look dorado.|r",
    ["Action Bars"] = "Barras de acción",
    ["Skin the action bars"] = "Aplicar el aspecto a las barras de acción",
    ["Bar style"] = "Estilo de barra",
    ["WeakAuras Icons"] = "Iconos de WeakAuras",
    ["Skin WeakAuras icons"] = "Aplicar el aspecto a los iconos de WeakAuras",
    ["Hide WeakAuras' own border"] = "Ocultar el borde propio de WeakAuras",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "Oculta el borde claro que WeakAuras dibuja en los iconos para que solo se vea nuestro borde oscuro. Usa /reload para restaurarlo por completo.",
    ["Circle"] = "Círculo",
    ["Also skin pet & stance buttons"] = "Aplicar también a los botones de mascota y actitud",
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "Mejora el panel de personaje: nivel de objeto por ranura, engarces y texto de encantamiento abreviado.",
    ["Show item level per slot"] = "Mostrar nivel de objeto por ranura",
    ["Show average item level"] = "Mostrar nivel de objeto medio",
    ["Show sockets"] = "Mostrar engarces",
    ["Shorten enchant text (DE/EN)"] = "Abreviar el texto de encantamiento (DE/EN)",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "Ejemplo: 'Stamina' → 'Stam', 'Ausdauer' → 'Ausd'.",
    ["Treat rings as enchantable"] = "Tratar los anillos como encantables",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "También muestra el texto de encantamiento en los anillos (TBC: algunas profesiones pueden encantar anillos). Requiere /reload.",
    ["Text Size"] = "Tamaño del texto",
    ["Item Level Text Size"] = "Tamaño del texto de nivel de objeto",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "Tamaño de fuente del número de nivel de objeto en cada ranura. Se aplica al instante con el panel de personaje abierto.",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "Nota: algunos cambios solo se aplican del todo tras un /reload, ya que el panel de personaje se engancha al cargar.",
    ["|cffff0000No Ench|r"] = "|cffff0000Sin ench|r",
    ["|c%siLvL - %d|r"] = "|c%siLvL - %d|r",
    ["Gold Tracker"] = "Registro de oro",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "Muestra en el tooltip de oro de la mochila cuánto oro has ganado o gastado desde el último restablecimiento. Persistente por personaje.",
    ["Gold Tracker reset|r. Start = "] = "Registro de oro restablecido|r. Inicio = ",
    ["Gold Balance|r"] = "Balance de oro|r",
    ["Gained:|r"] = "Ganado:|r",
    ["Spent:|r"] = "Gastado:|r",
    ["|cffffffffNet:|r"] = "|cffffffffNeto:|r",
    ["Start:|r"] = "Inicio:|r",
    ["Now:|r"] = "Ahora:|r",
    ["Reset with /vcui goldreset|r"] = "Restablece con /vcui goldreset|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaaMuestra en el tooltip de oro de la mochila el balance desde el último restablecimiento manual:|n  - |cff44ff44Ganado|r (misiones, botín, ventas a vendedores, correo)|n  - |cffff4444Gastado|r (reparaciones, compras a vendedores, gastos de correo)|n  - |cffffffffNeto|r (+/- desde el restablecimiento)|n|nLos valores son |cffffffffpersistentes por personaje|r tras /reload y al cerrar sesión.|nEl oro recibido sin conexión (correo de la casa de subastas, comercio) no se cuenta.|n|nRestablecer: el botón de abajo o |cffffff00/vcui goldreset|r.|r",
    ["Reset session"] = "Restablecer sesión",
    ["Class Specific"] = "Específico de clase",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaaRegistro de maná de Toque vampírico: muestra en directo cuánto maná has dado al grupo (5% por tic del daño de las Sombras, por cada usuario de maná).|n|cffffffffSe restablece automáticamente al empezar el combate.|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800Estas herramientas solo están activas si juegas con un Sacerdote.|r",
    ["No tools yet"] = "Aún no hay herramientas",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaaAún no hay herramientas específicas para esta clase. ¿Tienes alguna idea? ¡Dímelo!|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffManá TV:|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffManá TV:|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "Toque vampírico: %d de maná dado al grupo.",
    ["|cffffffffVT MANA|r"] = "|cffffffffMANÁ TV|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "Marco de maná TV: x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor de maná TV activo. |cff9b6cffArrastra|r o usa las |cff9b6cffflechas|r (MAYÚS = 5 px).",
    ["VT mana mover disabled."] = "Movedor de maná TV desactivado.",
    ["Print to chat at combat end"] = "Mostrar en el chat al acabar el combate",
    ["Writes a summary in chat after each fight."] = "Escribe un resumen en el chat tras cada combate.",
    ["Reset manually"] = "Restablecer manualmente",
    ["VT mana reset."] = "Maná TV restablecido.",
    ["Bars"] = "Barras",
    ["Icons"] = "Iconos",
    ["Shadow Word: Pain"] = "Palabra de las Sombras: Dolor",
    ["Vampiric Touch"] = "Toque vampírico",
    ["Devouring Plague"] = "Peste devoradora",
    ["Warning (seconds left)"] = "Aviso (segundos restantes)",
    ["Bar width"] = "Ancho de barra",
    ["Bar height"] = "Alto de barra",
    ["Spacing"] = "Espaciado",
    ["Color the timer text"] = "Colorear el texto del temporizador",
    ["Show recast gain %"] = "Mostrar % ganado al relanzar",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "Muestra cuánto más fuerte golpearía un lanzamiento nuevo ahora mismo (p. ej. +12% con un proc de poder con hechizos activo). Los valores negativos significan que el DoT activo se capturó más fuerte: mejor consérvalo.",
    ["DoT Tracker"] = "Registro de DoT",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaaRegistra tus DoT en el objetivo. |cff44ff44Verde|r = tienes un beneficio activo que hará que golpee más fuerte si lo relanzas ahora (captura de TBC); |cffff4444rojo|r = a punto de expirar.|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800Solo activo si juegas con un %s.|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaaRegistra tus DoT de Brujo (Corrupción, Maldición de agonía, Aflicción inestable, Sifón de vida, Inmolar, Maldición de perdición) en el objetivo, con la misma lectura de captura al relanzar que el registro del Sacerdote.|r",
    ["Corruption"] = "Corrupción",
    ["Curse of Agony"] = "Maldición de agonía",
    ["Unstable Affliction"] = "Aflicción inestable",
    ["Siphon Life"] = "Sifón de vida",
    ["Immolate"] = "Inmolar",
    ["Curse of Doom"] = "Maldición de perdición",
    ["|cffffffffDOTS|r"] = "|cffffffffDOT|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "DoT de Sombras: x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor de DoT de Sombras activo. |cff9b6cffArrastra|r o usa las |cff9b6cffflechas|r (MAYÚS = 5 px).",
    ["Shadow DoTs mover disabled."] = "Movedor de DoT de Sombras desactivado.",
    ["Mark empty sockets"] = "Marcar engarces vacíos",
    ["Adds a red ring around item sockets that have no gem."] = "Añade un anillo rojo alrededor de los engarces sin gema.",
    ["Text shadow (instead of outline)"] = "Sombra en el texto (en lugar de contorno)",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "Texto más limpio con sombra en lugar de un contorno grueso.",
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaaUn minimapa redondo y moderno con anillo biselado, texto de zona y reloj en una píldora estrecha. Haz zoom con la rueda del ratón. |cffffffffMayús+arrastrar el mapa|r para moverlo, o usa Desbloquear / el modo Edición propio del addon (/vedit). El modo Edición de Blizzard no gestiona este mapa.|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffffMINIMAPA|r",
    ["Minimap: x=%.0f, y=%.0f"] = "Minimapa: x=%.0f, y=%.0f",
    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor de minimapa activo. |cff9b6cffArrastra|r o usa las |cff9b6cffflechas|r (MAYÚS = 5 px).",
    ["Minimap module disabled — /reload restores the default layout completely."] = "Módulo de minimapa desactivado: /reload restaura por completo la disposición por defecto.",
    ["Minimap ping: %s"] = "Ping en el minimapa: %s",
    ["Shape"] = "Forma",
    ["Round"] = "Redondo",
    ["Accent ring"] = "Anillo de acento",
    ["Ring color"] = "Color del anillo",
    ["Accent (purple)"] = "Acento (morado)",
    ["Class color"] = "Color de clase",
    ["Custom color"] = "Color personalizado",
    ["Theme color"] = "Color del tema",
    ["Dark guild & communities window"] = "Ventana oscura de hermandad y comunidades",
    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "Aplica el mismo look oscuro a la ventana de hermandad y comunidades. Desactivarlo requiere un /reload.",
    ["Debuffs on target (yours only)"] = "Perjuicios en el objetivo (solo los tuyos)",
    ["Missing buffs (reminder)"] = "Beneficios ausentes (recordatorio)",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaaLos iconos aparecen mientras TU perjuicio/DoT está en el objetivo, con su tiempo restante. Añade el perjuicio por nombre o ID.|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaaLos iconos aparecen mientras te FALTA el beneficio: un recordatorio para aceites de arma, bendiciones y beneficios de comida. Añade el beneficio por nombre o ID.|r",
    ["Tint blue when out of mana"] = "Teñir de azul si falta maná",
    ["Tint red when out of range"] = "Teñir de rojo si está fuera de alcance",
    ["Needs a target; uses the spell's own range."] = "Necesita un objetivo; usa el alcance del propio hechizo.",
    ["Auto-track equipped trinkets"] = "Seguir automáticamente los abalorios equipados",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "Mantiene automáticamente ambos abalorios equipados en este grupo: se actualizan al cambiar de abalorio.",
    ["(copy)"] = "(copia)",
    ["Show tooltips on hover"] = "Mostrar tooltips al pasar el ratón",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "Los iconos interceptarán el ratón: déjalo desactivado si la barra queda sobre elementos en los que haya que hacer clic.",
    ["Copy the link with Ctrl+C:"] = "Copia el enlace con Ctrl+C:",
    ["Click: copy link"] = "Clic: copiar enlace",
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaaColorea todo lo que hoy es morado con el color que elijas: barra lateral, bordes, resaltados y barras. Un /reload lo aplica en todas partes.|r",
    ["Purple (default)"] = "Morado (por defecto)",
    ["Turquoise"] = "Turquesa",
    ["Pink"] = "Rosa",
    ["Orange"] = "Naranja",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "Color del tema cambiado. /reload lo aplica a todo (los elementos ya dibujados conservan el color anterior hasta entonces).",
    ["Custom ring color"] = "Color del anillo personalizado",
    ["A thin colored line around the dark ring (round shape only)."] = "Una línea fina de color alrededor del anillo oscuro (solo con forma redonda).",
    ["Zone panel"] = "Panel de zona",
    ["Zone text and clock"] = "Texto de zona y reloj",
    ["Above the map"] = "Encima del mapa",
    ["Below the map"] = "Debajo del mapa",
    ["Hidden"] = "Oculto",
    ["Show clock"] = "Mostrar reloj",
    ["Show date"] = "Mostrar fecha",
    ["Shows the date next to the clock. Click it to open the calendar."] = "Muestra la fecha junto al reloj. Haz clic para abrir el calendario.",
    ["Buttons"] = "Botones",
    ["Zoom buttons (+/-)"] = "Botones de zoom (+/-)",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "Muestra un + y un - planos en el borde derecho del mapa. La rueda del ratón siempre hace zoom también.",
    ["Show day/night button"] = "Mostrar el botón de día/noche",
    ["Restyle addon buttons"] = "Rediseñar los botones de addons",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "Quita los bordes dorados de los botones de minimapa de otros addons y les da un aspecto redondo y limpio. Desactivarlo requiere un /reload.",
    ["Addon buttons only on mouseover"] = "Botones de addons solo al pasar el ratón",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "Oculta los botones de minimapa de otros addons hasta que el ratón está sobre el minimapa.",
    ["Ping in chat"] = "Ping en el chat",
    ["Prints who pinged the minimap."] = "Muestra quién ha hecho ping en el minimapa.",
    ["Totem Bar"] = "Barra de tótems",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa|cffffffffClic izquierdo|r en un icono para (re)lanzar el tótem de ese elemento, |cffffffffpasa el ratón|r por una ranura para elegir el tótem de la lista y |cffffffffclic central|r para retirar todos los tótems. El borde del icono se vuelve rojo justo antes de que el tótem expire.|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800Solo activo si juegas con un Chamán.|r",
    ["Totem set"] = "Conjunto de tótems",
    ["Active set"] = "Conjunto activo",
    ["Set name"] = "Nombre del conjunto",
    ["New set"] = "Nuevo conjunto",
    ["Delete set"] = "Borrar conjunto",
    ["Shown elements"] = "Elementos mostrados",
    ["Sound before a totem expires"] = "Sonido antes de que expire un tótem",
    ["Icon border (action-bar style)"] = "Borde del icono (estilo barra de acción)",
    ["Style"] = "Estilo",
    ["VuloUI (dark)"] = "VuloUI (oscuro)",
    ["Classic (metal)"] = "Clásico (metal)",
    ["Flyout direction"] = "Dirección del desplegable",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "Hacia dónde se abre el selector de tótems al pasar el ratón por una ranura. Automático elige el lado contrario al borde de la pantalla.",
    ["Automatic"] = "Automático",
    ["Upwards"] = "Hacia arriba",
    ["Downwards"] = "Hacia abajo",
    ["To the left"] = "Hacia la izquierda",
    ["To the right"] = "Hacia la derecha",
    ["Open flyout in combat"] = "Abrir el desplegable en combate",
    ["Tooltip with cooldown on hover"] = "Tooltip con tiempo de reutilización al pasar el ratón",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "Al pasar el ratón por una ranura de tótem o un icono del selector se muestran el nombre del tótem y su tiempo de reutilización restante.",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "Desactivado = pasar el ratón por una ranura nunca abre el selector de tótems mientras luchas (los clics siguen lanzando). El selector también se cierra al salir el ratón y tras cada lanzamiento, incluso en combate.",
    ["Earth"] = "Tierra",
    ["Water"] = "Agua",
    ["|cffffffffTOTEMS|r"] = "|cffffffffTÓTEMS|r",
    ["Totems: x=%.0f, y=%.0f"] = "Tótems: x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Movedor del temporizador de tótems activo. |cff9b6cffArrastra|r o usa las |cff9b6cffflechas|r (MAYÚS = 5 px).",
    ["Totem timer mover disabled."] = "Movedor del temporizador de tótems desactivado.",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555Error de herramienta de clase:|r %s",
    ["EDIT MODE"] = "MODO EDICIÓN",
    ["Edit Mode"] = "Modo Edición",
    ["Open Edit Mode"] = "Abrir el modo Edición",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "Cierra el modo Edición y bloquea todas las ventanas. Tus cambios se mantienen.",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "Mantiene la disposición actual y sigue editando. Descartar volverá entonces a este punto en lugar de al aspecto que tenía al abrir el modo Edición.",
    ["Window positions saved."] = "Posiciones de las ventanas guardadas.",
    ["Exit"] = "Salir",
    ["Close"] = "Cerrar",
    ["Reset"] = "Restablecer",
    ["Reset this frame"] = "Restablecer este marco",
    ["Reset all VuloUI window positions to the screen centre."] = "Restablece todas las posiciones de las ventanas de VuloUI al centro de la pantalla.",
    ["Reset all VuloUI window positions to the screen centre?"] = "¿Restablecer todas las posiciones de las ventanas de VuloUI al centro de la pantalla?",
    ["Done — lock everything"] = "Listo: bloquear todo",
    ["Grid"] = "Cuadrícula",
    ["Snap"] = "Ajustar",
    ["Show an alignment grid."] = "Muestra una cuadrícula de alineación.",
    ["Snap windows to the grid while dragging."] = "Ajusta las ventanas a la cuadrícula al arrastrarlas.",
    ["%d frames here - hold Alt to cycle"] = "%d marcos aquí: mantén Alt para alternar",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "A qué punto de la pantalla está anclado el marco (lo mantiene en su sitio al cambiar de resolución).",
    ["ANCHOR"] = "ANCLAJE",
    ["POSITION"] = "POSICIÓN",
    ["SCALE"] = "ESCALA",
    ["FREE MOVE"] = "MOVIMIENTO LIBRE",
    ["FOLLOW WINDOW"] = "SEGUIR VENTANA",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "Ancla esta ventana a otra: se moverá con ella siempre que esa ventana se mueva. Arrastrar esta ventana mantiene el anclaje y solo actualiza la distancia.",
    ["Not possible - that would create a loop."] = "No es posible: se crearía un bucle.",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "¿Restablecer TODOS los ajustes de VuloClassicUI para todos los personajes de esta cuenta? Esta acción no se puede deshacer.",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "Temporizador de golpe desactivado: solo registra los ataques automáticos cuerpo a cuerpo, que los talentos de este personaje no usan.",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555Error en la migración de ajustes %s:|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "Reproduce un sonido de aviso de banda en cuanto un rival usa su abalorio JcJ.",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "Hace destellar el icono brevemente cuando un rival usa su abalorio JcJ.",
    ["Icon gap"] = "Separación del icono",
    ["Distance between the icon and the bar."] = "Distancia entre el icono y la barra.",
    ["Accent colour"] = "Color de acento",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "Se usa para la barra mientras el modo de relleno no sea una textura, y para los lanzamientos canalizados en la barra de Blizzard.",
    ["Cast finished"] = "Lanzamiento completado",
    ["The bar flashes in this colour when a cast completes."] = "La barra destella con este color cuando un lanzamiento termina.",
    ["Cast interrupted"] = "Lanzamiento interrumpido",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "La barra destella con este color cuando un lanzamiento se interrumpe o falla.",
    ["Fade-in time"] = "Tiempo de aparición",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "Cuánto tarda un icono en aparecer. 0 lo muestra al instante.",
    [" and %d item(s)"] = " y %d objeto(s)",
    ["/vlfg toggles the group board."] = "/vlfg abre o cierra el tablón de grupos.",
    ["Auto-apply a lure when the pole has none"] = "Aplicar cebo automáticamente si la caña no lo tiene",
    ["Auto-equip a fishing pole if none is worn"] = "Equipar una caña de pescar automáticamente si no llevas ninguna",
    ["Auto-loot while fishing"] = "Recoger automáticamente mientras pescas",
    ["Bags are full — some items were left in the mail."] = "Bolsas llenas: algunos objetos se quedaron en el correo.",
    ["Boost fishing sound (hear the bite clearly)"] = "Realzar el sonido de pesca (oír bien el picotazo)",
    ["Burning Crusade Dungeons"] = "Mazmorras de Burning Crusade",
    ["Burning Crusade Raids"] = "Bandas de Burning Crusade",
    ["Can't change the fishing key in combat."] = "No se puede cambiar la tecla de pesca en combate.",
    ["Classic Dungeons"] = "Mazmorras de Classic",
    ["Classic Raids"] = "Bandas de Classic",
    ["Clear key"] = "Borrar tecla",
    ["Extra items & macros"] = "Objetos y macros adicionales",
    ["Fishing key cleared."] = "Tecla de pesca borrada.",
    ["Fishing key set to: %s"] = "Tecla de pesca asignada a: %s",
    ["Fishing key: %s  —  click to change"] = "Tecla de pesca: %s  —  haz clic para cambiarla",
    ["Fishing sound volume"] = "Volumen del sonido de pesca",
    ["Friends"] = "Amigos",
    ["Guild"] = "Hermandad",
