    -- Talent overrides
    ["active"] = "activos",
    ["Talent Overrides"] = "Ajustes por grupo de talentos",
    ["Talent group %d"] = "Grupo de talentos %d",
    ["%d settings overridden"] = "%d ajustes sustituidos",
    ["Forget all overrides for this talent group"] = "Olvidar todos los ajustes de este grupo de talentos",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "Los ajustes se aplican solos al cambiar de grupo de talentos. Este cliente no tiene especializaciones, por eso el eje es el sistema de talentos dual.",
    -- Override groups
    ["Talent group %d (%s)"] = "Grupo de talentos %d (%s)",
    ["Name for the new group"] = "Nombre del nuevo grupo",
    ["Editing as"] = "Editando como",
    ["Yourself"] = "Tú mismo",
    ["Manage groups..."] = "Gestionar grupos...",
    ["Owns the current talent group"] = "Se aplica al grupo de talentos actual",
    ["Delete this group"] = "Eliminar este grupo",
    ["No groups yet."] = "Aún no hay grupos.",
    -- Anchor points
    ["Centre"] = "Centro",
    ["Thin outline"] = "Contorno fino",
    ["Bar Setups"] = "Configuraciones de barra",
    -- Patch notes 1.40.0
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s todavía no tiene una acción asignada — esto es un error, informa de él por favor.",
    ["%s belongs to %s, which is switched off."] = "%s pertenece a %s, que está desactivado.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cffComandos|r — %d en total. Los grises pertenecen a un módulo desactivado.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s también lo reclama otro accesorio (%s) — solo uno de los dos gana.",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555El módulo de configuraciones de barra no está cargado.|r",
    ["Bar setup '%s' deleted."] = "Configuración de barra '%s' eliminada.",
    ["Not in combat — bars can't be changed while fighting."] = "Fuera de combate — las barras no se pueden cambiar mientras luchas.",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "Configuración de barra '%s' cargada: %d espacios asignados, %d vaciados, |cffff8800%d omitidos|r (hechizo desconocido / objeto o macro ausente).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "Configuración de barra '%s' cargada: %d espacios asignados, %d vaciados.",
    ["on"] = "activado",
    ["Overridden settings: %s"] = "Ajustes anulados: %s",
    ["Situation"] = "Situación",
    ["Everywhere"] = "En todas partes",
    ["Raid instance"] = "Banda",
    ["5-player instance"] = "Mazmorra (5 jugadores)",
    ["Battleground"] = "Campo de batalla",
    ["In a group"] = "En grupo",
    ["Alone"] = "En solitario",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "Solo se aplica en esta situación. Junto con una configuración de talentos, ambas deben cumplirse — y ese grupo prevalece entonces sobre uno que solo indique la configuración de talentos.",
    ["Icon"] = "Icono",
    ["No icon"] = "Sin icono",
    ["Shown in front of the group name in the menu and on the header button."] = "Aparece delante del nombre del grupo en el menú y en el botón de cabecera.",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "Desactivar elimina justo esta anulación. El ajuste vuelve a seguir al perfil.",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "Las configuraciones de barra ahora se guardan una sola vez para toda la cuenta: %d conservadas, %d duplicadas fusionadas.",
    ["Trinket window settings now live in this addon's own database."] = "Los ajustes de la ventana de abalorios ahora residen en la base de datos propia de este accesorio.",
    ["Auto queue: top slot"] = "Cola automática: espacio superior",
    ["Auto queue: bottom slot"] = "Cola automática: espacio inferior",
    ["Auto queue for this slot"] = "Cola automática para este espacio",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "El mismo interruptor que alt-clic sobre el espacio. Activado, la cola cambia este abalorio en combate siguiendo el orden de abajo.",
    ["Order"] = "Orden",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "La cola recorre esta lista desde arriba. Elige una entrada para moverla o cambiar sus ajustes.",
    ["- empty -"] = "- vacío -",
    ["— queue stops here —"] = "— la cola se detiene aquí —",
    ["Add from bags"] = "Añadir desde las bolsas",
    ["Adds a trinket you are carrying to the end of this list."] = "Añade al final de esta lista un abalorio que lleves encima.",
    ["Swap delay"] = "Retardo de cambio",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "Segundos que este abalorio permanece equipado antes de que la cola lo vuelva a cambiar. 0 = sin espera.",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "Este abalorio se equipa antes que los de encima en cuanto esté listo.",
    ["Pause while equipped"] = "Pausar mientras esté equipado",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "Mientras lleves este abalorio la cola se detiene — para un abalorio cuyo efecto no quieres cortar.",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaaConsejo: clic izquierdo en un espacio para usar el abalorio, clic derecho para la lista. Alt-clic activa la cola automática de ese espacio.|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "%d instantánea(s) tenían el mismo nombre pero contenido distinto y se conservaron con un nombre nuevo.",
    ["GAP"] = "SEPARACIÓN",
    ["Distance from that edge, in pixels. 0 is flush."] = "Distancia a ese borde, en píxeles. 0 es al ras.",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "Acopla esta ventana a ese lado del objetivo y la centra ahí. 'Centrado' no la mueve — solo la lleva consigo. La separación se mantiene de borde a borde, así que sobrevive al redimensionado de cualquiera de las dos ventanas.",
    ["waiting for a swing"] = "esperando un golpe",
    ["  -  lag %.0fms"] = "  -  latencia %.0fms",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800No hay ningún sello del que cambiar. Solo el Sello de Autoridad y el Sello de Rectitud siguen aplicándose a un golpe después de ser sustituidos, así que hay que conocer uno de los dos.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800Solo se conoce un sello. Hace falta un segundo al que cambiar.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800No se puede cambiar desde el sello que mantienes. Solo el Sello de Autoridad y el Sello de Rectitud siguen aplicándose al golpe que los sustituye.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "Aquí solo valen el Sello de Autoridad y el Sello de Rectitud: son los dos cuyo efecto sigue aplicándose al golpe que los sustituye.",
    -- Namensplaketten-Vorlage
    -- Plaetze der Namensplaketten
    ["Main positions"] = "Posiciones principales",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaaUna cosa por espacio. Lo que asignes a un espacio se lo quitas al que lo tenía.|r",
    ["Debuffs"] = "Perjuicios",
    ["Buffs"] = "Beneficios",
    ["Crowd control"] = "Control de masas",
    ["Your own debuffs"] = "Tus propios perjuicios",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow in the aura's own school colour"] = "Brillar en el color de escuela del aura",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "Magia azul, maldición morado, enfermedad naranja, veneno verde — en vez de un color para todo.",
    -- Absorptionsstil
    ["Absorb style"] = "Estilo de absorción",
    ["Flat colour"] = "Color plano",
    -- Zauberziel
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "El objetivo actual de quien lanza, junto a la barra de lanzamiento. Tu propio nombre se colorea.",
    ["Cast target size"] = "Tamaño del objetivo del hechizo",
    -- Zielpfeile
    ["Two arrows pointing in at the target's bar, one on each side."] = "Dos flechas que apuntan a la barra del objetivo, una a cada lado.",
    ["Arrow size"] = "Tamaño de flecha",
    ["Arrow distance"] = "Distancia de flecha",
    ["Arrow colour"] = "Color de flecha",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "Marca en la placa de foco",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "Un texto corto en la placa de tu objetivo de foco. Un anillo dice que esa es especial; la marca dice cuál.",
    ["Mark text"] = "Texto de la marca",
    ["Mark position"] = "Posición de la marca",
    ["Mark size"] = "Tamaño de la marca",
    -- Kleine Plaketten
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaaMantén el Sello de Autoridad y lanza el segundo sello en la última fracción de segundo antes de tu ataque automático: ese golpe llevará ambos. Por debajo del nivel 64 el segundo sello es el de Rectitud; a partir de ahí lo sustituyen Sangre y Mártir.|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaaLa barra cuenta atrás hasta el golpe por zonas: |cff5c8aebazul|r está libre para un relleno, |cffd93636rojo|r es el tramo en el que un lanzamiento seguiría en el tiempo de reutilización global al abrirse la ventana, y |cff33ff66verde|r es la ventana de cambio. La última marca dentro del verde es el cambio tardío, que deja sitio para un juicio por delante del sello.|r",
    ["Late twist window (seconds)"] = "Ventana de cambio tardío (segundos)",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "El final de la ventana de cambio, marcado aparte. Cambiar tan tarde deja sitio para un juicio por delante del sello. Iguálalo a la ventana de cambio para ocultar la marca.",
    ["Second cue for the late window"] = "Segundo aviso para la ventana tardía",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "Un sonido distinto en la marca del cambio tardío, para distinguir los dos extremos de la ventana sin mirar la barra.",
    ["Shade the zones"] = "Colorear las zonas",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "Tiñe la parte del golpe que aún queda con el color de la zona a la que llega.",
    ["Show the marks"] = "Mostrar las marcas",
    ["The three boundary lines: danger zone, twist window, late twist."] = "Las tres líneas de límite: zona de peligro, ventana de cambio, cambio tardío.",
    ["Show seal indicators"] = "Mostrar indicadores de sello",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "Los sellos que llevas ahora y cuánto duran, a la derecha de la barra. Ambos se ven mientras el cambio está hecho: ese solape es la recompensa.",
    ["Seal icon size"] = "Tamaño de los iconos de sello",
    ["Head start for the prompt (ms)"] = "Adelanto del aviso (ms)",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "Muestra el aviso de cambio y reproduce su sonido este tiempo antes de que la ventana se abra de verdad, para que dé tiempo a verlo y pulsar. Los colores de la barra siguen siendo exactos.",
    ["auto"] = "Auto",
    ["Twist only"] = "Solo cambio",
    ["Rotation"] = "Rotación",
    ["Show the rotation helper"] = "Mostrar la ayuda de rotación",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "Una fila de pasos encima de la barra: qué secuencia encaja con tu arma y tu celeridad, y en qué punto de ella estás. Avanza con lo que lanzas de verdad y con tus golpes.",
    ["Sequence"] = "Secuencia",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "Automática sigue tu velocidad de ataque y tu celeridad de hechizos, que son las que deciden cuántos cambios caben entre dos golpes. Elige una a mano para practicar una sola secuencia.",
    ["Rotation icon size"] = "Tamaño de icono",
    ["Sound when the twist lands"] = "Sonido cuando el cambio acierta",
    ["Hit sound"] = "Sonido de acierto",
    ["Listen"] = "Escuchar",
    ["Chime"] = "Campanilla",
    ["Raid warning"] = "Aviso de banda",
    ["Ready check"] = "Comprobación de preparación",
    ["Click"] = "Clic",
    -- Patch notes 1.41.0
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "Oscurecer enemigos fuera de combate",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "Atenúa los enemigos que no luchan contra nadie, para que destaquen los que sí. Nunca tu propio objetivo.",
    ["Darken to (%)"] = "Oscurecer al (%)",
    ["Highlight strength"] = "Intensidad del resaltado",
    ["Hitbox width (%)"] = "Ancho del área pulsable (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "Área pulsable de la placa. 100 deja intacto el tamaño del juego. Se guarda en el perfil.",
    ["Hitbox height (%)"] = "Alto del área pulsable (%)",
    -- Wechsel verloren
    -- Gewehrschuss
    ["Rifle"] = "Disparo de rifle",
    -- Aktionszeile
    ["Action text size"] = "Tamaño del texto de acción",
    ["The line that names what to press. 0 follows the general text size."] = "La línea que dice qué pulsar. 0 sigue al tamaño de texto general.",
    -- Tempo- und Siegel-Timer-Groesse
    ["Seal timer text size"] = "Tamaño del temporizador de sello",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "La cuenta atrás en los iconos de sello. 0 la escala con el icono.",
    -- Warnzeile
    ["Warning text size"] = "Tamaño del texto de aviso",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "Los avisos rojos y amarillos de la barra. 0 sigue al tamaño del texto de acción.",
    -- Bedingungen je Eintrag
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "Limita este icono a un número de acumulaciones, o a los últimos segundos antes de expirar.",
    ["Only from stacks"] = "Solo a partir de acumulaciones",
    ["0 = any number of stacks."] = "0 = cualquier número de acumulaciones.",
    ["Only in the last seconds"] = "Solo en los últimos segundos",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = en cualquier momento. Si no, el icono aparece solo así de cerca de expirar.",
    -- Einheit je Gruppe
    ["Watch this unit"] = "Observar esta unidad",
    ["Whose auras this group reads. The default is what the group type has always used."] = "De quién lee las auras este grupo. Por defecto es lo que el tipo de grupo ha usado siempre.",
    ["You"] = "Tú",
    ["Target"] = "Objetivo",
    ["Focus"] = "Foco",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "Solo lo que yo mismo lanzo",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "Desactivado cuenta el aura sin importar quién la puso — para un perjuicio de banda que cualquiera puede aplicar.",
    -- Sortierung
    ["Fixed keeps the order you added them in. The other two reorder live by what is left."] = "Fijo mantiene el orden en que los añadiste. Los otros dos reordenan en vivo según lo que queda.",
    ["As added"] = "Como se añadieron",
    ["Least time left first"] = "Menos tiempo restante primero",
    ["Most time left first"] = "Más tiempo restante primero",
    ["Practice"] = "Práctica",
    ["|cffaaaaaaA swing clock that runs on its own, with no target and nothing spent. Press your bound keys against it and every swing is graded: the twist landed, it was too early, or nothing was attempted. The seal model is the real one -- a replaced seal keeps resolving for 0.4 seconds -- so the timing you learn here is the timing that works.|r"] = "|cffaaaaaaUn reloj de golpe que corre por su cuenta, sin objetivo y sin gastar nada. Pulsa tus teclas asignadas contra él y cada golpe recibe una nota: el twist salió, fue demasiado pronto o no se intentó nada. El modelo de sellos es el real -- un sello reemplazado sigue resolviéndose durante 0,4 segundos -- así que el ritmo que aprendes aquí es el ritmo que funciona.|r",
    ["Start / stop practice"] = "Iniciar / detener práctica",
    ["Stop practice"] = "Detener práctica",
    ["Simulated weapon speed"] = "Velocidad de arma simulada",
    ["0 uses whatever you have equipped. Any other value drills a speed you do not own yet, which is how you find out that the weapon you are saving for needs a different sequence."] = "0 usa lo que lleves equipado. Cualquier otro valor entrena una velocidad que aún no tienes, que es como descubres que el arma para la que ahorras necesita otra secuencia.",
    ["Spell queue window (ms)"] = "Ventana de cola de hechizos (ms)",
    ["A key pressed this far before the global cooldown ends is held and fires the moment it does, exactly as the client does it. Practising without it teaches a rhythm the game never asks for."] = "Una tecla pulsada con esta antelación al final del tiempo de reutilización global se retiene y se ejecuta en cuanto termina, igual que hace el cliente. Practicar sin ella enseña un ritmo que el juego nunca pide.",
    ["Result text size"] = "Tamaño del texto de resultado",
    ["Result text duration (seconds)"] = "Duración del texto de resultado (segundos)",
    ["Landed colour"] = "Color de logrado",
    ["Missed colour"] = "Color de fallado",
    ["Show the fight timeline"] = "Mostrar la cronología del combate",
    ["Every swing and every cast on one strip against a ruler. The ruler is the point: without it you can see that two swings were close together but not how close, which is the only number practice is about."] = "Cada golpe y cada lanzamiento en una sola franja sobre una regla. La regla es lo importante: sin ella ves que dos golpes estuvieron cerca, pero no cuánto, y ese es el único número que importa al practicar.",
    ["Timeline width"] = "Anchura de la cronología",
    ["Timeline pixels per second"] = "Píxeles por segundo de la cronología",
    ["TWIST"] = "TWIST",
    ["MISS"] = "FALLO",
    ["TOO EARLY"] = "MUY PRONTO",
    ["speed %.2fs  -  GCD %.2fs  -  %d of %d"] = "veloc. %.2fs  -  GCD %.2fs  -  %d de %d",
    ["|cffffffffPRACTICE|r"] = "|cffffffffPRÁCTICA|r",
    ["|cffffffffRESULT|r"] = "|cffffffffRESULTADO|r",
    ["|cffffffffTIMELINE|r"] = "|cffffffffCRONOLOGÍA|r",
    ["|cffffcc33Twist practice|r"] = "|cffffcc33Práctica de twist|r",
    ["Practice needs two seals: pick them under Seals first."] = "La práctica necesita dos sellos: elígelos primero en Sellos.",
    ["Practice mode on. Press your bound keys; the swing runs on its own."] = "Modo de práctica activado. Pulsa tus teclas asignadas; el golpe corre por su cuenta.",
    ["Practice mode off. %d of %d swings carried the twist."] = "Modo de práctica desactivado. %d de %d golpes llevaron el twist.",
    ["Bloodlust"] = "Ansia de sangre",
    ["Haste potion"] = "Poción de celeridad",
    ["Abacus"] = "Ábaco",
    ["Time warp"] = "Distorsión temporal",
    ["Crusader Strike"] = "Golpe de cruzado",
    ["Judgement"] = "Juicio",
    ["Cast the held seal"] = "Lanzar el sello mantenido",
    ["Cast the twist seal"] = "Lanzar el sello de twist",
    ["Filler"] = "Relleno",
    ["Start / stop attack"] = "Iniciar / detener ataque",
    ["wait"] = "esperar",
    ["Next action"] = "Siguiente acción",
    ["|cffffffffNEXT ACTION|r"] = "|cffffffffSIGUIENTE ACCIÓN|r",
    ["Next action mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Reubicación de siguiente acción activa. |cff9b6cffArrastra la caja morada|r o usa las |cff9b6cffteclas de flecha|r (MAYÚS = 5px). Vuelve a pulsar 'Desbloquear / Probar' para terminar.",
    ["Next action mover disabled."] = "Reubicación de siguiente acción desactivada.",
    ["|cffaaaaaaAn icon of the one thing to press, wherever you want it. It answers the same question as the line under the bar -- the three switches below feed both, so the word and the picture can never disagree.|r"] = "|cffaaaaaaUn icono de lo único que hay que pulsar, donde tú quieras. Responde a la misma pregunta que la línea bajo la barra -- los tres interruptores de abajo alimentan a ambos, así que la palabra y la imagen nunca pueden contradecirse.|r",
    ["Show the next action guide"] = "Mostrar la guía de siguiente acción",
    ["When to show it"] = "Cuándo mostrarla",
    ["Show a hold instead of nothing"] = "Mostrar una espera en vez de nada",
    ["While the right move is to press nothing on purpose -- the twist is coming and anything else would cost it -- the guide keeps showing the seal, drained and outlined. An empty box says the same thing much less clearly."] = "Mientras la jugada correcta sea no pulsar nada a propósito -- el twist está por llegar y cualquier otra cosa lo costaría -- la guía sigue mostrando el sello, apagado y con contorno. Una caja vacía dice lo mismo con mucha menos claridad.",
    ["Suggest Judgement"] = "Sugerir Juicio",
    ["Judging consumes the seal, so it is only ever offered with room to re-seal afterwards. Off by default: a mistimed judgement costs more than no suggestion at all."] = "Juzgar consume el sello, así que solo se ofrece cuando queda margen para volver a sellar después. Desactivado por defecto: un juicio a destiempo cuesta más que ninguna sugerencia.",
    ["Suggest a filler"] = "Sugerir un relleno",
    ["Consecration, or Exorcism where the target can take it, in the stretch of the swing that is free for it. Exorcism is offered by asking the client whether the spell can be aimed at your target, which is right in every language."] = "Consagración, o Exorcismo cuando el objetivo lo admite, en el tramo del golpe que queda libre para ello. Exorcismo se ofrece preguntando al cliente si el hechizo puede apuntar a tu objetivo, lo cual es correcto en cualquier idioma.",
    ["Consecration mana floor (%)"] = "Mínimo de maná para Consagración (%)",
    ["Below this share of your mana the filler is not worth it."] = "Por debajo de esta fracción de tu maná el relleno no compensa.",
    ["Exorcism mana floor (%)"] = "Mínimo de maná para Exorcismo (%)",
    ["Longest Crusader Strike delay (ms)"] = "Retraso máximo de Golpe de cruzado (ms)",
    ["Once leaving the strike any longer than this would waste it, it stops being a suggestion and becomes the answer. Measured against the earliest moment you could actually cast it, not against now."] = "En cuanto dejar el golpe más tiempo que esto lo desperdiciaría, deja de ser una sugerencia y pasa a ser la respuesta. Se mide desde el primer momento en que podrías lanzarlo de verdad, no desde ahora.",
    ["Twist!"] = "¡Twist!",
    ["|cffffffffTWIST TEXT|r"] = "|cffffffffTEXTO DE TWIST|r",
    ["Twist text mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Reubicación del texto de twist activa. |cff9b6cffArrastra la caja morada|r o usa las |cff9b6cffteclas de flecha|r (MAYÚS = 5px). Vuelve a pulsar 'Desbloquear / Probar' para terminar.",
    ["Twist text mover disabled."] = "Reubicación del texto de twist desactivada.",
    ["Twist landed"] = "Twist logrado",
    ["|cffaaaaaaAll three cues below wait for PROOF, not for a prediction. A swing has to land with both seals up, and the held seal's own damage has to follow it in the combat log. Nothing fires without that second line -- a confirmation that is right most of the time is one you cannot practise against.|r"] = "|cffaaaaaaLos tres avisos de abajo esperan una PRUEBA, no una predicción. Un golpe tiene que impactar con ambos sellos activos, y el daño propio del sello mantenido tiene que seguirlo en el registro de combate. Nada se dispara sin esa segunda línea -- una confirmación que acierta casi siempre no sirve para practicar.|r",
    ["Sound channel"] = "Canal de sonido",
    ["Master"] = "Maestro",
    ["Sound effects"] = "Efectos de sonido",
    ["Master ignores the sound effects slider, which is what a confirmation wants: it is feedback about the fight rather than part of it."] = "Maestro ignora el deslizador de efectos de sonido, que es lo que quiere una confirmación: es información sobre el combate, no parte de él.",
    ["The sniper and rifle cracks are bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "Los chasquidos de francotirador y rifle vienen incluidos; el resto son avisos propios del cliente. Debajo aparecen los sonidos que otros complementos hayan registrado como medios compartidos.",
    ["Sniper"] = "Francotirador",
    ["Level up"] = "Subir de nivel",
    ["Quest complete"] = "Misión completada",
    ["Bonus objective"] = "Objetivo adicional",
    ["Map ping"] = "Señal en el mapa",
    ["Glow on the bar when the twist lands"] = "Resplandor en la barra al lograr el twist",
    ["Glow style"] = "Estilo del resplandor",
    ["Pixel border"] = "Borde de píxeles",
    ["Autocast ring"] = "Anillo de autolanzamiento",
    ["Pixel border traces the bar's own outline at any width. Autocast pins the client's own ring to the four corners, so it stays a ring however wide the bar gets."] = "Borde de píxeles recorre el propio contorno de la barra sea cual sea su anchura. Autolanzamiento fija el anillo propio del cliente a las cuatro esquinas, de modo que sigue siendo un anillo por muy ancha que se haga la barra.",
    ["Glow colour"] = "Color del resplandor",
    ["Glow duration (seconds)"] = "Duración del resplandor (segundos)",
    ["Text when the twist lands"] = "Texto al lograr el twist",
    ["A line somewhere on screen, with its own position. Useful where the bar is in the corner of the eye and the confirmation should be in the middle of it."] = "Una línea en algún punto de la pantalla, con su propia posición. Útil cuando la barra queda en el rabillo del ojo y la confirmación debería estar en el centro de la vista.",
    ["Text font"] = "Fuente del texto",
    ["Text outline"] = "Contorno del texto",
    ["Text colour"] = "Color del texto",
    ["Text duration (seconds)"] = "Duración del texto (segundos)",
    ["|cffffffffSEALS|r"] = "|cffffffffSELLOS|r",
    ["Seal indicator mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Reubicación del indicador de sellos activa. |cff9b6cffArrastra la caja morada|r o usa las |cff9b6cffteclas de flecha|r (MAYÚS = 5px). Vuelve a pulsar 'Desbloquear / Probar' para terminar.",
    ["Seal indicator mover disabled."] = "Reubicación del indicador de sellos desactivada.",
    ["Match the bar height"] = "Igualar la altura de la barra",
    ["Sizes the icons to the bar instead of to their own setting, so the pair keeps lining up with it when the bar height changes."] = "Ajusta el tamaño de los iconos a la barra en vez de a su propio ajuste, para que la pareja siga alineada con ella cuando cambie la altura de la barra.",
    ["Ignored while the icons match the bar height."] = "Se ignora mientras los iconos igualen la altura de la barra.",
    ["Seal icon spacing"] = "Separación de los iconos de sello",
    ["Centre the icons"] = "Centrar los iconos",
    ["Keeps the midpoint of the pair still when the second seal appears or falls off. Left-aligned keeps the first icon still instead, which is what an attached pair wants -- that edge is the bar."] = "Mantiene fijo el punto medio de la pareja cuando el segundo sello aparece o desaparece. Alineado a la izquierda mantiene fijo el primer icono, que es lo que quiere una pareja adosada -- ese borde es la barra.",
    ["Show the cooldown sweep"] = "Mostrar el barrido de reutilización",
    ["The client's own sweep across the icon. It says the same thing as the number under it, but it says it without being read."] = "El barrido propio del cliente sobre el icono. Dice lo mismo que el número que hay debajo, pero lo dice sin tener que leerlo.",
    ["Seal timer colour"] = "Color del temporizador de sello",
    ["Detach from the bar"] = "Separar de la barra",
    ["Gives the pair its own position anywhere on screen. They stay tied to the bar in every other way: when it is hidden, they are too."] = "Da a la pareja su propia posición en cualquier punto de la pantalla. Siguen ligados a la barra en todo lo demás: cuando ella se oculta, ellos también.",
    ["Twist lost"] = "Twist perdido",
    ["Swing ready -- restart your attack"] = "Golpe listo -- reinicia tu ataque",
    ["(none available)"] = "(ninguno disponible)",
    ["Solid"] = "Sólido",
    ["Attack speed"] = "Velocidad de ataque",
    ["Swing timer"] = "Temporizador de golpe",
    ["Latency (ms)"] = "Latencia (ms)",
    ["Global cooldown left"] = "Tiempo de reutilización global restante",
    ["Nothing"] = "Nada",
    ["Left readout"] = "Lectura izquierda",
    ["What the left end of the bar shows. Attack speed turns into the warning colour below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "Lo que muestra el extremo izquierdo de la barra. La velocidad de ataque pasa al color de advertencia por debajo de dos tiempos de reutilización globales por golpe -- por debajo de eso ya no caben a la vez el twist y volver a poner el sello, así que espera al tiempo de reutilización antes de hacer twist.",
    ["Right readout"] = "Lectura derecha",
    ["Readout text size"] = "Tamaño del texto de lectura",
    ["The two numbers inside the bar. 0 follows the general text size."] = "Los dos números dentro de la barra. 0 sigue el tamaño de texto general.",
    ["Global cooldown bar texture"] = "Textura de la barra de tiempo de reutilización global",
    ["Border"] = "Borde",
    ["Solid draws four flat edges in the colour below. Texture takes an edge file from shared media, which is what a border from another interface pack looks like."] = "Sólido dibuja cuatro bordes planos en el color de abajo. Textura toma un archivo de borde de los medios compartidos, que es el aspecto que tiene un borde de otro paquete de interfaz.",
    ["Only used while the border is set to texture."] = "Solo se usa mientras el borde esté ajustado a textura.",
    ["Border width"] = "Anchura del borde",
    ["Marker texture"] = "Textura del marcador",
    ["Marker width"] = "Anchura del marcador",
    ["Font colour"] = "Color de la fuente",
    ["Frame strata"] = "Estrato del marco",
    ["Which layer of the interface the helper sits in. Raise it to lift the bar over another addon that draws in the same place."] = "En qué capa de la interfaz se sitúa el asistente. Súbelo para poner la barra por encima de otro complemento que dibuje en el mismo sitio.",
    ["Draw level"] = "Nivel de dibujo",
    ["The order inside the chosen layer. Higher draws on top."] = "El orden dentro de la capa elegida. Un valor más alto se dibuja encima.",
    ["Colour the bar by"] = "Colorear la barra según",
    ["The zone the swing is in"] = "La zona en la que está el golpe",
    ["The seal you are carrying"] = "El sello que llevas",
    ["Zones colour the fill by the stretch of the swing you are in, which is what this helper is built around. Seal colours it by what you are carrying, which is the faster read once the timing is in your fingers. Either way the special colours below outrank the choice."] = "Zonas colorea el relleno según el tramo del golpe en el que estás, que es la base de este asistente. Sello lo colorea según lo que llevas, que se lee más rápido cuando ya tienes el ritmo en los dedos. En cualquier caso, los colores especiales de abajo tienen prioridad sobre esta elección.",
    ["Seal of Command"] = "Sello de Mando",
    ["Seal of Righteousness"] = "Sello de Rectitud",
    ["Seal of Blood / the Martyr"] = "Sello de Sangre / del Mártir",
    ["Seal of Vengeance"] = "Sello de Venganza",
    ["Seal of the Crusader"] = "Sello del Cruzado",
    ["Seal of Justice"] = "Sello de Justicia",
    ["Seal of Light"] = "Sello de Luz",
    ["Seal of Wisdom"] = "Sello de Sabiduría",
    ["No twist possible"] = "Twist imposible",
    ["The fill while this swing's twist is already gone, and the tail of the swing a cast can no longer reach."] = "El relleno mientras el twist de este golpe ya se ha perdido, y la cola del golpe a la que un lanzamiento ya no llega.",
    ["Warning"] = "Advertencia",
    ["The warnings on the bar, and the attack speed once the weapon is too fast to twist with."] = "Las advertencias de la barra, y la velocidad de ataque cuando el arma es demasiado rápida para hacer twist.",
    ["Twisting"] = "Twist en curso",
    ["The fill while both seals are up: the twist is in and this swing carries it."] = "El relleno mientras ambos sellos están activos: el twist está hecho y este golpe lo lleva.",
    ["Default"] = "Por defecto",
    ["The fill with no seal up and between swings."] = "El relleno sin ningún sello activo y entre golpes.",
    ["Global cooldown"] = "Tiempo de reutilización global",
    ["Deadzone"] = "Zona muerta",
    ["Twist window padding"] = "Margen de la ventana de twist",
    ["Pulls the twist window earlier so the cast still reaches the server inside it. Dynamic follows your calibrated latency; fixed is a number you choose yourself."] = "Adelanta la ventana de twist para que el lanzamiento aún llegue al servidor dentro de ella. Dinámico sigue tu latencia calibrada; fijo es un número que eliges tú.",
    ["Fixed twist padding (ms)"] = "Margen de twist fijo (ms)",
    ["Only used while the padding mode is set to fixed."] = "Solo se usa mientras el modo de margen esté ajustado a fijo.",
    ["Dynamic (follows latency)"] = "Dinámico (sigue la latencia)",
    ["Fixed"] = "Fijo",
    ["Latency"] = "Latencia",
    ["|cffaaaaaaThe round trip your client reports is not the delay a twist has to beat: the client adds a slice of its own, so the figure everything below works from is (world latency x multiplier) + offset. Raise the multiplier if you keep missing twists that looked in time.|r"] = "|cffaaaaaaEl viaje de ida y vuelta que informa tu cliente no es el retardo que un twist debe superar: el cliente añade una parte propia, así que la cifra con la que trabaja todo lo de abajo es (latencia de mundo x multiplicador) + desfase. Sube el multiplicador si sigues fallando twists que parecían a tiempo.|r",
    ["Latency multiplier"] = "Multiplicador de latencia",
    ["Latency offset (ms)"] = "Desfase de latencia (ms)",
    ["Shade the deadzone"] = "Sombrear la zona muerta",
    ["The tail of the swing a cast can no longer cross, shaded at the end of the bar. Its size follows your raw world latency rather than the calibrated figure, because this one is the wire and not a prediction. This switch only draws it -- the timing itself always accounts for it, so set the scale to 0 if you want no compensation at all."] = "La cola del golpe que un lanzamiento ya no puede cruzar, sombreada al final de la barra. Su tamaño sigue tu latencia de mundo en bruto en lugar de la cifra calibrada, porque esta es el cable y no una predicción. Este interruptor solo la dibuja -- el cálculo del ritmo siempre la tiene en cuenta, así que pon la escala a 0 si no quieres ninguna compensación.",
    ["Deadzone scale"] = "Escala de la zona muerta",
    ["Multiplies your world latency. Raise it if you cannot twist just outside the shaded stretch, lower it if you still can inside it. 0 switches the compensation off entirely."] = "Multiplica tu latencia de mundo. Súbela si no consigues hacer twist justo fuera del tramo sombreado, bájala si aún puedes hacerlo dentro de él. 0 desactiva la compensación por completo.",
    ["Deadzone texture"] = "Textura de la zona muerta",
    ["Deadzone transparency"] = "Transparencia de la zona muerta",
    ["Global cooldown padding"] = "Margen del tiempo de reutilización global",
    ["Pulls the global cooldown boundary earlier by part of your latency, so a cast started right at the mark still clears the cooldown in time."] = "Adelanta el límite del tiempo de reutilización global una parte de tu latencia, para que un lanzamiento iniciado justo en la marca supere el tiempo de reutilización a tiempo.",
    ["Fixed global cooldown padding (ms)"] = "Margen fijo del tiempo de reutilización global (ms)",
    ["Show the judgement mark"] = "Mostrar la marca de juicio",
    ["A fourth line where Judgement comes off cooldown during this swing, so a judgement can be put in front of the twist instead of on top of it. Only drawn while a seal is up."] = "Una cuarta línea donde Juicio termina su reutilización durante este golpe, para poder colocar un juicio delante del twist en vez de encima de él. Solo se dibuja mientras haya un sello activo.",
    ["Show the global cooldown bar"] = "Mostrar la barra de tiempo de reutilización global",
    ["A strip along the bottom of the bar reaching to the moment the global cooldown frees up, so you can see how much of this swing is already spoken for."] = "Una franja a lo largo de la parte inferior de la barra que llega hasta el momento en que se libera el tiempo de reutilización global, para que veas qué parte de este golpe ya está comprometida.",
    ["Global cooldown bar height"] = "Altura de la barra de tiempo de reutilización global",
    ["When to show the bar"] = "Cuándo mostrar la barra",
    ["Always keeps it on screen, which is the easier way to practise the timing on a dummy. Seal active shows it whenever you are carrying a seal, in or out of a fight."] = "Siempre la mantiene en pantalla, que es la forma más fácil de practicar el ritmo con un muñeco. Sello activo la muestra siempre que lleves un sello, dentro o fuera de combate.",
    ["Seal active"] = "Sello activo",
    ["In combat or seal active"] = "En combate o sello activo",
    ["Only with Two-Handed Weapon Specialization"] = "Solo con Especialización en armas a dos manos",
    ["Hides the helper unless you have a point in the talent. Twisting works without it, but the slow swing it is built around is what makes the whole habit pay."] = "Oculta el asistente salvo que tengas un punto en el talento. Enlazar funciona sin él, pero el golpe lento sobre el que se construye es lo que hace que todo el hábito valga la pena.",
    ["Neck"] = "Cuello",
    ["Shoulder"] = "Hombros",
    ["Waist"] = "Cintura",
    ["Legs"] = "Piernas",
    ["Wrist"] = "Muñecas",
    ["Hands"] = "Manos",
    ["Finger 2"] = "Dedo 2",
    ["Trinket 2"] = "Abalorio 2",
    ["Off Hand"] = "Mano izquierda",
    ["Ranged"] = "A distancia",
    -- Patch notes 1.42.0
    -- Patch notes 1.42.0
