    -- Patch notes 1.43.0
    ["Icon Strip"] = "Tira de iconos",
    ["Distance from frame"] = "Distancia al marco",
    ["Spacing between icons"] = "Espaciado entre iconos",
    ["Racial, PvP trinket and the DR row sit on the same edge of the frame and are placed one after the other, in that order, outwards from the frame."] = "La habilidad racial, el abalorio JcJ y la fila de DR se sitúan en el mismo borde del marco y se colocan uno tras otro, en ese orden, hacia fuera.",
    ["Where it sits is set once for all three trackers under Layout, Icon Strip."] = "Su posición se ajusta una sola vez para los tres rastreadores en Disposición, Tira de iconos.",
    ["Gap below each frame. The opponent's pet bar hangs off the bottom of the frame, so a small gap lets it reach into the next one."] = "Espacio bajo cada marco. La barra de la mascota del rival sobresale por debajo del marco, así que con poco espacio invade el siguiente.",
    ["Arena: racial, PvP trinket and the DR row now share one icon strip; your chosen side was kept."] = "Arena: la habilidad racial, el abalorio JcJ y la fila de DR comparten ahora una sola tira de iconos; se ha mantenido el lado que elegiste.",
    ["|cffff5555Arena layout failed:|r %s"] = "|cffff5555Fallo en la disposición de la arena:|r %s",
    ["|cffff5555Arena icon strip error:|r %s"] = "|cffff5555Error en la tira de iconos de la arena:|r %s",
    ["Nothing in this bar yet. Add a spell or trinket below, or drag one onto the bar."] = "Aún no hay nada en esta barra. Añade abajo un hechizo o abalorio, o arrastra uno a la barra.",
    ["+  New cooldown bar"] = "+  Nueva barra de reutilizaciones",
    ["+  New buff / proc bar"] = "+  Nueva barra de beneficios y procs",
    ["+  New target debuff bar"] = "+  Nueva barra de perjuicios en el objetivo",
    ["+  New missing-buff reminder"] = "+  Nuevo recordatorio de beneficios ausentes",
    ["Buffs & Procs"] = "Beneficios y procs",
    ["Target debuffs"] = "Perjuicios en el objetivo",
    ["Missing buffs"] = "Beneficios ausentes",
    ["New name for this bar"] = "Nuevo nombre para esta barra",
    ["Delete this bar and everything on it?"] = "¿Eliminar esta barra y todo lo que hay en ella?",
    ["That is the last bar — there has to be one."] = "Esa es la última barra: tiene que quedar una.",
    ["Drag to reorder bars"] = "Arrastra para reordenar las barras",
    ["Rename this bar"] = "Renombrar esta barra",
    ["Delete this bar"] = "Eliminar esta barra",
    ["Duplicate bar"] = "Duplicar barra",
    ["Copies the selected bar with all entries and layout settings."] = "Copia la barra seleccionada con todas sus entradas y ajustes de disposición.",
    ["Bar layout"] = "Disposición de la barra",
    ["Icon appearance"] = "Aspecto de los iconos",
    ["Icon display"] = "Visualización de iconos",
    ["Movable cooldown bars grouped however you like — procs, defensives, offensives, each with its own look and position."] = "Barras de reutilización movibles agrupadas a tu gusto: procs, defensivas, ofensivas, cada una con su propio aspecto y posición.",
    ["Which IDs should be shown in tooltips? Some types do not exist on this game version and are ignored (e.g. TraitNodeID, SourceID)."] = "¿Qué ID deben mostrarse en los tooltips? Algunos tipos no existen en esta versión del juego y se ignoran (p. ej. TraitNodeID, SourceID).",
    ["CDM Bars"] = "Barras CDM",
    ["Bug Fixes"] = "Corrección de errores",
    ["Bar Glows"] = "Brillos de barra",
    ["Click to edit this icon's glow."] = "Haz clic para editar el brillo de este icono.",
    ["Click an icon to edit its glow."] = "Haz clic en un icono para editar su brillo.",
    ["Nothing in this bar yet. Add a spell or trinket on the CDM Bars tab first."] = "Aún no hay nada en esta barra. Añade primero un hechizo o abalorio en la pestaña Barras CDM.",
    ["|cffaaaaaaEach icon can glow while a buff of yours is active — or missing. Click an icon in the preview above, then add one or more watchers; the first whose condition holds paints the icon.|r"] = "|cffaaaaaaCada icono puede brillar mientras un beneficio tuyo esté activo — o ausente. Haz clic en un icono en la vista previa de arriba y añade uno o más vigilantes; el primero cuya condición se cumpla colorea el icono.|r",
    ["|cff888888No icon picked yet.|r"] = "|cff888888Ningún icono elegido todavía.|r",
    ["Glows: %s"] = "Brillos: %s",
    ["Glow when"] = "Brillar cuando",
    ["Buff is active"] = "El beneficio está activo",
    ["Buff is missing"] = "El beneficio falta",
    ["Action button glow"] = "Brillo de botón de acción",
    ["Pulsing fill"] = "Relleno pulsante",
    ["Gold (default)"] = "Oro (predeterminado)",
    ["Pick color..."] = "Elegir color...",
    ["Remove this glow"] = "Quitar este brillo",
    ["Watches: %s"] = "Vigila: %s",
    ["Add watcher (buff name / ID)"] = "Añadir vigilante (nombre del hechizo / ID)",
    ["|cffaaaaaaNo watcher yet. Most spells put a buff of the same name on you when used — one click below makes this icon glow while that buff is on you. Or type any other buff into the field.|r"] = "|cffaaaaaaAún no hay vigilante. La mayoría de los hechizos ponen sobre ti un beneficio del mismo nombre al usarse: un clic abajo hace brillar este icono mientras ese beneficio esté sobre ti. O escribe cualquier otro beneficio en el campo.|r",
    ["Glow while '%s' is on me"] = "Brillar mientras '%s' esté sobre mí",
    -- Patch notes 1.44.0
    ["Developer"] = "Desarrollador",
    ["Suppress Lua Errors"] = "Suprimir errores de Lua",
    ["Hides the game's own Lua error popup (CVar scriptErrors). Errors still happen and error-collecting addons still see them - they just stop interrupting you."] = "Oculta la ventana de errores de Lua del juego (CVar scriptErrors). Los errores siguen ocurriendo y los addons que los recopilan siguen viéndolos; simplemente dejan de interrumpirte.",
    ["Show IDs in Tooltips"] = "Mostrar IDs en los tooltips",
    ["Shows spell, item, NPC and other IDs in tooltips. Which ID types appear can be fine-tuned on the Tooltip IDs page in the Extras group."] = "Muestra IDs de hechizos, objetos, PNJ y más en los tooltips. Qué tipos de ID aparecen se puede ajustar en la página ID en tooltips del grupo Extras.",
    ["Reset All Settings"] = "Restablecer todos los ajustes",
    ["Optimize My FPS and Graphics"] = "Optimizar mis FPS y gráficos",
    ["Applies a proven set of graphics settings that noticeably raises FPS while keeping the game looking good - shadows, liquids, ambient occlusion and view distance go down, textures and spell effects stay sharp. Your current values are saved first and the restore button brings them back. Only settings this client knows are touched."] = "Aplica un conjunto probado de ajustes gráficos que sube notablemente los FPS sin que el juego deje de verse bien: sombras, líquidos, oclusión ambiental y distancia de visión bajan, las texturas y los efectos de hechizos siguen nítidos. Tus valores actuales se guardan primero y el botón de restaurar los devuelve. Solo se tocan ajustes que este cliente conoce.",
    ["Restore My Graphics Settings"] = "Restaurar mis ajustes gráficos",
    ["Returns every graphics setting the optimize button changed to its previous value and removes the backup."] = "Devuelve cada ajuste gráfico cambiado por el botón de optimizar a su valor anterior y elimina la copia de seguridad.",
    ["Graphics optimized: %d settings applied."] = "Gráficos optimizados: %d ajustes aplicados.",
    ["Graphics settings restored."] = "Ajustes gráficos restaurados.",
    ["Global Font"] = "Fuente global",
    ["The font for the whole VuloClassicUI interface. Fonts shared by other addons appear here too.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "La fuente de toda la interfaz de VuloClassicUI. Las fuentes compartidas por otros addons también aparecen aquí.\n\n|cffaaaaaaRequiere /reload para aplicarse en todas partes.|r",
    ["Outline Mode"] = "Modo de contorno",
    ["Default outline for VuloClassicUI text. Elements with their own outline setting keep it.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "Contorno predeterminado para los textos de VuloClassicUI. Los elementos con su propio ajuste de contorno lo conservan.\n\n|cffaaaaaaRequiere /reload para aplicarse en todas partes.|r",
    ["Apply to All Game Texts"] = "Aplicar a todos los textos del juego",
    ["Replaces the font of the game's own texts (chat, tooltips, quest log and more) with the global font.\n\n|cffaaaaaaTurning it off requires /reload to restore the original fonts.|r"] = "Sustituye la fuente de los textos propios del juego (chat, tooltips, registro de misiones y más) por la fuente global.\n\n|cffaaaaaaAl desactivarlo se necesita /reload para restaurar las fuentes originales.|r",
    ["Class Colors"] = "Colores de clase",
    ["Resource Colors"] = "Colores de recursos",
    ["Font changed. /reload required to apply it everywhere."] = "Fuente cambiada. Se necesita /reload para aplicarla en todas partes.",
    ["Reset to default"] = "Restablecer al valor predeterminado",
    ["Rename..."] = "Renombrar...",
    ["Rename loadout '%s'. Enter new name:"] = "Renombrar el conjunto “%s”. Nuevo nombre:",
    ["A loadout named '%s' already exists."] = "Ya existe un conjunto llamado “%s”.",
    ["Loadout '%s' renamed to '%s'."] = "Conjunto “%s” renombrado a “%s”.",
    -- Patch notes 1.45.0
    ["On"] = "Activado",
    ["Select all"] = "Seleccionar todo",
    ["Deselect all"] = "Deseleccionar todo",
    ["Interface layout (window positions and links)"] = "Disposición de la interfaz (posiciones y enlaces de ventanas)",
    ["Fonts & colors (account-wide)"] = "Fuentes y colores (toda la cuenta)",
    ["Also carries your account-wide font and color settings; they apply immediately when the string is imported."] = "También incluye tus ajustes de fuente y color de toda la cuenta; se aplican de inmediato al importar la cadena.",
    ["|cffaaaaaaThe export will include %d of %d modules.|r"] = "|cffaaaaaaLa exportación incluirá %d de %d módulos.|r",
    ["Nothing selected to export."] = "No hay nada seleccionado para exportar.",
    ["|cffaaaaaaUntick modules to share only a part - a partial string merges onto the importer's active profile.|r"] = "|cffaaaaaaDesmarca módulos para compartir solo una parte - una cadena parcial se fusiona con el perfil activo de quien la importa.|r",
    ["Standard Action Bars"] = "Barras de acción estándar",
    ["Modern"] = "Moderno",
    ["|cffaaaaaaThe game's own action bars stay in place. Frame style and Dark Mode below come from the Dark Skin module and style Blizzard's buttons directly.|r"] = "|cffaaaaaaLas barras de acción propias del juego permanecen. El estilo de marco y el Modo Oscuro de abajo vienen del módulo Dark Skin y estilizan directamente los botones de Blizzard.|r",
    ["Apply layout to all bars"] = "Aplicar disposición a todas las barras",
    ["Copies this bar's layout - scale, icon size, buttons per row, spacing, direction - to every other bar."] = "Copia la disposición de esta barra - escala, tamaño de icono, botones por fila, espaciado, dirección - a todas las demás.",
    ["Layout applied to all bars."] = "Disposición aplicada a todas las barras.",
    ["Text sizes"] = "Tamaños de texto",
    ["Bar Display"] = "Visualización de barras",
    ["Menu, Bags & XP Bar"] = "Menú, bolsas y barra de EXP",
    ["|cffaaaaaaOnly active in Modern mode (Bar Display tab).|r"] = "|cffaaaaaaSolo activo en el modo Moderno (pestaña Visualización de barras).|r",
    ["Click: layout settings. Right-click: text sizes."] = "Clic: ajustes de disposición. Clic derecho: tamaños de texto.",
    ["Bar Animations"] = "Animaciones de barras",
    ["Tint the pressed state"] = "Teñir el estado pulsado",
    ["Colours the flash a button shows while it is pressed down."] = "Colorea el destello que muestra un botón mientras está pulsado.",
    ["Tint the hover highlight"] = "Teñir el resaltado al pasar el ratón",
    ["Colours the glow a button shows under the mouse."] = "Colorea el brillo que muestra un botón bajo el ratón.",
    ["Use class colour"] = "Usar color de clase",
    ["Enable bar background"] = "Activar fondo de barra",
    ["A flat colour panel behind the bar, sized with it."] = "Un panel de color plano detrás de la barra, dimensionado con ella.",
    ["Padding"] = "Margen",
    ["Flat (default)"] = "Plano (predeterminado)",
    ["Core"] = "Principal",
    ["Opacity"] = "Opacidad",
    ["Durability"] = "Durabilidad",
    ["Talent points"] = "Puntos de talento",
    ["Pulse"] = "Pulso",
    ["Steady"] = "Constante",
    ["Background"] = "Fondo",
    ["Low"] = "Bajo",
    ["Medium"] = "Medio",
    ["High"] = "Alto",
    ["Dialog"] = "Diálogo",
    ["Click an icon to jump to its settings."] = "Haz clic en un icono para ir a su ajuste.",
    ["Middle-click: hide until the next loading screen."] = "Clic central: ocultar hasta la próxima pantalla de carga.",
    ["Nothing to preview: every reminder is switched off."] = "Nada que previsualizar: todos los recordatorios están desactivados.",
    ["Show effects missing on others"] = "Mostrar efectos que faltan a otros",
    ["Scans your party or raid for class buffs you could cast and reminds you when someone lacks one."] = "Examina tu grupo o banda en busca de beneficios de clase que podrías lanzar y te avisa cuando a alguien le falta uno.",
    ["Missing on %s: %s"] = "Le falta a %s: %s",
    ["In raids (minutes)"] = "En bandas (minutos)",
    ["In dungeons (minutes)"] = "En mazmorras (minutos)",
    ["0 uses the global warn threshold."] = "0 usa el umbral de aviso global.",
    ["Preferred food"] = "Comida preferida",
    ["Preferred flask or elixir"] = "Frasco o elíxir preferido",
    ["Preferred weapon enhancement"] = "Mejora de arma preferida",
    ["Automatic (best in bags)"] = "Automático (lo mejor en las bolsas)",
    ["Click to use."] = "Haz clic para usar.",
    ["Attach reminders to the cursor"] = "Anclar recordatorios al cursor",
    ["Shows small copies of the current reminders next to the mouse cursor."] = "Muestra pequeñas copias de los recordatorios actuales junto al cursor del ratón.",
    ["Helpers"] = "Ayudantes",
    ["Queue countdown, buff minigame helper and class trainer book in one place."] = "Cuenta atrás de cola, ayudante del minijuego de mejoras y libro del entrenador en un solo lugar.",
    ["Open group board"] = "Abrir buscador de grupos",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the button below)."] = "Examina el chat en busca de gente formando grupos y los lista por estancia de Classic/TBC en una ventana (/vlfg o el botón de abajo).",
    ["Show minimap button"] = "Mostrar botón en el minimapa",
    ["PvP Settings"] = "Ajustes JcJ",
    ["Fullscreen"] = "Pantalla completa",
    ["Fullscreen dialog"] = "Diálogo a pantalla completa",
    ["Tooltip"] = "Tooltip",
    ["Orientation"] = "Orientación",
    ["Horizontal"] = "Horizontal",
    ["Vertical (up)"] = "Vertical (hacia arriba)",
    ["Vertical (down)"] = "Vertical (hacia abajo)",
    ["Fill opacity"] = "Opacidad del relleno",
    ["Below 100 the world shows through the filled part of the bar."] = "Por debajo de 100, el mundo se ve a través de la parte llena de la barra.",
    ["The fill fades into a second colour towards its end."] = "El relleno se funde con un segundo color hacia su extremo.",
    ["Show plates for enemy pets"] = "Mostrar placas de mascotas enemigas",
    ["Spell name"] = "Nombre del hechizo",
    ["Colour the last tick"] = "Colorear el último tic",
    ["Show latency text"] = "Mostrar texto de latencia",
    ["Vertical"] = "Vertical",
    ["Automatic stacks a side slot as a column and a top or bottom slot as a row."] = "Automático apila un espacio lateral en columna y un espacio superior o inferior en fila.",
    ["Show older versions"] = "Mostrar versiones anteriores",
    ["%d broken numeric values were removed from the settings so they can be saved again."] = "Se eliminaron %d valores numéricos dañados de los ajustes para que puedan guardarse de nuevo.",
    ["Widen window"] = "Ensanchar ventana",
    ["Extra width for the friends window so long names, notes and zones fit on one line. 0 keeps Blizzard's width."] = "Anchura extra para la ventana de amigos, para que los nombres largos, notas y zonas quepan en una línea. 0 mantiene la anchura de Blizzard.",
    ["Classic+ keeps Blizzard's layout with extras. Modern adds the dark chrome and moves all stats into a panel on the right of the character window."] = "Classic+ mantiene el diseño de Blizzard con extras. Modern añade el acabado oscuro y mueve todas las estadísticas a un panel a la derecha de la ventana del personaje.",
    ["Overrides the group switch for this entry alone - e.g. to track a buff someone else casts on you."] = "Anula el ajuste de grupo solo para esta entrada; p. ej. para seguir un beneficio que otro lanza sobre ti.",
    ["Group default"] = "Predeterminado del grupo",
    ["Anyone's"] = "De cualquiera",
    ["Use conditions"] = "Usar condiciones",
    ["Unticked parks this entry: it keeps its settings but never shows. The gear holds moving, removing and per-entry settings."] = "Sin marcar, esta entrada queda aparcada: conserva sus ajustes pero nunca se muestra. El engranaje contiene mover, quitar y los ajustes por entrada.",
    ["Talent Window"] = "Ventana de talentos",
    ["Shows all three talent trees side by side in one window."] = "Muestra los tres árboles de talentos lado a lado en una sola ventana.",
    ["Points left: %d"] = "Puntos restantes: %d",
    ["TALENTS"] = "TALENTOS",
    ["Open Blizzard's talent window"] = "Abrir la ventana de talentos de Blizzard",
    ["For glyphs and everything this window does not cover."] = "Para glifos y todo lo que esta ventana no cubre.",
    ["|cffaaaaaaAll three talent trees side by side, with live ranks and click-to-learn. Glyphs stay in Blizzard's window, one button away.|r"] = "|cffaaaaaaLos tres árboles de talentos lado a lado, con rangos en vivo y aprendizaje con un clic. Los glifos siguen en la ventana de Blizzard, a un botón de distancia.|r",
    ["Replace Blizzard's talent window"] = "Reemplazar la ventana de talentos de Blizzard",
    ["Opening talents shows this window instead. Turn it off to get Blizzard's one-tree window back."] = "Al abrir los talentos se muestra esta ventana. Desactívalo para recuperar la ventana de un solo árbol de Blizzard.",
    ["Open talent window"] = "Abrir ventana de talentos",
    ["See-through"] = "Transparencia",
    ["Hide the box fill and labels while editing, so you can see the interface you are aligning. The thin borders stay."] = "Oculta el relleno y las etiquetas de las cajas al editar para que veas la interfaz que estás alineando. Los bordes finos se mantienen.",
    -- Patch notes 1.46.0
    ["Options"] = "Opciones",
    ["Talents"] = "Talentos",
    ["The page opens with two modes: Standard keeps Blizzard's bars with the skin rows, Modern runs the addon's own bars with a live preview, a per-bar background, button press and hover tints and an XP bar texture"] = "La página se abre con dos modos: Estándar conserva las barras de Blizzard con las filas de aspecto, Moderno usa las barras propias del addon con vista previa en vivo, fondo por barra, tintes de pulsación y de cursor en los botones y una textura para la barra de experiencia",
    ["Modern – Third player cast bar style: flat look with name and timer on the bar, plus bar texture, border, a coloured last tick and a latency readout"] = "Moderno – Tercer estilo de la barra de lanzamiento del jugador: aspecto plano con nombre y tiempo sobre la barra, más textura de barra, borde, un último tic coloreado y un indicador de latencia",
    ["The options page carries a live preview; clicking its icon or bar jumps to the matching section"] = "La página de opciones lleva una vista previa en vivo; hacer clic en su icono o en su barra salta a la sección correspondiente",
    ["Enchant and gem displays no longer displace each other on non-English clients, and Chinese enchant text is no longer cut mid-character"] = "Las indicaciones de encantamiento y gemas ya no se desplazan entre sí en clientes no ingleses, y el texto de encantamiento chino ya no se corta a mitad de carácter",
    ["Tracked entries sit two per row, each with a gear: park an entry without deleting it, move or remove it, set conditions, and override Only what I cast myself for that entry alone"] = "Las entradas seguidas van de dos en dos por fila, cada una con engranaje: aparcar una entrada sin borrarla, moverla o quitarla, poner condiciones y anular Solo lo que yo mismo lanzo solo para esa entrada",
    ["See-through – Hides the box fill and labels while editing, so you can see the interface you are aligning"] = "Transparencia – Oculta el relleno y las etiquetas de las cajas al editar para que veas la interfaz que estás alineando",
    ["Coordinates appear on the box while dragging or nudging, and the window being snapped to pulses white"] = "Al arrastrar o ajustar aparecen las coordenadas en la propia caja, y la ventana a la que se acopla parpadea en blanco",
    ["The loot window can be moved on Wrath clients"] = "La ventana de botín se puede mover en clientes Wrath",
    ["Widen window – Extra width so long names, notes and zones fit on one line"] = "Ensanchar ventana – Anchura extra para que nombres largos, notas y zonas quepan en una línea",
    ["The close glyph of every window is larger now"] = "El signo de cerrar de todas las ventanas es ahora más grande",
    ["Three tabs with a pinned live preview, a name-in-bar option and thousands separators on health numbers"] = "Tres pestañas con vista previa fija, una opción de nombre dentro de la barra y separadores de miles en las cifras de salud",
    ["Gear rows open inside their own column, aura rows align per row, helper tools share one tab, and the pinned page header of the last visited tab is cleared on switching"] = "Las filas de engranaje se abren dentro de su propia columna, las filas de auras se alinean por fila, las herramientas auxiliares comparten una pestaña, y la cabecera fijada de la última pestaña visitada se limpia al cambiar",
    ["Only the last five versions build at once; a button loads the older ones"] = "Solo se construyen las últimas cinco versiones a la vez; un botón carga las anteriores",
    ["Orientation, fill opacity, frame strata and a live preview on the options page"] = "Orientación, opacidad del relleno, capa del marco y una vista previa en la página de opciones",
    ["A profile string can carry a selection: chosen modules, the window layout, talent overrides, and the account-wide fonts and colours"] = "Una cadena de perfil puede llevar una selección: módulos elegidos, la disposición de ventanas, las anulaciones de talentos y las fuentes y colores de toda la cuenta",
    ["Per-rule switches with class-coloured names, a group scan for missing buffs, preferred food, flask and weapon oil, raid and dungeon thresholds, glow styles, scale and a live preview; middle-click hides a reminder until the next loading screen"] = "Interruptores por regla con nombres en color de clase, un escaneo del grupo para beneficios que faltan, comida, matraz y aceite de arma preferidos, umbrales para banda y mazmorra, estilos de brillo, escala y una vista previa; el clic central oculta un recordatorio hasta la siguiente pantalla de carga",
    ["Broken numeric values are removed before saving and reported at the next login. A single such value used to reset every setting of the account to defaults"] = "Los valores numéricos dañados se eliminan antes de guardar y se informan en el siguiente inicio de sesión. Un solo valor así restablecía todos los ajustes de la cuenta a los predeterminados",
    ["Totemic Recall stands as its own button after the elements on Wrath clients"] = "La retirada de tótems es ahora un botón propio tras los elementos en clientes Wrath",
    ["Talent Window – All three talent trees side by side with live ranks and click-to-learn on Wrath clients; glyphs stay one button away"] = "Ventana de talentos – Los tres árboles de talentos lado a lado con rangos en vivo y aprendizaje con un clic en clientes Wrath; los glifos quedan a un botón",
    ["The string is selected - press Ctrl+C to copy it."] = "La cadena está seleccionada: pulsa Ctrl+C para copiarla.",
    ["%d characters"] = "%d caracteres",
    ["Paste the string here with Ctrl+V."] = "Pega aquí la cadena con Ctrl+V.",
    ["String captured - %d characters."] = "Cadena capturada: %d caracteres.",
    ["Partial string: anything missing is taken from your active profile."] = "Cadena parcial: lo que falte se toma de tu perfil activo.",
    ["Unticked parts keep your current settings."] = "Las partes desmarcadas conservan tu configuración actual.",
    ["Profile '%s' imported. Switch to it now and reload the UI?"] = "Perfil '%s' importado. ¿Cambiar a él ahora y recargar la interfaz?",
    ["Switch and reload"] = "Cambiar y recargar",
    ["Save a backup copy"] = "Guardar una copia de seguridad",
    ["Creates a dated copy of the active profile as a restore point. Nothing switches - the copy just sits in the profile list."] = "Crea una copia con fecha del perfil activo como punto de restauración. No se cambia nada: la copia simplemente queda en la lista de perfiles.",
    ["Backup '%s' created."] = "Copia de seguridad '%s' creada.",
    ["Go back"] = "Atrás",
    ["Pixel-true plate size"] = "Tamaño de placa exacto en píxeles",
    ["Sizes the plates in screen pixels instead of interface units: height 27 is then 27 pixels on any monitor and UI scale."] = "Dimensiona las placas en píxeles de pantalla en lugar de unidades de interfaz: una altura de 27 son entonces 27 píxeles en cualquier monitor y escala.",
    -- Patch notes 1.47.0
    ["The boxes now cover their window exactly, in the same dark look as the rest of the interface, with the name centred and shown in orange when the window is docked to another one"] = "Las cajas ahora cubren su ventana con exactitud, con el mismo estilo oscuro que el resto de la interfaz, con el nombre centrado y en naranja cuando la ventana está anclada a otra",
    ["Outside the editor the small drag handle stays, so an unlocked cooldown bar still accepts dropped spells and test previews stay visible"] = "Fuera del editor se mantiene el asa pequeña, de modo que una barra de reutilización desbloqueada sigue aceptando hechizos arrastrados y las vistas previas de prueba quedan visibles",
    ["The cloak equipment slot was translated with the navigation word for back in six languages and now reads correctly everywhere"] = "La ranura de equipo de la capa estaba traducida en seis idiomas con la palabra de navegación para atrás y ahora se lee correctamente en todas partes",
    ["Pixel-true plate size – Sizes the plates in screen pixels, so height 27 is 27 pixels on any monitor and interface scale"] = "Tamaño de placa exacto en píxeles – Dimensiona las placas en píxeles de pantalla, de modo que una altura de 27 son 27 píxeles en cualquier monitor y escala de la interfaz",
    ["Plate sizes now mean exactly what the sliders say: the game no longer secretly enlarges the target's plate or shrinks distant ones, and the live preview matches the game — making the target larger is now solely the job of the target plate scale option"] = "Los tamaños de placa significan ahora exactamente lo que dicen los controles: el juego ya no agranda en secreto la placa del objetivo ni encoge las lejanas, y la vista previa coincide con el juego; agrandar el objetivo es ahora tarea exclusiva de la opción de escala de la placa del objetivo",
    ["Save a backup copy – One click keeps a dated copy of the active profile as a restore point"] = "Guardar una copia de seguridad – Un clic guarda una copia con fecha del perfil activo como punto de restauración",
    ["Exporting opens a proper window with the string already selected, and importing shows a preview first: rename the profile and untick the parts you do not want before anything is written"] = "Exportar abre una ventana propia con la cadena ya seleccionada, e importar muestra primero una vista previa: renombra el perfil y desmarca lo que no quieras antes de que se escriba nada",
    ["Export strings are compressed to a fraction of their old length and fit in a chat message; strings from older versions still import"] = "Las cadenas de exportación están comprimidas a una fracción de su longitud anterior y caben en un mensaje de chat; las cadenas de versiones antiguas se siguen importando",
    ["On the Wrath client the talent tooltip showed a placeholder instead of the description, and the talent key would open the window but not close it — both fixed"] = "En el cliente de Wrath el tooltip de talentos mostraba un marcador en lugar de la descripción, y la tecla de talentos abría la ventana pero no la cerraba; ambas cosas corregidas",
    ["%s Locked"] = "%s bloqueada",
    ["|cffffffffLOSS OF CONTROL|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffPÉRDIDA DE CONTROL|r\n|cffaaaaaaArrastra o usa las flechas|r",
    ["%.1f seconds"] = "%.1f segundos",
    ["Loss of control mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Movedor de pérdida de control activo. |cff9b6cffArrastra la caja morada|r o usa las |cff9b6cffflechas|r (MAYÚS = 5 px). Pulsa el botón otra vez para terminar.",
    ["Preview"] = "Vista previa",
    ["Loss of Control"] = "Pérdida de control",
    ["Shows what is controlling you right now -- stun, fear, root, silence, disarm or a school lockout -- with the effect icon, its name and the time left. Where two effects run at once the one that matters is shown large, and the next one as a small icon beside it."] = "Muestra lo que te está controlando ahora mismo: aturdimiento, miedo, raíces, silencio, desarme o una escuela bloqueada, con el icono del efecto, su nombre y el tiempo restante. Si hay dos efectos a la vez, el más importante se muestra grande y el siguiente como un icono pequeño al lado.",
    ["Show loss of control alert"] = "Mostrar aviso de pérdida de control",
    ["Show in"] = "Mostrar en",
    ["Arena and battlegrounds"] = "Arenas y campos de batalla",
    ["Arena only"] = "Solo en arenas",
    ["Name font size"] = "Tamaño de fuente del nombre",
    ["Timer font size"] = "Tamaño de fuente del tiempo",
    ["Background and red lines"] = "Fondo y líneas rojas",
    ["Show the next effect"] = "Mostrar el siguiente efecto",
    ["Profile changed. Use /reload when you are out of combat."] = "Perfil cambiado. Usa /reload cuando salgas de combate.",
    ["Profile keybind"] = "Atajo de teclado del perfil",
    ["Switches to this profile outside combat and then asks to reload the UI. Override bindings are restored at login."] = "Cambia a este perfil fuera de combate y luego pregunta si recargar la interfaz. Los atajos se restauran al iniciar sesión.",
    ["Use the global font"] = "Usar la fuente global",
    ["Name color"] = "Color del nombre",
    ["Timer color"] = "Color del tiempo",
    ["|cffffffffINTERRUPTS|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffINTERRUPCIONES|r\n|cffaaaaaaArrastra o usa las flechas|r",
    ["Interrupt bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Movedor de la barra de interrupciones activo. |cff9b6cffArrastra la caja morada|r o usa las |cff9b6cffflechas|r (MAYÚS = 5 px). Pulsa el botón otra vez para terminar.",
    ["Interrupts"] = "Interrupciones",
    ["Watches the combat log for enemy interrupts and starts a cooldown for each one, tracked per caster -- two enemies of the same class get an icon each. The border carries the caster's class colour."] = "Vigila el registro de combate en busca de interrupciones enemigas e inicia un tiempo de reutilización para cada una, por lanzador: dos enemigos de la misma clase reciben un icono cada uno. El borde lleva el color de clase del lanzador.",
    ["Show interrupt bar"] = "Mostrar la barra de interrupciones",
    ["Show interrupts that are still ready"] = "Mostrar también las interrupciones disponibles",
    ["Timer text on the icons"] = "Texto de tiempo en los iconos",
    ["Cooldown swipe on the icons"] = "Barrido de reutilización en los iconos",
    ["Only take over the key while a fishing pole is worn"] = "Ocupar la tecla solo con una caña equipada",
    ["Without a pole in hand the key keeps whatever you bound it to, so it stays usable outside fishing. A cast already in the water keeps the key. This switches off auto-equipping a pole, which needs the key exactly while none is worn."] = "Sin caña en la mano la tecla conserva lo que le hayas asignado, así que sigue siendo útil fuera de la pesca. Un lanzamiento ya en el agua mantiene la tecla. Esto desactiva equipar la caña automáticamente, porque eso necesita la tecla justo cuando no llevas ninguna.",
    ["Stand-in for an enemy frame: the side strip is placed by the settings below."] = "Marcador de posición de un marco enemigo: la tira lateral se coloca con los ajustes de abajo.",
    -- Patch notes 1.48.0
    ["Options Window"] = "Ventana de opciones",
    ["Loss of Control – Shows the stun, fear, root, silence or lockout holding you, with its icon, its name and the time left"] = "Pérdida de control – Muestra el aturdimiento, miedo, raíz, silencio o bloqueo que te retiene, con su icono, su nombre y el tiempo restante",
    ["Interrupts – Tracks enemy interrupts from the combat log, one icon per caster, bordered in the caster's class colour"] = "Interrupciones – Sigue las interrupciones enemigas en el registro de combate, un icono por lanzador, con el borde del color de su clase",
    ["Timer Text On The Icons – Seconds left on the interrupt icons, with their own font, outline and colour"] = "Texto de tiempo en los iconos – Segundos restantes en los iconos de interrupción, con su propia fuente, contorno y color",
    ["Cooldown Swipe On The Icons – Drop the sweeping shade and keep only the number"] = "Barrido de reutilización en los iconos – Quita la sombra que gira y deja solo el número",
    ["The icon strip beside the enemy frames has a live preview on the General tab. Those frames exist only inside an arena, so its sliders used to move something you could not see."] = "La tira de iconos junto a los marcos enemigos tiene una vista previa en vivo en la pestaña General. Esos marcos solo existen dentro de una arena, así que sus controles movían algo que no podías ver.",
    ["An unlocked mover box no longer vanished a moment after the button put it there. The box and a running preview now ignore the zone filter: you place a bar where you are standing, and that is rarely an arena."] = "Una caja de movimiento desbloqueada ya no desaparece un instante después de que el botón la muestre. La caja y una vista previa en curso ignoran ahora el filtro de zona: colocas una barra donde estás, y eso rara vez es una arena.",
    ["The pinned icon strip also appears on the Layout tab, where icon size, spacing, shape and zoom read back off it while the slider moves."] = "La tira de iconos fijada aparece ahora también en la pestaña Diseño, donde el tamaño, el espaciado, la forma y el zoom se leen en ella mientras mueves el control.",
    ["Moving Blizzard frames no longer marks every Edit Mode window as touched by this addon, which had the pet frame refused in combat. Selecting a layout caused it, and that ran on every editor entry even when nothing had been placed."] = "Mover marcos de Blizzard ya no marca cada ventana del modo de edición como tocada por este accesorio, lo que hacía que el juego rechazara mostrar el marco de mascota en combate. La causa era seleccionar un diseño, y eso ocurría en cada entrada al editor aunque nunca se hubiera colocado nada.",
    ["The icon picker has a close button, and no longer floats over the game after the character sheet is shut."] = "El selector de iconos tiene un botón de cierre y ya no flota sobre el juego después de cerrar la hoja de personaje.",
    ["Only Take Over The Key While A Fishing Pole Is Worn – Without a pole the key keeps whatever you bound it to"] = "Ocupar la tecla solo con una caña equipada – Sin caña la tecla conserva lo que le hayas asignado",
    ["The mouse wheel scrolls the sidebar and the page. The window also shrinks to fit a screen smaller than itself, which is what left it undraggable on a high interface scale."] = "La rueda del ratón desplaza la barra lateral y la página. La ventana además se reduce para caber en una pantalla más pequeña que ella, que era justo lo que la dejaba inamovible con una escala de interfaz alta.",
    ["Profile Keybind – Put a profile on a key and switch to it out of combat"] = "Atajo de teclado del perfil – Pon un perfil en una tecla y cambia a él fuera de combate",
    ["The bag sweep behind the food, flask and weapon oil reminders is kept until the bags change, instead of walking every bag three times over twice a second."] = "El barrido de bolsas detrás de los avisos de comida, frasco y aceite de arma se conserva hasta que cambian las bolsas, en lugar de recorrer todas las bolsas tres veces dos veces por segundo.",
    ["The modern player frame style no longer reaches into the pet and totem frames."] = "El estilo moderno del marco de jugador ya no toca los marcos de mascota ni de tótem.",
    ["Fine tuning for this slot"] = "Ajuste fino de esta posición",
    ["Slot settings"] = "Ajustes de la posición",
    ["Border settings"] = "Ajustes del borde",
    ["Border size"] = "Grosor del borde",
    ["How solid the empty part of the bar is."] = "Cuán sólida es la parte vacía de la barra.",
    ["Absorb settings"] = "Ajustes de absorción",
    ["Border around the cast bar"] = "Borde alrededor de la barra de lanzamiento",
    ["Off leaves the cast bar without its own outline; the health bar keeps one."] = "Desactivado deja la barra de lanzamiento sin contorno propio; la barra de vida conserva el suyo.",
    ["Top text"] = "Texto superior",
    ["Left text"] = "Texto izquierdo",
    ["Right text"] = "Texto derecho",
    ["Centred text"] = "Texto centrado",
    ["Unit name"] = "Nombre de la unidad",
    ["Main text positions"] = "Posiciones principales de texto",
    ["|cffaaaaaaOne thing per slot. The level rides at the name's left edge and follows it.|r"] = "|cffaaaaaaUna cosa por posición. El nivel va junto al borde izquierdo del nombre y lo sigue.|r",
    ["Health and cast bar"] = "Barra de vida y de lanzamiento",
    ["Health bar width"] = "Anchura de la barra de vida",
    ["Health bar height"] = "Altura de la barra de vida",
    ["Cast icon"] = "Icono de lanzamiento",
    ["Cast icon settings"] = "Ajustes del icono de lanzamiento",
    ["Cast background"] = "Fondo de lanzamiento",
    ["Cast bar border"] = "Borde de la barra de lanzamiento",
    ["Thickness of the cast bar's own border. 0 removes it; the health bar keeps its own."] = "Grosor del borde propio de la barra de lanzamiento. 0 lo quita; la barra de vida conserva el suyo.",
    ["Cast bar border colour"] = "Color del borde de la barra de lanzamiento",
    ["Cast timer"] = "Temporizador de lanzamiento",
    ["Cast timer settings"] = "Ajustes del temporizador",
    ["Cast bar Y offset"] = "Desplazamiento Y de la barra de lanzamiento",
    ["Cast colours and effects"] = "Colores y efectos de lanzamiento",
    ["The bar's colour while a spell is being cast."] = "El color de la barra mientras se lanza un hechizo.",
    ["More cast colours"] = "Más colores de lanzamiento",
    ["Interrupt ready"] = "Interrupción lista",
    ["Interrupt flash"] = "Destello de interrupción",
    ["Interrupt-ready hint"] = "Aviso: interrupción lista",
    ["Show cast bars in front of nameplates"] = "Mostrar barras de lanzamiento delante de las placas",
    ["Casts draw above every plate, so a cast you care about is never hidden behind another unit's bar."] = "Los lanzamientos se dibujan sobre todas las placas, para que uno importante nunca quede oculto tras la barra de otra unidad.",
    ["The enemy's cast bar flashes and reads 'Interrupted' for a moment when their cast is stopped."] = "La barra de lanzamiento del enemigo destella y muestra brevemente «Interrumpido» cuando su hechizo se detiene.",
    ["Interrupt flash settings"] = "Ajustes del destello de interrupción",
    ["Target, focus and hover effects"] = "Efectos de objetivo, foco y ratón",
    ["Target effect"] = "Efecto de objetivo",
    ["A coloured edge around the plate you have targeted."] = "Un borde de color alrededor de la placa que tienes como objetivo.",
    ["Target arrows"] = "Flechas de objetivo",
    ["Arrow settings"] = "Ajustes de las flechas",
    ["Target bar colour on"] = "Activar color del objetivo",
    ["Focus bar colour on"] = "Activar color del foco",
    ["A coloured edge around the plate you have set as your focus."] = "Un borde de color alrededor de la placa que has fijado como foco.",
    ["Mouseover effect"] = "Efecto al pasar el ratón",
    ["Mouseover effect settings"] = "Ajustes del efecto del ratón",
    ["General text"] = "Texto general",
    ["Debuff duration"] = "Duración de perjuicios",
    ["Buff duration"] = "Duración de beneficios",
    ["Crowd control duration"] = "Duración del control",
    ["Aura stacks"] = "Acumulaciones de auras",
    ["Timer text colour"] = "Color del temporizador",
    ["Stack text colour"] = "Color de las acumulaciones",
    ["Text settings"] = "Ajustes del texto",
    ["Spell target"] = "Objetivo del hechizo",
    ["Background settings"] = "Ajustes del fondo",
    ["Hide the gryphons"] = "Ocultar los grifos",
    ["Removes the two beasts at the ends of Blizzard's main action bar. The bar itself stays."] = "Quita las dos bestias de los extremos de la barra de acción original. La barra se mantiene.",
    ["Extra indicators"] = "Indicadores adicionales",
    ["Enemy colours"] = "Colores de enemigos",
    ["Enemy types"] = "Tipos de enemigo",
    ["The health bar colour a unit takes from its reaction to you."] = "El color que la barra toma de la actitud de la unidad hacia ti.",
    ["Neutral enemies"] = "Enemigos neutrales",
    ["Units that are not hostile until you make them so."] = "Unidades que no son hostiles hasta que tú las provocas.",
    ["Other nameplates"] = "Otras placas de nombre",
    ["Nameplate spacing"] = "Espaciado de las placas",
    ["|cffaaaaaaThe game's own settings, changed live and not part of the profile — except the hitbox. Not changeable in combat.|r"] = "|cffaaaaaaAjustes del propio juego, aplicados al momento y fuera del perfil — salvo el área de clic. No se pueden cambiar en combate.|r",
    ["Stackable nameplates"] = "Placas apilables",
    ["Extra aura options"] = "Opciones de auras adicionales",
    ["Target and focus effects"] = "Efectos de objetivo y foco",
    ["Plate scale while casting"] = "Tamaño de la placa al lanzar",
    ["A casting unit's plate grows to this size, so the one that matters stands out. 100 = off."] = "La placa de una unidad que lanza crece a este tamaño, para que destaque la que importa. 100 = desactivado.",
    ["Opacity while casting"] = "Opacidad al lanzar",
    ["A casting unit's plate is at least this opaque, even when something else is targeted."] = "La placa de una unidad que lanza mantiene al menos esta opacidad, aunque tengas otro objetivo.",
    ["The unit's name gives way to the spell name for as long as the cast runs."] = "El nombre de la unidad deja sitio al nombre del hechizo mientras dura el lanzamiento.",
    ["Active talent group"] = "Grupo de talentos activo",
    ["Left-click: show this talent group"] = "Clic izquierdo: mostrar este grupo de talentos",
    ["Right-click: activate this talent group"] = "Clic derecho: activar este grupo de talentos",
    ["Talent group %d (not active)"] = "Grupo de talentos %d (inactivo)",
    ["Talents can only be learned in the active talent group."] = "Los talentos solo pueden aprenderse en el grupo de talentos activo.",
    ["Talent groups cannot be switched in combat."] = "No se puede cambiar de grupo de talentos en combate.",
    ["This client refused to switch the talent group."] = "Este cliente rechazó el cambio de grupo de talentos.",
    ["Input line above the chat"] = "Línea de entrada encima del chat",
    ["Puts the chat input line above the message area instead of below it. The panel and the tab bar follow it."] = "Coloca la línea de entrada encima del área de mensajes en lugar de debajo. El panel y la barra de pestañas la siguen.",
    ["Own background for the input line"] = "Fondo propio para la línea de entrada",
    ["Draws the input line on our own dark background instead of Blizzard's. The dark background panel already covers the input line, so this shows once that panel is off."] = "Dibuja la línea de entrada sobre un fondo oscuro propio en lugar del de Blizzard. El panel de fondo oscuro ya cubre la línea de entrada, así que esto se ve cuando ese panel está desactivado.",
    ["Addon buttons"] = "Botones de addons",
    ["Click to show or hide the collected buttons."] = "Haz clic para mostrar u ocultar los botones recogidos.",
    ["Where other addons' minimap buttons sit: around the map, hidden until the mouse is over it, or gathered in one box under it."] = "Dónde se sitúan los botones de minimapa de otros addons: alrededor del mapa, ocultos hasta pasar el ratón por encima, o reunidos en una caja debajo.",
    ["Around the minimap"] = "Alrededor del minimapa",
    ["Only on mouseover"] = "Solo al pasar el ratón",
    ["Collected in a box"] = "Reunidos en una caja",
    -- Patch notes 1.49.0
    ["Hide The Gryphons – Takes the two beasts off the ends of Blizzard's main bar without dimming anything else"] = "Ocultar los grifos – Quita las dos bestias de los extremos de la barra principal de Blizzard sin oscurecer nada más",
    ["Switching the module off now switches it off. Its handlers are registered when the addon loads, so a module that was already off at login never ran its shutdown: being stunned in a battleground still popped the loss-of-control display, and the interrupt bar filled up and never emptied again, because the ticker that clears its icons only starts when the module is switched on."] = "Desactivar el módulo ahora lo desactiva de verdad. Sus manejadores se registran al cargar, así que un módulo que ya estaba desactivado al entrar nunca ejecutaba su apagado: quedar aturdido en un campo de batalla hacía aparecer igualmente el aviso de pérdida de control, y la barra de interrupciones se llenaba y no volvía a vaciarse, porque el temporizador que limpia sus iconos solo arranca al activar el módulo.",
    ["The interrupt bar no longer reads the whole world's combat log. It registered on load and never unregistered, so every combat line anywhere — several thousand a second in a raid — was taken apart for a bar whose own default is arena and battlegrounds only. It uses the same zone filter as the display beside it now."] = "La barra de interrupciones ya no lee el registro de combate del mundo entero. Se registraba al cargar y nunca se daba de baja, así que cada línea de combate en cualquier parte — varios miles por segundo en una banda — se desmontaba para una barra cuyo propio valor por defecto es arena y campos de batalla. Ahora usa el mismo filtro de zona que el aviso que tiene al lado.",
    ["Switching the module on inside an arena counts as arriving. The zone decision used to live in the loading screen alone, so anyone who enabled it while already in there got no diminishing-returns ticker until the next one."] = "Activar el módulo dentro de una arena cuenta como llegar. La decisión de zona vivía solo en la pantalla de carga, así que quien lo activaba ya estando dentro no tenía temporizador de reducción decreciente hasta la siguiente.",
    ["The item level text size slider works again. It looked for the numbers in two places it hoped they would be, and where a client parents its paper doll buttons elsewhere it found none and quietly did nothing — which from the outside is indistinguishable from the text simply being too small."] = "El control del tamaño del texto de nivel de objeto vuelve a funcionar. Buscaba los números en dos sitios donde esperaba encontrarlos, y donde un cliente cuelga sus botones de equipo de otro sitio no encontraba ninguno y no hacía nada en silencio — algo que desde fuera no se distingue de que el texto sea simplemente demasiado pequeño.",
    ["Input Line Above The Chat – Puts the input line over the message area instead of under it, with the panel and the tab bar following it; Wrath client only"] = "Línea de entrada encima del chat – Coloca la línea de entrada sobre el área de mensajes en lugar de debajo, y el panel y la barra de pestañas la siguen; solo en el cliente Wrath",
    ["Own Background For The Input Line – Draws the input line on its own dark background instead of Blizzard's, which is what you saw once the dark panel was off; Wrath client only"] = "Fondo propio para la línea de entrada – Dibuja la línea de entrada sobre un fondo oscuro propio en vez del de Blizzard, que es el que veías al desactivar el panel oscuro; solo en el cliente Wrath",
    ["Icon zoom is now called Icon crop and reads in percent. It is the same question the nameplate sliders ask, and it was answering in hundredths while they answered in percent."] = "El zoom del icono ahora se llama recorte del icono y se lee en porcentaje. Es la misma pregunta que hacen los controles de las placas de nombre, y se respondía en centésimas mientras aquellos respondían en porcentaje.",
    ["The extra width belongs to the friends tab alone now. The row texts there stretch with the window, but the column headers on the who, guild and raid tabs sit at fixed offsets and stay put, so every point of width you added landed in an empty right half. Those three tabs go back to Blizzard's own proportions, which is what their columns were measured for."] = "El ancho adicional pertenece ahora solo a la pestaña de amigos. Los textos de las filas se estiran con la ventana, pero los encabezados de columna de las pestañas de búsqueda, hermandad y banda están en posiciones fijas y no se mueven, así que cada punto de ancho añadido acababa en una mitad derecha vacía. Esas tres pestañas vuelven a las proporciones de Blizzard, para las que se midieron sus columnas.",
    ["The set list and the icon picker take the character panel's style. In the classic style they used to be a flat dark surface with a purple edge holding Blizzard's red buttons — two materials in a hand's width. They now carry Blizzard's dialog frame there and stand in the same material as the window they hang off, while the modern style keeps the flat look."] = "La lista de conjuntos y el selector de iconos adoptan el estilo de la hoja de personaje. En el estilo clásico eran una superficie oscura y plana con borde morado que contenía los botones rojos de Blizzard — dos materiales en un palmo. Ahora llevan allí el marco de diálogo de Blizzard y están en el mismo material que la ventana de la que cuelgan, mientras que el estilo moderno mantiene el aspecto plano.",
    ["The character panel no longer breaks when the sidebar builds its first set row. The marker bar on the row still reached for an accent colour that had been removed, so the list stayed empty and the panel came up bare."] = "La hoja de personaje ya no se rompe cuando la barra lateral construye su primera fila de conjunto. La barra marcadora de la fila seguía buscando un color de acento que había sido retirado, así que la lista quedaba vacía y la ventana salía desnuda.",
    ["Addon Buttons – Choose where other addons' buttons sit: around the map, hidden until you mouse over it, or gathered in one box below it; Wrath client only"] = "Botones de addons – Elige dónde se sitúan los botones de otros addons: alrededor del mapa, ocultos hasta pasar el ratón por encima, o reunidos en una caja debajo; solo en el cliente Wrath",
    ["Icon Crop (%) – How much of the border the game bakes into its icons is cut away, set per aura row and for the cast bar icon"] = "Recorte del icono (%) – Cuánto se recorta del borde que el juego hornea en sus iconos, ajustable por fila de auras y para el icono de la barra de lanzamiento",
    ["The rounded bar style no longer leaves dead space at both ends. The round shape does not fill its own image — a transparent border runs all the way round it — and stretching that border across a wide, short bar put roughly eleven points of empty bar at each end and barely one above and below, which is why it showed up sideways and not upright."] = "El estilo de barra redondeada ya no deja espacio muerto en ambos extremos. La forma redonda no llena su propia imagen — un borde transparente la rodea por completo —, y estirar ese borde sobre una barra ancha y baja dejaba unos once puntos de barra vacía en cada extremo y apenas uno arriba y abajo, por eso se notaba en horizontal y no en vertical.",
    ["The options page is cut by question instead of by mechanism. Sixteen sections had settings that belong together lying far apart, with the bar texture under one heading and the cast bar's texture under another; eight settings were reachable from two sections at once."] = "La página de opciones está cortada por preguntas en vez de por mecánica. Dieciséis secciones tenían ajustes que van juntos muy separados, con la textura de la barra bajo un encabezado y la de la barra de lanzamiento bajo otro; ocho ajustes eran alcanzables desde dos secciones a la vez.",
    ["Every text on the plate sits in a slot now, the way the aura rows already did: top, left, right or centred, filled with the unit name or the health text. Four on/off switches became position pickers, each starting on the place its text already had."] = "Cada texto de la placa ocupa ahora una posición, igual que ya hacían las filas de auras: arriba, izquierda, derecha o centrado, con el nombre de la unidad o el texto de vida. Cuatro interruptores se han convertido en selectores de posición, cada uno empezando en el lugar que su texto ya tenía.",
    ["The stacking dropdown had no readable value at all. It was reading a setting this client does not have; the one it does have is now read and written, measured in the running game."] = "El menú desplegable de apilamiento no mostraba ningún valor legible. Leía un ajuste que este cliente no tiene; el que sí tiene ahora se lee y se escribe, medido en el juego en marcha.",
    ["A gear icon on a half-width row opens a small floating window instead of unfolding inside the cell. Half a cell has no room for a slider, and six of them had been squeezed into stubs."] = "Un engranaje en una fila de media anchura abre una pequeña ventana flotante en vez de desplegarse dentro de la celda. Media celda no tiene sitio para un deslizador, y seis de ellos habían quedado reducidos a muñones.",
    ["Colour swatches, eyes, gears and arrows sit directly beside the control they belong to rather than in the icon strip on the right, which stays reserved for the gear and the info dot."] = "Las muestras de color, los ojos, los engranajes y las flechas están justo al lado del control al que pertenecen, en vez de en la tira de iconos de la derecha, que queda reservada para el engranaje y el punto de información.",
    ["On the Wrath client the module stands down completely and the client keeps its own window. Our restyle addresses Blizzard's widgets by name and by region number, and behind those names that client has a different anatomy: black holes where the hidden regions used to be, a stretched title bar, dropdowns over the recipe list — and no error, because nothing throws, it simply lands on the wrong widgets."] = "En el cliente Wrath el módulo se retira por completo y el cliente conserva su propia ventana. Nuestro rediseño se dirige a los elementos de Blizzard por nombre y por número de región, y detrás de esos nombres ese cliente tiene otra anatomía: agujeros negros donde estaban las regiones ocultas, una barra de título estirada, desplegables sobre la lista de recetas — y ningún error, porque nada falla, simplemente aterriza en los elementos equivocados.",
    ["Talent group buttons run down the right edge, one for each group you have bought. Left-click shows a group, right-click activates it, the same split Blizzard's own window uses. Talents can only be learned in the active group, so a click in the preview does nothing and the tooltip says so beforehand."] = "Por el borde derecho corren botones de grupos de talentos, uno por cada grupo que hayas comprado. Clic izquierdo muestra un grupo, clic derecho lo activa, el mismo reparto que usa la propia ventana de Blizzard. Los talentos solo pueden aprenderse en el grupo activo, así que un clic en la vista previa no hace nada y la ayuda emergente lo dice antes.",
    ["The tab carries a book instead of a question mark. That mark is Blizzard's placeholder for a missing icon and read like a defect."] = "La pestaña lleva un libro en vez de un signo de interrogación. Esa marca es el marcador de posición de Blizzard para un icono ausente y parecía un defecto.",
    ["Glyphs"] = "Glifos",
    ["CHARACTER"] = "Personaje",
    ["Packs the selected bar setup into a string you can pass on. Slots, macros and key bindings travel with it."] = "Empaqueta el conjunto de barras seleccionado en una cadena que puedes compartir. Las asignaciones, las macros y los atajos viajan con ella.",
    ["Reads a bar setup string into your library. Putting it onto your bars stays a separate step."] = "Lee una cadena de conjunto de barras y la añade a tu biblioteca. Aplicarla a tus barras sigue siendo un paso aparte.",
    ["The bar setup string is damaged."] = "La cadena del conjunto de barras está dañada.",
    ["This is not a bar setup string."] = "Esto no es una cadena de conjunto de barras.",
    ["Bar setup '%s' imported."] = "Conjunto de barras '%s' importado.",
    ["Macros left alone: the switch above is off."] = "Macros sin tocar: el interruptor de arriba está desactivado.",
    ["Macros: %d restored, |cffff8800%d failed|r -- the macro list may be full."] = "Macros: %d restauradas, |cffff8800%d fallidas|r: puede que la lista de macros esté llena.",
    ["Macros: %d restored."] = "Macros: %d restauradas.",
    ["Key bindings left alone: the switch above is off."] = "Atajos sin tocar: el interruptor de arriba está desactivado.",
    ["Key bindings: %d applied."] = "Atajos de teclado: %d aplicados.",
    ["Bar setup '%s' saved: %d slots, %d macros, %d key bindings."] = "Conjunto de barras '%s' guardado: %d espacios, %d macros, %d atajos de teclado.",
    ["|cffff8800No key bindings were captured.|r This client may not report them."] = "|cffff8800No se capturó ningún atajo de teclado.|r Puede que este cliente no los informe.",
    -- Patch notes 1.50.0
    ["Export as string – Packs the selected setup into a string you can pass on, with its slots, macros and key bindings"] = "Exportar como texto – Empaqueta el conjunto seleccionado en una cadena que puedes compartir, con sus espacios, macros y atajos de teclado",
    ["Import from string – Reads someone else's setup into your library; a name you already use gets a number rather than being overwritten"] = "Importar desde texto – Lee el conjunto de otra persona en tu biblioteca; un nombre que ya uses recibe un número en lugar de sobrescribirse",
    ["An imported setup is rebuilt entry by entry before it is stored. The restore walks every entry, so a malformed one would have thrown in the middle of a run with part of your bars already changed. Broken entries are dropped, the rest still arrives."] = "Un conjunto importado se reconstruye entrada por entrada antes de guardarse. La restauración recorre cada entrada, así que una malformada habría fallado a mitad del proceso con parte de tus barras ya cambiadas. Las entradas rotas se descartan y el resto llega igualmente.",
    ["Saving and loading say what they did. Both had been counting their work all along and throwing the numbers away, so a setup whose macros all failed looked exactly like one that had none, and a save that captured no key bindings said nothing at all."] = "Guardar y cargar dicen lo que han hecho. Ambos llevaban todo el tiempo contando su trabajo y tirando los números: un conjunto cuyas macros fallaban todas se veía igual que uno sin macros, y un guardado que no capturó ningún atajo no decía nada.",
    ["The character window can be placed by hand on the Wrath client. Blizzard's editor does not own that window, so it takes the same direct route the loot window already uses; one box moves the character, reputation and skills tabs together, and the stats panel and set list travel with it."] = "La ventana de personaje se puede colocar a mano en el cliente Wrath. El editor de Blizzard no es dueño de esa ventana, así que toma la misma vía directa que ya usa la ventana de botín; una caja mueve las pestañas de personaje, reputación y habilidades a la vez, y el panel de estadísticas y la lista de conjuntos viajan con ella.",
    ["The window starts wide on the Wrath client. The slider has always gone to 400 — it simply started at nothing, so the extra room only ever reached whoever went looking for it."] = "La ventana empieza ancha en el cliente Wrath. El control siempre ha llegado a 400: simplemente empezaba en nada, así que el espacio extra solo llegaba a quien iba a buscarlo.",
    ["The glyph page opens from a button under the talent group buttons, and it is dark now. The rune circle is dimmed rather than removed, because it is what makes that page recognisable; the sockets take the accent colour, and the glyph artwork and the pickup highlight stay as they are."] = "La página de glifos se abre con un botón bajo los botones de grupo de talentos, y ahora es oscura. El círculo rúnico se atenúa en lugar de quitarse, porque es lo que hace reconocible esa página; los engarces toman el color de acento, y el arte del glifo y el resalte al cogerlo se quedan como están.",
    ["The talent group button shows its tree's icon instead of a question mark. It asked for that icon through an interface that does not answer on every client, and fell back to the placeholder; the answer is now worked out from the ranks themselves, which cannot be misread."] = "El botón de grupo de talentos muestra el icono de su árbol en vez de un signo de interrogación. Lo pedía a través de una interfaz que no responde en todos los clientes y recurría al marcador de posición; ahora la respuesta se deduce de los propios rangos, que no se pueden malinterpretar.",
    ["The level number on the player frame sits where the client puts it on the Wrath client. Our two anchors are measured against one frame sheet, and where a different one ships, the number landed beside the portrait — the client keeps that anchor itself there anyway, moving it as the rest and PvP icons come and go."] = "El número de nivel del marco de jugador queda donde lo pone el cliente en el cliente Wrath. Nuestros dos anclajes están medidos contra una hoja de marco, y donde se distribuye otra, el número acababa junto al retrato: allí el cliente mantiene ese anclaje por su cuenta y lo mueve según aparecen y desaparecen los iconos de descanso y JcJ.",

    -- Character Panel: socket strip
    ["Socket strip under the window"] = "Barra de ranuras bajo la ventana",
    ["Puts a strip with every socket of your equipped gear under the character window. Click a socket to put a gem from your bags into it. Stays empty on clients whose game has no gems."] = "Coloca bajo la ventana de personaje una barra con todas las ranuras de tu equipo. Haz clic en una ranura para engarzar en ella una gema de tus bolsas. Permanece vacía en clientes cuyo juego no tiene gemas.",
    ["Choose a gem"] = "Elige una gema",
    ["No gems in your bags."] = "No hay gemas en tus bolsas.",
    ["Empty socket"] = "Ranura vacía",
    ["Click to pick a gem from your bags."] = "Haz clic para elegir una gema de tus bolsas.",
    ["Cannot socket gems in combat."] = "No se pueden engarzar gemas en combate.",
    ["Close the socketing window first."] = "Cierra primero la ventana de engarce.",
    -- Patch notes 1.51.0
    ["Socket strip under the window – A row of every socket on your equipped gear, hung under the character window; click a socket to put a gem from your bags into it"] = "Barra de ranuras bajo la ventana – Una fila con todas las ranuras de tu equipo, bajo la ventana de personaje; haz clic en una ranura para engarzar en ella una gema de tus bolsas",
    ["The enchant text on armour slots reads the enchant again instead of the item's difficulty tag. The filter took the first green line of the tooltip, and where an item carries a tag that tag stands above the enchant — so every such slot showed the tag, while a weapon two rows down showed its enchant correctly because nothing stood in front of it. The tag and the client's bracketed hints are both recognised now, in every language rather than only in English and German."] = "El texto de encantamiento en las ranuras de armadura vuelve a mostrar el encantamiento en lugar de la marca de dificultad del objeto. El filtro tomaba la primera línea verde de la descripción, y cuando un objeto lleva esa marca, la marca está por encima del encantamiento — así que cada ranura mostraba la marca, mientras un arma dos filas más abajo mostraba el suyo correctamente porque no había nada delante. La marca y los avisos entre corchetes angulares del cliente se reconocen ahora ambos, y en todos los idiomas en vez de solo en inglés y alemán.",
    ["The set list no longer casts a shadow past its own frame. What looked like the background standing out over the border was a drop shadow: not an outline but four filled rectangles reaching up to seven pixels beyond the frame on every side, and behind Blizzard's dialog frame there was nothing for it to fall on. It is gone in both looks."] = "La lista de conjuntos ya no proyecta una sombra más allá de su propio marco. Lo que parecía un fondo saliéndose del borde era una sombra: no un contorno, sino cuatro rectángulos rellenos que llegaban hasta siete píxeles más allá del marco por cada lado, y detrás del marco de diálogo de Blizzard no había nada sobre lo que caer. Ha desaparecido en ambos estilos.",
    ["In the Classic+ look the dark ground stopped short of the ornate line instead of ending on it, and so showed past the frame on every side."] = "En el estilo Classic+ el fondo oscuro terminaba antes de la línea decorada en lugar de sobre ella, y por eso sobresalía del marco por todos los lados.",

    -- Nameplates: layout preset + health text content
    ["Apply this arrangement"] = "Aplicar esta disposición",
    ["Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, and gives the cast bar its icon, its remaining time and its target. Your current arrangement is saved first and the button beside this one brings it back."] = "Coloca el nombre de la unidad y el valor de salud dentro de la barra, el control de masas a su izquierda, las penalizaciones entrantes encima de este y las mejoras a su derecha, y da a la barra de lanzamiento su icono, su tiempo restante y su objetivo. Tu disposición actual se guarda antes y el botón de al lado la devuelve.",
    ["Restore my arrangement"] = "Restaurar mi disposición",
    ["Puts every text and aura position back to what it was before the arrangement was applied, and removes the saved copy. Anything you moved by hand since then goes back as well."] = "Devuelve cada posición de texto y de aura a como estaba antes de aplicar la disposición, y elimina la copia guardada. Todo lo que hayas movido a mano desde entonces vuelve también.",
    ["Nameplate layout applied. The button beside it puts your old one back."] = "Disposición de placas de nombre aplicada. El botón de al lado devuelve la anterior.",
    ["Nameplate layout restored."] = "Disposición de placas de nombre restaurada.",
    ["Shows"] = "Muestra",
    ["Current health"] = "Salud actual",
    ["Current and maximum"] = "Actual y máxima",
    ["Current and percent"] = "Actual y porcentaje",
    ["Separator"] = "Separador",
    ["What goes between the two numbers, when the row above is set to current and percent."] = "Lo que va entre los dos números, cuando la fila de arriba está en actual y porcentaje.",
    ["Brackets"] = "Paréntesis",
    ["Vertical bar"] = "Barra vertical",
    ["Dash"] = "Guion",
    ["Space"] = "Espacio",
    -- Patch notes 1.52.0
    ["The own background for the input line is offered on every client. It was limited to one client generation, and the code already said it would work everywhere."] = "El fondo propio para la línea de entrada se ofrece en todos los clientes. Estaba limitado a una generación de cliente, y el código ya decía que funcionaría en todas partes.",
    ["The icon borders are pixel-exact. The border there is not a texture of its own but the rim of a plate behind the icon, so the two have to sit on the same pixel grid, the thickness has to be counted in pixels rather than frame units, and the icon size and spacing have to begin on whole pixels. None of the three was true, which is why a rim came out two pixels on one edge and none on the opposite."] = "Los bordes de los iconos son exactos al píxel. Ahí el borde no es una textura propia sino el reborde de una placa detrás del icono, así que ambos han de estar en la misma rejilla de píxeles, el grosor ha de contarse en píxeles y no en unidades de marco, y el tamaño y la separación han de empezar en píxeles enteros. Ninguna de las tres cosas se cumplía, por lo que un reborde salía de dos píxeles en un lado y de ninguno en el opuesto.",
    ["Apply this arrangement – Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, with the cast bar carrying its icon, its remaining time and its target"] = "Aplicar esta disposición – Coloca el nombre de la unidad y el valor de salud dentro de la barra, el control de masas a su izquierda, las penalizaciones entrantes encima y las mejoras a su derecha, y la barra de lanzamiento lleva su icono, su tiempo restante y su objetivo",
    ["The unit name was hidden behind the health bar fill as soon as a text slot put it inside the bar. The name and the health value hang from different parents: the value is created on the bar, the name on the plate, and the bar is a child of the plate — so it draws over anything the plate draws. While the name only ever sat above the bar this never showed. It has its own layer now, above the bar but not attached to it, because name-only mode hides that bar and a text parented to a hidden frame would go with it."] = "El nombre de la unidad quedaba oculto tras el relleno de la barra de salud en cuanto una ranura de texto lo colocaba dentro de ella. El nombre y el valor de salud cuelgan de padres distintos: el valor se crea sobre la barra, el nombre sobre la placa, y la barra es hija de la placa, de modo que dibuja por encima de todo lo que dibuja la placa. Mientras el nombre solo se situó encima de la barra, esto nunca se vio. Ahora tiene su propia capa, sobre la barra pero sin depender de ella, porque el modo de solo nombre oculta esa barra y un texto colgado de un marco oculto se iría con él.",
    ["The health text has its controls back: what it shows, and which mark goes between the two numbers. Both were still being read and had been unreachable since the page was rebuilt."] = "El texto de salud recupera sus controles: qué muestra y qué signo va entre los dos números. Ambos se seguían leyendo y eran inalcanzables desde que se rehízo la página.",
    ["The active talent group was always reported as the first one on clients that do not carry the newer interface for it. Everything behind that believed group one was running: the header called the group you were standing in not active, the activate button offered to switch to the one already on, and the switch reported success while changing nothing. Five files ask that same question, so profile overrides and bar setups were reading it too."] = "El grupo de talentos activo se informaba siempre como el primero en clientes que no llevan la interfaz más nueva para ello. Todo lo que hay detrás creía que corría el grupo uno: la cabecera llamaba no activo al grupo en el que estabas, el botón de activar ofrecía cambiar al que ya estaba puesto, y el cambio informaba de éxito sin cambiar nada. Cinco archivos hacen esa misma pregunta, así que las anulaciones de perfil y las configuraciones de barras también leían de ahí.",
    ["The glyph page stands permanently beside the window. It is lifted out of Blizzard's talent frame, where it lives inside the scroll area of the very window we replace, and handed back when ours closes."] = "La página de glifos está permanentemente junto a la ventana. Se extrae del marco de talentos de Blizzard, donde vive dentro del área de desplazamiento de la misma ventana que sustituimos, y se devuelve cuando se cierra la nuestra.",
    ["The separate glyph button is gone with it. Its only job was to send you to the page that now stands in front of you."] = "El botón de glifos aparte desaparece con ello. Su única tarea era enviarte a la página que ahora está delante de ti.",
    ["A band under the header carries the activate button and the name of the talent group on screen. Until now switching existed only as a right-click on the small side icons, and nothing announced it."] = "Una banda bajo la cabecera lleva el botón de activar y el nombre del grupo de talentos en pantalla. Hasta ahora el cambio existía solo como clic derecho en los pequeños iconos laterales, y nada lo anunciaba.",
    ["Form paging"] = "Paginación por forma",
    ["Keep the main bar on its page in every form"] = "Mantener la barra principal en su página en todas las formas",
    ["|cffaaaaaaCat, bear, stealth, stances and Shadowform normally swap the main bar to their own page. Switch this off to keep the bar you built through every form.|r"] = "|cffaaaaaaGato, oso, sigilo, actitudes y Forma de las Sombras cambian normalmente la barra principal a su propia página. Desactiva esto para mantener en todas las formas la barra que has creado.|r",
    -- Patch notes 1.52.1
    ["Keep the main bar on its page in every form – Cat, bear, stealth, stances and Shadowform stop swapping action bar 1 to a page of their own"] = "Mantener la barra principal en su página en todas las formas – Felino, oso, sigilo, actitudes y Forma de las Sombras dejan de cambiar la barra de acción 1 a una página propia",
    ["The ticker that paints cooldown dimming and range colouring no longer walks switched-off bars. It read and repainted every action bar five times a second, including the ones whose buttons nobody can see, so running two bars cost as much as running all of them."] = "El temporizador que dibuja el atenuado por reutilización y el coloreado por alcance ya no recorre las barras desactivadas. Leía y repintaba cada barra de acción cinco veces por segundo, incluidas aquellas cuyos botones nadie puede ver, así que llevar dos barras costaba lo mismo que llevarlas todas.",
    ["Leaving a button no longer builds a fresh check each time. The check only ever reads the bar, not the button, so it is built once per bar and shared by all of its buttons."] = "Salir de un botón ya no construye una comprobación nueva cada vez. La comprobación solo lee la barra, no el botón, así que se construye una vez por barra y la comparten todos sus botones.",
    ["The opponent frames are left alone unless you actually asked for a different arrangement. They are protected frames: anchoring one from our side is allowed outside a fight, but it marks the frame for the rest of the session, and the next time the default interface repositions it during a round its own call is refused and the block is reported against us. There is no way to anchor a protected frame without leaving that mark, so an untouched setup now keeps the default stacking. Order, spacing, grow direction and slot offsets all still work — the message becomes the price of a feature you asked for rather than something every arena hands out for free."] = "Los marcos de los oponentes se dejan en paz salvo que hayas pedido realmente otra disposición. Son marcos protegidos: anclar uno desde nuestro lado está permitido fuera del combate, pero marca el marco durante el resto de la sesión, y la próxima vez que la interfaz predeterminada lo recoloque en plena ronda, su propia llamada es rechazada y el bloqueo se nos atribuye a nosotros. No hay forma de anclar un marco protegido sin dejar esa marca, así que una configuración intacta conserva ahora el apilado predeterminado. El orden, el espaciado, la dirección de crecimiento y los desplazamientos de ranura siguen funcionando: el mensaje pasa a ser el precio de una función que has pedido, en vez de algo que toda arena reparte gratis.",
    ["Move up and move down work again on a category you switched off and back on. The order list was filled once, while it was still empty, so anything that did not exist at that moment never got an entry, and its arrows then did nothing at all for the rest of the session without saying so."] = "Subir y bajar vuelven a funcionar en una categoría que desactivaste y volviste a activar. La lista de orden se rellenaba una sola vez, mientras aún estaba vacía, así que lo que no existía en ese momento nunca obtenía una entrada, y sus flechas no hacían nada durante el resto de la sesión sin decirlo.",
    ["Switching a module off releases its event handlers again. The note recording which module owns a handler stayed behind when the handler was unregistered, and that note kept a hard reference to every handler the module had ever registered."] = "Desactivar un módulo vuelve a liberar sus manejadores de eventos. La nota que registra a qué módulo pertenece un manejador se quedaba al darlo de baja, y esa nota mantenía una referencia fuerte a cada manejador que el módulo hubiera registrado alguna vez.",
    -- Patch notes 1.52.2
    ["Casting out of the spell book keeps working after the book was opened from the micro menu. Our micro buttons are stand-ins that hand the click on to the default button behind them, which runs everything that follows inside our own call — and for the spell book that ends in the book writing down which half of itself it is showing. That note then counted as ours, the book reads it on every click on a spell, and so every cast from the book was refused as coming from an addon. Out of combat as well, for the rest of the session, until the interface was reloaded. Opening the book by its key was never affected. The micro menu now carries the default button itself, wearing our icon, so nothing is handed through us any more."] = "Lanzar hechizos desde el libro de hechizos sigue funcionando después de abrirlo desde el micromenú. Nuestros botones del micromenú son sustitutos que pasan el clic al botón original que hay detrás, con lo que todo lo que sigue se ejecuta dentro de nuestra propia llamada — y en el libro de hechizos eso acaba con el libro anotando qué mitad de sí mismo está mostrando. Esa nota pasaba a contar como nuestra, el libro la lee en cada clic sobre un hechizo, y así todo lanzamiento desde el libro se rechazaba por venir de un addon. También fuera de combate, durante el resto de la sesión, hasta recargar la interfaz. Abrir el libro con su tecla nunca se vio afectado. El micromenú lleva ahora el botón original en persona, con nuestro icono, de modo que ya no se pasa nada a través de nosotros.",
    ["Pointing at a bag slot shows the tooltip of the bag itself — quality colour, how much it holds, everything the item carries — with the click hints under it, instead of the bare name. In the inventory window as well as at the bank, which had drifted apart although the two bars are the same thing."] = "Al apuntar a una ranura de bolsa aparece la descripción de la bolsa misma — color de calidad, cuánto guarda, todo lo que trae el objeto — con las indicaciones de clic debajo, en lugar del nombre a secas. Tanto en la ventana de inventario como en el banco, que se habían separado aunque las dos barras son lo mismo.",
    ["The bar in the inventory window takes bags now, the way the one at the bank already did: drag a bag onto a slot to put it there, or left-click a slot with a bag on the cursor. Right-click with an empty hand takes the bag off again, and left-click with an empty hand still shows and hides it. The backpack and the keyring are not slotted bags, so they accept nothing and are not offered the right-click line in the first place."] = "La barra de la ventana de inventario acepta bolsas, igual que ya hacía la del banco: arrastra una bolsa a una ranura para colocarla ahí, o haz clic izquierdo en una ranura con una bolsa en el cursor. El clic derecho con la mano vacía vuelve a sacar la bolsa, y el clic izquierdo con la mano vacía sigue mostrándola y ocultándola. La mochila y el llavero no son bolsas equipadas, así que no aceptan nada y ni siquiera se les ofrece la línea del clic derecho.",
    ["The enchant on the wrist slot sits closer to the rows around it, and the enchant on the weapon sits six pixels lower."] = "El encantamiento de la ranura de muñecas queda más cerca de las filas que lo rodean, y el del arma seis píxeles más abajo.",
    ["The trainer tab is a button of its own now. It used to be a spare tab of the spell book that we wrote on with every update, and the book reads those tabs back in the middle of its own pass. It also goes away with the pet book, where it used to stay behind."] = "La pestaña del entrenador es ahora un botón propio. Antes era una pestaña libre del libro de hechizos que escribíamos en cada actualización, y el libro vuelve a leer esas pestañas en mitad de su propio recorrido. Además desaparece con el libro de la mascota, donde antes se quedaba.",
    -- Nameplates: aura border + CC size
    ["Match the health bar height"] = "Ajustar a la altura de la barra de salud",
    ["The icon becomes a square exactly as tall as the health bar. The three size sliders below step aside while this is on."] = "El icono se vuelve cuadrado y exactamente igual de alto que la barra de salud. Los tres deslizadores de tamaño de debajo quedan inactivos mientras esto esté activado.",
    ["Border around aura icons"] = "Borde alrededor de los iconos de auras",
    ["The thin rim around debuff, damage-over-time, buff and crowd-control icons. Its thickness follows the border size of the plate."] = "El borde fino alrededor de los iconos de penalizadores, daño con el tiempo, beneficios y control de masas. Su grosor sigue al grosor del borde de la placa.",
    ["Aura border colour"] = "Color del borde de las auras",
    ["Border in the aura's own school colour"] = "Borde en el color de escuela del aura",
    ["Magic blue, curse purple, disease orange, poison green — instead of the one colour beside it."] = "Magia azul, maldición morado, enfermedad naranja, veneno verde — en lugar del único color de al lado.",
    -- Global settings: settings window scale
    ["Settings Window Scale"] = "Tamaño de la ventana de ajustes",
    ["Scales this settings window on its own. The game's interface keeps the size it has."] = "Escala solo esta ventana de ajustes. La interfaz del juego conserva el tamaño que tiene.",
    -- Patch notes 1.52.3
    ["Match the health bar height – Makes the crowd-control icon a square exactly as tall as the health bar, in place of its own size sliders"] = "Ajustar a la altura de la barra de salud – Convierte el icono de control de masas en un cuadrado exactamente igual de alto que la barra de salud, en lugar de sus propios deslizadores de tamaño",
    ["Border around aura icons – Switches the rim around debuff, damage-over-time, buff and crowd-control icons on or off, with its colour beside it"] = "Borde alrededor de los iconos de auras – Activa o desactiva el borde de los iconos de penalizadores, daño con el tiempo, beneficios y control de masas, con su color al lado",
    ["Text size – Sets how large the unit name and the health value are drawn, in the panel behind each of those two rows"] = "Tamaño del texto – Define el tamaño con el que se dibujan el nombre de la unidad y el valor de salud, en el panel detrás de cada una de esas dos filas",
    ["A long unit name is trimmed with three dots instead of running through the health value. The two share the bar as soon as both sit inside it, so the name now gets the width that is actually free — and only a health value at the other end takes room away, because sharing one slot is something you did on purpose. Only a name that would overflow is capped at all, which is what keeps the level number glued to the name instead of hanging off an oversized box."] = "Un nombre de unidad largo se recorta con tres puntos en lugar de atravesar el valor de salud. Los dos comparten la barra en cuanto ambos están dentro, así que el nombre recibe ahora el ancho que de verdad queda libre — y solo un valor de salud en el otro extremo le quita sitio, porque compartir una misma posición fue cosa tuya. Solo se limita un nombre que se desbordaría, y eso es lo que mantiene el número de nivel pegado al nombre en vez de colgando de un cuadro demasiado ancho.",
    ["The aura border can also take the colour of the aura's own school. That switch was read from the start and had no control anywhere."] = "El borde de las auras también puede tomar el color de escuela del aura. Ese interruptor se leía desde el principio y no tenía ningún control en ninguna parte.",
    ["Settings Window Scale – Scales this settings window on its own, from 70 to 130 per cent, while the game's interface keeps the size it has"] = "Tamaño de la ventana de ajustes – Escala solo esta ventana de ajustes, del 70 al 130 por ciento, mientras la interfaz del juego conserva su tamaño",
    ["Making the window smaller now gives it back its full size on a screen that was cutting it off. The fitting measured the room in the game's units and the window in its own, so scaling it down changed nothing about what it was allowed to be."] = "Reducir la ventana le devuelve ahora su tamaño completo en una pantalla que antes la recortaba. El ajuste medía el espacio en las unidades del juego y la ventana en las suyas, así que reducirla no cambiaba nada de lo que se le permitía ocupar.",
    -- Nameplates: reverse aura swipe
    ["Reverse the swipe"] = "Invertir el barrido",
    ["The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone."] = "La sombra vuelve a crecer mientras el aura se agota, así que un icono casi limpio significa que ya casi ha terminado.",
    -- Character panel: socket overwrite confirmation
    ["Replace %s with %s? The gem that comes out is destroyed."] = "¿Reemplazar %s por %s? La gema que sale se destruye.",
    ["That socket has changed — nothing was socketed."] = "Ese engarce ha cambiado — no se engarzó nada.",
    ["Click to replace the gem — the old one is destroyed."] = "Haz clic para reemplazar la gema — la anterior se destruye.",
    ["Ask before overwriting a gem"] = "Preguntar antes de sobrescribir una gema",
    ["A click on a socket that already holds a gem asks first — putting a gem in destroys the one that comes out."] = "Un clic en un engarce que ya tiene una gema pregunta primero — engarzar una gema destruye la que sale.",
    -- Loadouts: equipping straight out of the bank
    ["%d of them came out of the bank."] = "%d de ellos salieron del banco.",
    ["in the bank — open the bank window to equip it"] = "en el banco — abre la ventana del banco para equiparlo",
    -- Patch notes 1.52.4
    ["Ask before overwriting a gem – A click on a socket that already holds a gem asks first, because putting a gem in destroys the one that comes out"] = "Preguntar antes de sobrescribir una gema – Un clic en un engarce que ya tiene una gema pregunta primero, porque engarzar una gema destruye la que sale",
    ["Pointing at an occupied socket says what a click on it costs. Clicking one was always allowed, nothing ever said so, and the gem that comes out is destroyed. The question names both gems in their quality colours, and it drops the action when the gear moved while it was standing — otherwise a swap under the open dialog would answer for a socket you never looked at."] = "Al apuntar a un engarce ocupado se indica lo que cuesta hacer clic en él. Siempre se pudo hacer clic, nunca se dijo, y la gema que sale se destruye. La pregunta nombra ambas gemas en sus colores de calidad y descarta la acción si el equipo cambió mientras estaba abierta — de lo contrario, un cambio bajo el diálogo abierto habría respondido por un engarce que nunca miraste.",
    ["Equipping a set at the bank takes the pieces that are lying in the bank, as long as the bank window is open. Until now they counted as missing, so you could stand at the bank and be told the set was not equippable. The message says how many of them came out of the bank, and the piece that comes off goes into the bank slot the new one came from. With the bank closed, a missing piece in there no longer only names its place, it says to open the bank window."] = "Equipar un conjunto en el banco toma las piezas que están en el banco, mientras la ventana del banco esté abierta. Hasta ahora contaban como ausentes, así que podías estar junto al banco y recibir el aviso de que el conjunto no se podía equipar. El mensaje dice cuántas de ellas salieron del banco, y la pieza que te quitas va a la ranura del banco de la que vino la nueva. Con el banco cerrado, una pieza ausente que esté allí ya no solo nombra su lugar, te dice que abras la ventana del banco.",
    ["The line that tells you which sets an item belongs to appears in item tooltips. It was built and hooked up from the start, but it went in through the one tooltip mechanism this client offers and never uses, so no line was ever drawn and nothing complained."] = "La línea que te dice a qué conjuntos pertenece un objeto aparece en los tooltips de objeto. Estaba construida y enganchada desde el principio, pero pasaba por el único mecanismo de tooltip que este cliente ofrece y nunca usa, así que nunca se dibujó ninguna línea y nada se quejó.",
    ["Reverse the swipe – The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone"] = "Invertir el barrido – La sombra vuelve a crecer mientras el aura se agota, así que un icono casi limpio significa que ya casi ha terminado",
    ["The cooldown swipe on the aura icons has a control of its own. It was read from the start and could not be changed anywhere."] = "El barrido de reutilización en los iconos de aura tiene su propio control. Se leía desde el principio y no se podía cambiar en ninguna parte.",
    ["The raid target marker is visible at all. The eight marks live on one sheet, and the call that picks a tile out of it was working on a frame that never got the sheet — a cut-out of nothing, on every plate and in the preview, since the module was built."] = "La marca de banda se ve. Los ocho símbolos están en una sola hoja, y la llamada que elige una casilla de ella trabajaba sobre una superficie que nunca recibió la hoja — un recorte de nada, en cada placa y en la vista previa, desde que se construyó el módulo.",
    ["The raid target marker takes one of the six named slots, like the four aura rows. It had three positions of its own and could land on top of a row, which is the very collision the slots exist for. The old choice moves into the matching slot once and then goes, so there is no second control for the same question. Its room is reserved as soon as it is switched on, not only once a unit really carries a mark, so the rows do not jump every time somebody sets a skull."] = "La marca de banda ocupa una de las seis posiciones con nombre, igual que las cuatro filas de auras. Tenía tres posiciones propias y podía caer encima de una fila, justo la colisión para la que existen esas posiciones. La elección antigua se traslada una vez a la posición correspondiente y luego desaparece, para que no haya un segundo control para la misma pregunta. Su sitio se reserva en cuanto se activa, no solo cuando una unidad lleva realmente un símbolo, para que las filas no salten cada vez que alguien pone una calavera.",
    ["The marker's own offset and spacing sliders take effect again. They were writing two fields of their own while the plate read the slot, so the visible control was the one without an effect. The old values move across once."] = "Los deslizadores propios de desplazamiento y espaciado de la marca vuelven a tener efecto. Escribían en dos campos propios mientras la placa leía la posición, así que el control visible era el que no hacía nada. Los valores antiguos se trasladan una vez.",
    ["A mark set between two aura passes lands where it belongs. Where the marker goes is worked out in the aura pass, because only that knows how far the rows on its side reach, and the plate now remembers that point for the event that shows the marker on its own."] = "Un símbolo puesto entre dos pasadas de auras aparece donde le corresponde. Dónde va la marca se calcula en la pasada de auras, porque solo ella sabe hasta dónde llegan las filas de su lado, y la placa recuerda ahora ese punto para el evento que muestra la marca por sí sola.",
    ["The cast time and the cast target show something in the preview. Both only exist for a cast that is really running on a real unit, so both stayed empty while their switches, colours and side settings stood next to them with nothing to show."] = "El tiempo de lanzamiento y el objetivo del lanzamiento muestran algo en la vista previa. Ambos solo existen para un lanzamiento realmente en curso sobre una unidad real, así que ambos quedaban vacíos mientras sus interruptores, colores y ajustes de lado estaban al lado sin nada que mostrar.",
    -- Slot picker: the bags moved under an open picker
    ["Your bags moved — pick the item again."] = "Tus bolsas han cambiado — elige el objeto de nuevo.",
    -- Bar setups: load confirmation, imported macros left alone
    ["Load '%s'? Every button on your bars is overwritten or cleared."] = "¿Cargar '%s'? Cada botón de tus barras se sobrescribe o se vacía.",
    ["Macros: %d restored, %d of your own kept (an import does not rewrite them)."] = "Macros: %d restauradas, %d propias conservadas (una importación no las reescribe).",
    -- Patch notes 1.52.5
    ["The enchant text of the wrist slot sits under its slot instead of beside it. The wrist is the last slot of the left column, and to the right of it lies the weapon row, which is where the line was writing."] = "El texto de encantamiento de las muñequeras aparece debajo de su casilla en lugar de al lado. Las muñequeras son la última casilla de la columna izquierda, y a su derecha está la fila de armas, que es justo donde se escribía la línea.",
    ["Search field in the enchanting window – Leaves only the recipes whose name or reagents match what you type"] = "Campo de búsqueda en la ventana de encantamiento – Deja solo las recetas cuyo nombre o componentes coincidan con lo que escribes",
    ["The enchanting window is the one profession window that never had a search box. The field sits between the title and the slot dropdown: type into it and only the recipes whose name or one of their reagents matches stay, with the scroll bar shortening along with the list instead of leaving empty rows under the last hit. Recipes you starred still float to the top of what is left, and closing the window clears the text — otherwise the next visit would open on a list with most of the recipes missing and nothing on screen to explain it."] = "La ventana de encantamiento es la única ventana de profesión que nunca tuvo un campo de búsqueda. Está entre el título y el desplegable de ranuras: escribe en él y solo quedan las recetas cuyo nombre o alguno de sus componentes coincide, y la barra de desplazamiento se acorta con la lista en vez de dejar filas vacías bajo el último resultado. Las recetas marcadas con estrella siguen subiendo al principio de lo que queda, y al cerrar la ventana el texto se borra; de lo contrario, la próxima visita empezaría con una lista a la que le faltan casi todas las recetas y nada en pantalla que lo explique.",
    -- Patch notes 1.52.5
    ["Diminishing returns and interrupts recognise every rank of a spell. Both lists carried one identifier per spell, usually the one for rank one, so what is really cast at level seventy fell through: no icon for the polymorph, no bar for the kick. All ranks share their name, and the client knows the name behind every identifier already in the list, so one pass builds a name index that covers every rank at once, in the client's own language, which is the one the combat log speaks."] = "Las reducciones decrecientes y las interrupciones reconocen todos los rangos de un hechizo. Ambas listas llevaban un solo identificador por hechizo, casi siempre el de rango uno, así que se escapaba lo que de verdad se lanza a nivel setenta: sin icono para la metamorfosis, sin barra para la patada. Todos los rangos comparten el nombre, y el cliente conoce el nombre de cada identificador ya presente en la lista, así que una pasada construye con ellos un índice de nombres que cubre todos los rangos a la vez, en el idioma del propio cliente, que es el que habla el registro de combate.",
    ["Loading a setup asks first. It sets a hundred and twenty slots and empties the ones the setup has nothing for, and a single click in the dropdown was enough. The only warning, for a setup belonging to another class, was a chat line that arrived after the damage was done."] = "Cargar una configuración pregunta antes. Coloca ciento veinte espacios y vacía aquellos para los que la configuración no tiene nada, y bastaba un clic en el desplegable. El único aviso, para una configuración de otra clase, era una línea de chat que llegaba después del daño.",
    ["Importing a setup leaves your own macros and keybindings alone. Macros are matched by name, and a name like Pull belongs to everyone, so a foreign setup replaced the contents of your own macro of that name with the switch on by default and without a word about it. Imported setups are marked as foreign now and keep what is already there, and the message says how many were kept. A backup entry carrying no keys at all no longer gets restored either, which used to clear the keys of that command and save the result."] = "Importar una configuración deja en paz tus propias macros y asignaciones de teclas. Las macros se emparejan por nombre, y un nombre como Pull es de todos, así que una configuración ajena sustituía el contenido de tu macro homónima, con la opción activada por defecto y sin decir una palabra. Las configuraciones importadas se marcan ahora como ajenas y respetan lo que ya existe, y el mensaje dice cuántas se conservaron. Una entrada de copia de seguridad sin ninguna tecla tampoco se restaura ya, algo que antes borraba las teclas de ese comando y guardaba el resultado.",
    ["The enchant text of a weapon sits above its slot. Beside a weapon there is the next weapon, and to the left the whole text column, so the line had nowhere to go; above the weapon row the paper doll is empty. It is centred over its own slot and wraps upward, so two enchanted weapons no longer write across each other."] = "El texto de encantamiento de un arma va encima de su casilla. Al lado de un arma está la siguiente arma, y a la izquierda toda la columna de texto, así que la línea no tenía adónde ir; encima de la fila de armas el muñeco está vacío. Va centrada sobre su propia casilla y se parte hacia arriba, de modo que dos armas encantadas ya no escriben una sobre otra.",
    ["The question before overwriting a gem is only armed once the dialog is really standing. If one was already open the client reuses it, and rebuilding it cleared the note that had just been made, so the second question answered nothing at all and said nothing about it. The recheck now compares the item as well, and an open window on its own no longer counts as proof that it is the right one."] = "La pregunta antes de sobrescribir una gema solo se activa cuando el diálogo está realmente en pantalla. Si ya había uno abierto el cliente lo reutiliza, y reconstruirlo borraba la nota recién tomada, así que la segunda pregunta no respondía a nada y no lo decía. La comprobación posterior compara también el objeto, y una ventana abierta por sí sola ya no cuenta como prueba de que es la correcta.",
    ["The item level of a piece the client has not cached yet appears once it arrives. The retry ran into the very gate that had excluded it and drew nothing, ever. It is capped at twenty attempts per item so it cannot turn into a loop that runs every tenth of a second."] = "El nivel de objeto de una pieza que el cliente aún no ha guardado en caché aparece en cuanto llega. El reintento caía en la misma puerta que lo había excluido y no dibujaba nada, nunca. Ahora está limitado a veinte intentos por objeto para que no se convierta en un bucle cada décima de segundo.",
    ["Deleting an entry removes the one you clicked. It went by the position the row was built with, and the list is rewritten behind the open page whenever the trinket matching adds or removes entries after an equipment change, so the neighbour disappeared instead."] = "Borrar una entrada elimina la que has pulsado. Iba por la posición con la que se construyó la fila, y la lista se reescribe detrás de la página abierta en cuanto el emparejado de abalorios añade o quita entradas tras un cambio de equipo, de modo que desaparecía la vecina.",
    ["Logging in no longer opens the edit mode behind your back. Restoring frame positions used to apply the layout by showing the client's own edit mode manager, and that rebuilds every system the editor owns out of our call stack, which hands them to the addon for the rest of the session. Measured in game: one such call three seconds after login, and twenty seconds later 1593 refused actions in combat, party and raid frames among them. The layout is still written, and the client applies it the next time it does so itself. A frame you drag by hand still settles immediately."] = "Iniciar sesión ya no abre el modo de edición a tus espaldas. Restaurar las posiciones de los marcos aplicaba el diseño mostrando el propio gestor del modo de edición del cliente, y ese reconstruye todos los sistemas del editor a partir de nuestra pila de llamadas, con lo que pasan a pertenecer al addon durante el resto de la sesión. Medido en el juego: una llamada así tres segundos después de entrar y, veinte segundos más tarde, 1593 acciones rechazadas en combate, marcos de grupo y de banda incluidos. El diseño se sigue guardando y el cliente lo aplica la próxima vez que lo aplica por su cuenta. Un marco que arrastres a mano sigue colocándose al instante.",
    ["A frame dropped after a fight has started keeps the spot you dropped it at. A drag can only begin out of combat but it can end in one, and letting go wrote the anchor onto a protected frame without asking. The position was already saved by then, so the saved value and the frame on screen would have disagreed for the rest of the session. The write now waits for the fight to end and is made good afterwards."] = "Un marco que sueltas después de empezar un combate se queda donde lo has soltado. Un arrastre solo puede empezar fuera de combate, pero puede terminar dentro, y al soltar se escribía el anclaje sobre un marco protegido sin preguntar. La posición ya estaba guardada para entonces, así que el valor guardado y el marco en pantalla se habrían contradicho durante el resto de la sesión. La escritura espera ahora al final del combate y se recupera después.",
    ["The client settings the fishing mode borrows survive a crash. The backup of your own values lived in memory only, so a reload, a disconnect or a crash while fishing mode was running took it along, and music, ambience, auto loot and soft targeting stayed on the fishing values for good with nothing left anywhere to say what they had been."] = "Los ajustes del cliente que toma prestados el modo de pesca sobreviven a un cierre inesperado. La copia de tus propios valores vivía solo en memoria, así que una recarga, una desconexión o un cierre con el modo de pesca activo se la llevaba, y música, ambiente, recogida automática y objetivo suave se quedaban para siempre con los valores de pesca, sin que quedara en ningún sitio lo que había antes.",
    ["Switching the camera zoom option off returns the zoom to the client's default. The comment promised as much and the code did nothing of the sort, so with the option already on from an earlier session there was no value of ours to fall back to and the maximum stayed for every session after. It is only reset while the value still is our maximum, so anything you have set yourself since then stays."] = "Desactivar la opción de zoom de cámara devuelve el zoom al valor predeterminado del cliente. El comentario lo prometía y el código no hacía nada de eso, y si la opción ya venía activada de una sesión anterior no había ningún valor propio al que volver, así que el máximo se quedaba también en todas las sesiones siguientes. Solo se restablece mientras el valor siga siendo nuestro máximo, de modo que lo que hayas ajustado tú desde entonces se mantiene.",
    ["Unit tooltips no longer throw a Lua error on a unit without an identifier. The fallback one line above did the arithmetic on the missing identifier itself and handed the result to the very call that cannot take it."] = "Las descripciones de unidad ya no lanzan un error de Lua con una unidad sin identificador. El recurso alternativo de la línea anterior hacía él mismo el cálculo con el identificador ausente y pasaba el resultado justo a la llamada que no puede aceptarlo.",
    ["A set finds its own piece when two items share an identifier, the way the owl's ring and the bear's ring do. Sets store the full reference but searched by the bare identifier; the search goes by identifier and suffix now, while enchants and gems stay out of it because those change during an item's life and would make a set report its own piece as missing."] = "Un conjunto encuentra su propia pieza cuando dos objetos comparten identificador, como el anillo del búho y el del oso. Los conjuntos guardan la referencia completa, pero buscaban por el identificador desnudo; ahora se busca por identificador y sufijo, mientras que encantamientos y gemas quedan fuera a propósito, porque cambian a lo largo de la vida de un objeto y harían que un conjunto diera por perdida su propia pieza.",
    ["The name comes back after a cast the same way the interrupt flash already decides it. A retired field was still being asked, although the options page says it is read nowhere any more."] = "El nombre vuelve tras un lanzamiento igual que ya lo decide el destello de interrupción. Se seguía consultando un campo retirado, aunque la página de opciones dice que ya no se lee en ninguna parte.",
    ["The click area of a plate returns to its measured size. The value that means the client's own size was only right as long as the setter had never run, so afterwards the old area stood until a reload and the sliders went up without ever coming back."] = "El área de pulsación de una placa vuelve a su tamaño medido. El valor que significa el tamaño propio del cliente solo era correcto mientras no se hubiera ejecutado el asignador; después el área antigua se quedaba hasta recargar, y los deslizadores subían sin volver jamás.",
    ["An installation from before the schema stamp runs its migrations instead of skipping them. No stamp meant two opposite things, a fresh installation with nothing to migrate or one older than the stamp with everything still pending, and both were stamped current and skipped, so the older one silently lost every migration, its bar setups in their old storage place among them. The two are told apart now by whether there is any module data at all."] = "Una instalación anterior al sello de esquema ejecuta sus migraciones en lugar de saltárselas. La ausencia de sello significaba dos cosas opuestas, una instalación nueva sin nada que migrar o una más antigua que el sello con todo pendiente, y ambas quedaban selladas como actuales y omitidas, de modo que la más antigua perdía en silencio todas las migraciones, incluidas sus configuraciones de barras en su antiguo lugar de almacenamiento. Ahora se distinguen por si existe algún dato de módulo.",
    ["The strip for the weapon slots opens downward instead of sideways. The three weapons are the only slots standing in a row rather than a column, at the bottom of the paper doll, where sideways always runs into their own neighbour. It grows away from the middle of the screen so it cannot pass the near edge, and it tips upward when the window sits at the bottom of the screen."] = "La tira de las casillas de arma se despliega hacia abajo en vez de hacia el lado. Las tres armas son las únicas casillas que están en fila y no en columna, en la parte baja del muñeco, donde hacia el lado siempre se topa con su propia vecina. Crece alejándose del centro de la pantalla para no pasarse del borde cercano, y se vuelca hacia arriba cuando la ventana está pegada al borde inferior.",
    ["A click in the picker can no longer hit whatever has moved into that bag slot in the meantime. It remembered bag and slot from the moment it was filled and listened to no bag event, so after a sort run a click hit what was lying there by then, which with a merchant window open would have been a sale. It follows bag changes now, and every click checks the item in place against the one the button was built for."] = "Un clic en el selector ya no puede acertar a lo que haya llegado entretanto a esa casilla de bolsa. Recordaba bolsa y casilla del momento en que se llenó y no escuchaba ningún evento de bolsa, así que tras una ordenación el clic daba en lo que hubiera allí para entonces, y con una ventana de vendedor abierta eso habría sido una venta. Ahora sigue los cambios de bolsa, y cada clic compara el objeto que hay en el sitio con aquel para el que se construyó el botón.",
    ["The merchant lock covers both trinket slots. A mixed-up condition left it applying to the lower one only."] = "El bloqueo del vendedor se aplica a las dos casillas de abalorio. Una condición cruzada lo dejaba solo en la de abajo.",
    ["The addon no longer stamps the client's own health text and target classification with its taint. Both called the client's updaters from our call stack, the very thing the same file forbids two hundred lines further down in writing and with a reason, which makes the client's next pass over those frames unsafe. Both write what they need themselves now. The standard border returns the moment the client next classifies your target."] = "El addon ya no marca con su contaminación el texto de salud ni la clasificación de objetivo del propio cliente. Ambos llamaban a los actualizadores del cliente desde nuestra pila de llamadas, justo lo que el mismo archivo prohíbe doscientas líneas más abajo, por escrito y con motivo, y lo que vuelve insegura la siguiente pasada del cliente por esos marcos. Ahora cada uno escribe por su cuenta lo que necesita. El borde estándar vuelve en cuanto el cliente clasifica tu objetivo la próxima vez.",
    ["|cffff7777What it costs, and why this is off unless you switch it on: the answer has to sit on a name the client's own protected code reads, which hands the party and raid frames to this addon for the rest of the session. In combat they then refuse to resize and name this addon while doing it. Switching it back off stops it happening again but does not undo the session it already happened in - that takes a reload.|r"] = "|cffff7777Lo que cuesta, y por qué está desactivado mientras no lo actives: la respuesta tiene que residir en un nombre que el propio código protegido del cliente lee, y eso entrega los marcos de grupo y de banda a este addon durante el resto de la sesión. En combate se niegan entonces a cambiar de tamaño y nombran a este addon al hacerlo. Volver a desactivarlo solo evita que ocurra de nuevo, no deshace la sesión en la que ya ocurrió: para eso hace falta recargar.|r",
    ["not applied - this client does reject the call, so the error is firing"] = "no aplicado: este cliente sí rechaza la llamada, así que el error se produce",
    -- Patch notes 1.52.6
    ["X Offset / Y Offset – Nudge the stack and reagent numbers away from their chosen corner; both sit behind the gear of the position row"] = "Desplazamiento X / Desplazamiento Y – Aleja los números de pila y componentes de su esquina elegida; ambos están tras el engranaje de la fila de posición",
    ["Opening Edit Mode no longer hands the party and raid frames to the addon for the rest of the session. Merely opening it drove the client's frame editor through the addon, and in combat the client then refused to update those frames, naming the addon in the message. Only really moving one of Blizzard's frames still writes to the editor, and a frame that is hidden, like the focus frame while nothing is focused, never does."] = "Abrir el modo de edición ya no entrega los marcos de grupo y banda al addon durante el resto de la sesión. El mero hecho de abrirlo llevaba el editor de marcos del cliente a través del addon, y en combate el cliente rechazaba después actualizar esos marcos, nombrando al addon en el mensaje. Solo mover de verdad un marco de Blizzard sigue escribiendo en el editor, y un marco oculto, como el de foco sin ningún foco, no lo hace nunca.",
    ["Opening Edit Mode closes the options window. It sat exactly on top of the boxes it had just unlocked."] = "Abrir el modo de edición cierra la ventana de opciones. Se colocaba exactamente encima de las cajas que acababa de desbloquear.",
    ["The equipment list steps aside for the rune engraving panel. That panel opens on the right side of the character sheet, exactly where the list docks, so the two stood on top of each other. The list now follows the panel's edge, and where the screen is too narrow for sheet, panel and list together, it moves to the left side of the sheet."] = "La lista de equipamiento se aparta del panel de grabado de runas. Ese panel se abre a la derecha de la hoja de personaje, justo donde la lista se acopla, así que las dos quedaban una encima de la otra. La lista sigue ahora el borde del panel y, donde la pantalla es demasiado estrecha para hoja, panel y lista juntos, pasa al lado izquierdo de la hoja.",
    ["The role fix ships switched off. What it fixes is a silent error that truncates one update when a nameplate appears; what it costs is that the party and raid frames count as touched by the addon for the whole session and refuse to resize in combat, with the addon named in the message. That price was reaching players who never chose it, so now only whoever switches the fix on pays it."] = "El arreglo de rol viene desactivado. Lo que corrige es un error silencioso que recorta una actualización cuando aparece una placa de nombre; lo que cuesta es que los marcos de grupo y banda cuentan como tocados por el addon durante toda la sesión y se niegan a cambiar de tamaño en combate, con el addon nombrado en el mensaje. Ese precio lo pagaba gente que nunca lo eligió, así que ahora solo lo paga quien activa el arreglo.",
    ["The status line of the role fix tells the whole truth. With the fix off it used to claim it was not needed on this client, even for players who do have the error; it now says whether the fix is applied, not needed, or simply not switched on while the error is firing."] = "La línea de estado del arreglo de rol dice toda la verdad. Con el arreglo desactivado afirmaba que no era necesario en este cliente, incluso para jugadores que sí tienen el error; ahora dice si el arreglo está aplicado, si no hace falta o si simplemente no está activado mientras el error sigue saltando.",
    ["The bar ships switched off. A second resource bar is a strong opinion to hand someone who never asked for one, and the client already draws its own. Installations that already exist keep the bar exactly as it was."] = "La barra viene desactivada. Una segunda barra de recursos es una opinión fuerte para alguien que nunca la pidió, y el cliente ya dibuja la suya. Las instalaciones que ya existen conservan la barra exactamente como estaba.",
    ["The dark skin keeps Blizzard's rim off the stance buttons for good. Their updates write the button art back directly, past the hook that guards the action bars, so the rim used to return the first time you switched."] = "El aspecto oscuro mantiene el borde de Blizzard fuera de los botones de forma para siempre. Sus actualizaciones reescriben el arte del botón directamente, esquivando el gancho que protege las barras de acción, así que el borde volvía la primera vez que cambiabas.",
    ["Bonus"] = "Bonificación",
