    ["Chance to block enemy melee attacks with your shield."] = "Probabilidad de bloquear ataques cuerpo a cuerpo enemigos con tu escudo.",
    ["Shadow (darkened Blizzard border)"] = "Sombra (borde de Blizzard oscurecido)",
    ["Standard (Blizzard's own look)"] = "Estándar (aspecto original de Blizzard)",
    ["Pick how the action buttons look: Blizzard's own untouched button, the dark Shadow skin, or a masked shape (circle, square, hexagon)."] = "Elige el aspecto de los botones de acción: el botón original de Blizzard, el estilo oscuro Sombra o una forma con máscara (círculo, cuadrado, hexágono).",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): Blizzard's own look, the dark Shadow skin, or masked shapes.|r"] = "|cff9b6cffEl estilo de borde e icono de los botones está en el módulo Dark Skin (Action Bars > Bar style): el aspecto original de Blizzard, el estilo oscuro Sombra o formas con máscara.|r",
    ["Circle (masked shape)"] = "Círculo (forma con máscara)",
    ["Square (masked shape)"] = "Cuadrado (forma con máscara)",
    ["Hexagon (masked shape)"] = "Hexágono (forma con máscara)",
    ["WeakAuras style"] = "Estilo de WeakAuras",
    ["Style for WeakAuras icons, independent of the action bars."] = "Estilo de los iconos de WeakAuras, independiente de las barras de acción.",
    ["Shadow 1"] = "Shadow 1",
    ["Shadow 2"] = "Shadow 2",
    ["Shadow 3"] = "Shadow 3",
    ["Shadow 4"] = "Shadow 4",
    ["Shadow 5"] = "Shadow 5",
    ["Border color"] = "Color del borde",
    ["Tints the frame of the Shadow and shape styles. Reset it to get each style's built-in coloring back."] = "Tiñe el marco de los estilos Sombra y de formas. Restablécelo para recuperar el color integrado de cada estilo.",
    ["Tints the border layer of the aura sets. Reset it to get each set's built-in coloring back."] = "Tiñe la capa de borde de los conjuntos de auras. Restablécelo para recuperar el color integrado de cada conjunto.",
    ["Spell lists"] = "Listas de hechizos",
    ["Edit spell lists"] = "Editar listas de hechizos",
    ["Always-show and never-show spell IDs for this row."] = "IDs de hechizo para mostrar siempre o nunca en esta fila.",
    ["Always show"] = "Mostrar siempre",
    ["Never show"] = "No mostrar nunca",
    ["Auras on this list always appear in this row, even when its own rules would hide them."] = "Las auras de esta lista siempre aparecen en esta fila, incluso cuando sus propias reglas las ocultarían.",
    ["Auras on this list never appear in this row."] = "Las auras de esta lista nunca aparecen en esta fila.",
    ["No entries yet."] = "Aún no hay entradas.",
    ["Unknown spell"] = "Hechizo desconocido",
    ["Click to switch this entry on or off without deleting it."] = "Haz clic para activar o desactivar esta entrada sin borrarla.",
    ["Mine"] = "Propios",
    ["Any"] = "Todos",
    ["Counts only your own casts - click to count any caster."] = "Solo cuentan tus propios lanzamientos: haz clic para contar cualquier lanzador.",
    ["Counts any caster - click to count only your own casts."] = "Cuenta cualquier lanzador: haz clic para contar solo tus propios lanzamientos.",
    ["Low-health glow"] = "Brillo con poca salud",
    ["Lights the plate up once the unit drops below the chosen health percentage."] = "Ilumina la placa cuando la unidad cae por debajo del porcentaje de salud elegido.",
    ["Thin ring"] = "Anillo fino",
    ["Pulsing glow"] = "Brillo pulsante",
    ["Low-health percent"] = "Porcentaje de poca salud",
    -- Patch notes 1.53.0
    ["Every row of the stats sheet now explains itself when you point at it, and spell haste has joined the sheet."] = "Cada línea de la hoja de estadísticas se explica sola al señalarla, y la celeridad de hechizos se ha sumado a la hoja.",
    ["Custom class colours moved into the addon's own colour book. Writing them into the client's shared tables marked the party and raid frames as touched by the addon at every login, and the client then refused to resize them in combat. The clean-up has a price: the client's own windows and other addons show the standard class colours again, while the custom ones colour everything this addon draws."] = "Los colores de clase personalizados se mudan al libro de colores propio del addon. Escribirlos en las tablas compartidas del cliente marcaba los marcos de grupo y de banda como tocados por el addon en cada inicio de sesión, y el cliente se negaba después a ajustarlos en combate. La limpieza tiene un precio: las ventanas del propio cliente y otros addons vuelven a mostrar los colores de clase estándar, mientras que los personalizados tiñen todo lo que dibuja este addon.",
    ["Edit spell lists – Every aura row carries an always-show and a never-show spell ID list, kept in its own editing window behind the slot's fine tuning"] = "Editar listas de hechizos – Cada fila de auras lleva una lista de mostrar siempre y otra de no mostrar nunca por ID de hechizo, gestionadas en su propia ventana de edición tras el ajuste fino de la casilla",
    ["Low-health glow – Marks plates below a chosen health percentage, as a thin ring or a soft pulsing glow, in a colour of your choice"] = "Brillo con poca salud – Marca las placas por debajo de un porcentaje de salud elegido, como anillo fino o como brillo pulsante suave, en el color que elijas",
    ["The pulsing glow ships as a new texture file, so it takes one full client restart to appear; a reload is not enough."] = "El brillo pulsante llega como archivo de textura nuevo, así que necesita un reinicio completo del cliente para aparecer; recargar no basta.",
    ["The seal-twist helper no longer counts a swing ahead on parries or when attacking starts; its window used to point at a swing that never came."] = "El ayudante de cambio de sellos ya no adelanta un golpe en las paradas ni al empezar a atacar; su ventana apuntaba a un golpe que nunca llegaba.",
    ["The import preview no longer sits on top of the paste step of the import dialog."] = "La vista previa de importación ya no se coloca sobre el paso de pegado del diálogo de importación.",
    ["The clock keeps ticking through abilities that replace the swing, Heroic Strike and Cleave among them: they write their own combat log line instead of a swing line, so the bar used to stand still exactly for the classes that queue such an ability on every swing."] = "El reloj sigue corriendo con las habilidades que sustituyen el golpe, Golpe heroico y Hender entre ellas: escriben su propia línea en el registro de combate en lugar de una línea de golpe, así que la barra se quedaba parada justo para las clases que ponen una de esas habilidades en cada golpe.",
    ["Swing-resetting spells that deal no damage, parried special attacks and extra attacks now reach the clock too."] = "Los hechizos que reinician el golpe sin causar daño, los ataques especiales parados y los ataques extra ahora también llegan al reloj.",
    ["WeakAuras style – A separate icon style for WeakAuras, independent of the action bars, with five Shadow aura sets"] = "Estilo de WeakAuras – Un estilo de iconos aparte para WeakAuras, independiente de las barras de acción, con cinco conjuntos de auras Shadow",
    ["Border color – Tints the frame of the Shadow and shape styles; resetting it restores each style's built-in colouring"] = "Color del borde – Tiñe el marco de los estilos Shadow y de formas; restablecerlo devuelve el coloreado propio de cada estilo",
    ["The bar style now starts at Blizzard's own untouched look, and the masked shapes circle, square and hexagon bring their own frames."] = "El estilo de barras empieza ahora en el aspecto intacto de Blizzard, y las formas enmascaradas círculo, cuadrado y hexágono traen sus propios marcos.",
    -- Action Ring
    ["%d of %d entries"] = "%d de %d entradas",
    ["360 is a full circle; anything less opens a fan of that width."] = "360 es un círculo completo; cualquier valor menor abre un abanico de esa anchura.",
    ["Action Ring"] = "Anillo de acciones",
    ["Action Ring %d"] = "Anillo de acciones %d",
    ["Add an entry that runs a slash command or macro text."] = "Añade una entrada que ejecuta un comando de barra o texto de macro.",
    ["Add entry"] = "Añadir entrada",
    ["Add new ring"] = "Añadir nuevo anillo",
    ["All %d rings are in use."] = "Todos los %d anillos están en uso.",
    ["An extra key that closes the ring without using anything. ESCAPE always works."] = "Una tecla adicional que cierra el anillo sin usar nada. ESCAPE siempre funciona.",
    ["Arc width"] = "Anchura del arco",
    ["At the cursor"] = "En el cursor",
    ["Bind or change the key that opens this ring."] = "Asigna o cambia la tecla que abre este anillo.",
    ["Cancel key: %s"] = "Tecla de cancelación: %s",
    ["Clear cancel key"] = "Borrar tecla de cancelación",
    ["Clear select key"] = "Borrar tecla de selección",
    ["Click an entry to add it to the ring."] = "Haz clic en una entrada para añadirla al anillo.",
    ["Custom command"] = "Comando personalizado",
