    ["Delete ring"] = "Eliminar anillo",
    ["Distance from centre"] = "Distancia desde el centro",
    ["Edit ring"] = "Editar anillo",
    ["Enable action ring"] = "Activar anillo de acciones",
    ["Entries"] = "Entradas",
    ["Fixed screen position"] = "Posición fija en pantalla",
    ["Grey out unusable entries"] = "Atenuar entradas no utilizables",
    ["Hold a keybind to open a ring of actions around the cursor; aim at an entry and release to use it."] = "Mantén pulsada una asignación de teclas para abrir un anillo de acciones alrededor del cursor; apunta a una entrada y suelta para usarla.",
    ["Horizontal offset"] = "Desplazamiento horizontal",
    ["Keep the ring open"] = "Mantener el anillo abierto",
    ["Key %s was bound to '%s' - now opens %s."] = "La tecla %s estaba asignada a '%s' - ahora abre %s.",
    ["Keybind: %s"] = "Asignación de teclas: %s",
    ["Macros"] = "Macros",
    ["Markers"] = "Marcas",
    ["Not bound"] = "Sin asignar",
    ["Open position"] = "Posición de apertura",
    ["Opens this ring without a key press. It closes by itself after a while, or press the button again."] = "Abre este anillo sin pulsar ninguna tecla. Se cierra solo tras un tiempo, o pulsa el botón de nuevo.",
    ["Press a key... (ESC to cancel)"] = "Pulsa una tecla... (ESC para cancelar)",
