    ["Remove marker"] = "Quitar marca",
    ["Ring name"] = "Nombre del anillo",
    ["Ring setup"] = "Configuración del anillo",
    ["Select key: %s"] = "Tecla de selección: %s",
    ["Show cooldowns"] = "Mostrar tiempos de reutilización",
    ["Show ring name in the middle"] = "Mostrar el nombre del anillo en el centro",
    ["Shown in the middle of the ring and in the keybinding list."] = "Se muestra en el centro del anillo y en la lista de asignaciones de teclas.",
    ["Spells"] = "Hechizos",
    ["The key that uses the aimed entry while the ring is kept open. Without it the ring falls back to hold-and-release."] = "La tecla que usa la entrada apuntada mientras el anillo permanece abierto. Sin ella, el anillo vuelve al modo de mantener y soltar.",
    ["The ring grows on its own when entries would overlap; this is the smallest size."] = "El anillo crece por sí solo cuando las entradas se solaparían; este es el tamaño mínimo.",
    ["The ring stays open after the key is released. Aim and press the select key to use an entry; ESCAPE or the ring's key closes it."] = "El anillo permanece abierto tras soltar la tecla. Apunta y pulsa la tecla de selección para usar una entrada; ESCAPE o la tecla del anillo lo cierran.",
    ["This ring is empty - add entries below."] = "Este anillo está vacío - añade entradas abajo.",
    ["This ring is empty - add entries in the options."] = "Este anillo está vacío - añade entradas en las opciones.",
    ["This ring is full (%d entries)."] = "Este anillo está lleno (%d entradas).",
    ["Unbind"] = "Quitar asignación",
    ["|cffaaaaaaHold a keybind to open a ring of actions. Aim at an entry and release the key to use it; release over the middle to cancel. Each ring has its own keybind and its own entries.|r"] = "|cffaaaaaaMantén pulsada una asignación de teclas para abrir un anillo de acciones. Apunta a una entrada y suelta la tecla para usarla; suelta sobre el centro para cancelar. Cada anillo tiene su propia asignación de teclas y sus propias entradas.|r",
    -- Action Ring
    ["A dotted line from the centre toward the cursor. Ring layout only."] = "Una línea punteada desde el centro hacia el cursor. Solo con el diseño de anillo.",
    ["A near-square grid keeps the worst pointer travel short."] = "Una cuadrícula casi cuadrada mantiene corto el peor recorrido del puntero.",
    ["Apply this look to all rings"] = "Aplicar este aspecto a todos los anillos",
    ["Cancel form"] = "Cancelar forma",
    ["Choose columns automatically"] = "Elegir columnas automáticamente",
    ["Clear all markers"] = "Quitar todas las marcas",
    ["Columns"] = "Columnas",
    ["Custom"] = "Personalizado",
    ["Custom selection colour"] = "Color de selección personalizado",
    ["Cycle raid markers"] = "Alternar marcas de banda",
    ["Empty ring"] = "Anillo vacío",
    ["Entries each side"] = "Entradas a cada lado",
    ["Hide entries this character cannot use"] = "Ocultar entradas que este personaje no puede usar",
    ["Invert scroll direction"] = "Invertir la dirección de desplazamiento",
    ["New ring - empty or template"] = "Nuevo anillo: vacío o plantilla",
    ["Override the look for this ring"] = "Personalizar el aspecto de este anillo",
    ["Ring"] = "Anillo",
    ["Select with the mouse"] = "Seleccionar con el ratón",
    ["Selection colour"] = "Color de selección",
    ["Show entry names"] = "Mostrar nombres de las entradas",
    ["Show pointer needle"] = "Mostrar aguja del puntero",
    ["Strip (mouse wheel)"] = "Tira (rueda del ratón)",
    ["Strip direction"] = "Dirección de la tira",
    ["Templates are built from what this character has right now."] = "Las plantillas se crean a partir de lo que este personaje tiene ahora mismo.",
    ["The release fires the entry under the pointer; with this off, the wheel's entry fires."] = "Al soltar se activa la entrada bajo el puntero; con esto desactivado, se activa la entrada de la rueda.",
    ["The shared settings take this ring's values and every ring's own override is removed."] = "Los ajustes compartidos adoptan los valores de este anillo y se elimina la personalización propia de cada anillo.",
    ["Theme colour"] = "Color del tema",
    ["This ring keeps its own layout and display settings; every other ring follows the shared ones above."] = "Este anillo mantiene sus propios ajustes de diseño y visualización; los demás anillos siguen los compartidos de arriba.",
    ["This ring's own look"] = "Aspecto propio de este anillo",
    ["Unknown spells and missing macros are left out of the ring entirely. The stored entries stay for characters that can use them."] = "Los hechizos desconocidos y las macros que faltan quedan totalmente fuera del anillo. Las entradas guardadas se conservan para los personajes que puedan usarlas.",
    ["|cffaaaaaaTurn the override on to give this ring its own settings.|r"] = "|cffaaaaaaActiva la personalización para dar a este anillo sus propios ajustes.|r",
    ["Target markers"] = "Marcas de objetivo",
    ["Hearthstone"] = "Piedra de hogar",
    ["Teleports"] = "Teletransportes",
    ["Potions"] = "Pociones",
    ["Druid forms"] = "Formas de druida",
    ["Stances and auras"] = "Actitudes y auras",
    ["Quest items"] = "Objetos de misión",
    -- Action Ring
    ["Not in combat - keybinds can't be changed while fighting."] = "No en combate: las asignaciones de teclas no se pueden cambiar durante la lucha.",
    -- Action Ring
    ["Colour while a swing attack is queued"] = "Colorear mientras un golpe está en cola",
    ["While an on-next-swing attack (Heroic Strike, Cleave, Raptor Strike, Maul) is queued, the bar takes this colour - the resource it will eat is already spoken for."] = "Mientras un ataque al siguiente golpe (Golpe heroico, Hender, Golpe de raptor, Machacar) está en cola, la barra toma este color: el recurso que consumirá ya está comprometido.",
    ["Queued colour"] = "Color en cola",
    -- Patch notes 1.54.0
    ["Action Ring – Hold a keybind to open a ring of actions, aim at an entry and release to use it, spells, items and macros alike, in and out of combat"] = "Anillo de acciones – Mantén pulsada una tecla asignada para abrir un anillo de acciones; apunta a una entrada y suelta para usarla, hechizos, objetos y macros por igual, dentro y fuera de combate",
    ["Choose between a ring, a grid and a mouse-wheel strip, run up to 16 rings with their own keys, entries and look, and start from ready-made templates such as raid marks, teleports, potions or shapeshifts."] = "Puedes elegir entre anillo, cuadrícula y tira de rueda del ratón, llevar hasta 16 anillos con sus propias teclas, entradas y aspecto, y partir de plantillas listas como marcas de banda, teletransportes, pociones o cambios de forma.",
    ["The options page shows a live preview of the selected ring that redraws while you drag a slider, and a plus button right in the picture adds entries."] = "La página de opciones muestra una vista previa en vivo del anillo elegido que se redibuja mientras arrastras un deslizador, y un botón de más dentro de la imagen añade entradas.",
    ["Colour while a swing attack is queued – The resource bar shows a colour of your choice while an on-next-swing attack waits for the hit, so you can see that the resource is already spoken for"] = "Colorear mientras un golpe está en cola – La barra de recursos muestra un color a tu elección mientras un ataque al siguiente golpe espera su turno, para que veas que ese recurso ya está comprometido",
    ["The low-health glow now reaches further past the plate and rounds its corners more generously; before, it hugged the frame so tightly that it read as a border instead of a glow."] = "El brillo de salud baja llega ahora más allá de la placa y redondea sus esquinas con más generosidad; antes se pegaba tanto al marco que parecía un borde en lugar de un brillo.",
    ["The glow texture changed on disk, so it takes one full client restart to show its new shape; a reload is not enough."] = "La textura del brillo cambió en el disco, así que hace falta un reinicio completo del cliente para ver su nueva forma; recargar no basta.",
    ["The bar colour opens a full colour picker instead of a short list of presets; existing profiles keep the colour they had."] = "El color de la barra abre un selector de color completo en lugar de una lista corta de opciones fijas; los perfiles existentes conservan el color que tenían.",
    ["Bar default"] = "Predeterminado de la barra",
    ["Edit glows..."] = "Editar brillos...",
    ["Sound when ready"] = "Sonido cuando esté lista",
    ["Custom icon..."] = "Icono personalizado...",
    ["Park this icon (kept, never shown)"] = "Aparcar este icono (se conserva, nunca se muestra)",
    ["Drag to reorder. Right-click opens this icon's settings."] = "Arrastra para reordenar. Clic derecho abre los ajustes de este icono.",
    ["Drag to reorder. Right-click an icon for its settings."] = "Arrastra para reordenar. Clic derecho en un icono para sus ajustes.",
    ["Custom icon: enter a spell or item ID, or a texture path. Empty returns the real icon."] = "Icono personalizado: introduce el ID de un hechizo u objeto, o la ruta de una textura. Vacío devuelve el icono real.",
    ["Switching the module off now hands the micro buttons and the bag buttons back to their exact Blizzard positions, and a dialog offers the reload right away; the addon's row layout used to survive into the default bars until the next reload."] = "Al desactivar el módulo, los micro botones y los botones de bolsas vuelven exactamente a sus posiciones de Blizzard, y un diálogo ofrece recargar de inmediato; antes, la disposición en fila del accesorio sobrevivía en las barras estándar hasta la siguiente recarga.",
    ["Sound when ready – Every icon can announce the end of its cooldown with a sound from the shared media list, auditioned right in the menu with every click"] = "Sonido cuando esté lista – Cada icono puede anunciar el final de su reutilización con un sonido de la lista de medios compartidos, escuchado en el propio menú con cada clic",
    ["Custom icon... – Any entry can wear an icon of your choice, named by spell or item ID or a texture path"] = "Icono personalizado... – Cualquier entrada puede llevar el icono que elijas, indicado por ID de hechizo u objeto o por la ruta de una textura",
    ["Right-clicking an icon in the preview strip opens a settings menu for that one entry: glow while ready with its own colour, the ready flash, the dimming, the cooldown swipe and the countdown text can each override the bar's setting, and the glow editor, parking and removing live in the same place. Removing is no longer the bare right-click itself, so a stray click cannot shorten the bar."] = "Un clic derecho en un icono de la tira de vista previa abre un menú de ajustes para esa única entrada: el destello mientras esté lista con su propio color, el parpadeo, la atenuación, el barrido de reutilización y el texto de cuenta atrás pueden anular uno a uno el ajuste de la barra, y el editor de brillos, el aparcado y la eliminación viven en el mismo sitio. Eliminar ya no es el clic derecho a secas, así que un clic perdido ya no puede acortar la barra.",
    ["Long popup menus, the module list on the minimap button among them, now show a window that scrolls with the mouse wheel instead of growing past the screen edge."] = "Los menús emergentes largos, entre ellos la lista de módulos del botón del minimapa, muestran ahora una ventana que se desplaza con la rueda del ratón en lugar de crecer más allá del borde de la pantalla.",
    ["Helm"] = "Yelmo",
    ["Cloak"] = "Capa",
    ["Don't change"] = "No cambiar",
    ["shown"] = "visible",
    ["hidden"] = "oculto",
    ["Resilience"] = "Temple",
    ["Reduces the chance to be critically hit and the damage taken from critical strikes."] = "Reduce la probabilidad de recibir golpes críticos y el daño que estos infligen.",
    -- Patch notes 1.56.0
    ["Keeping the main bar on its page in every form now also holds the standard main bar, even while the whole module is off. The keys fire exactly what the buttons show, and switching to bars 2 to 6 by hand still works."] = "Mantener la barra principal en su página en todas las formas ahora también sujeta la barra principal estándar, incluso con el módulo entero desactivado. Las teclas disparan exactamente lo que muestran los botones, y cambiar a mano a las barras 2 a 6 sigue funcionando.",
    ["The stats sheet shows resilience under Defense, with the rating and its percent effect in the tooltip."] = "La hoja de estadísticas muestra el temple bajo Defensa, con la puntuación y su efecto porcentual en la descripción.",
    ["The enchant text on the equipment slots no longer falls onto the green armor line of pieces with built-in bonus armor; that line only stands in when no real enchant follows."] = "El texto de encantamiento en las casillas de equipo ya no cae sobre la línea verde de armadura de las piezas con armadura adicional incorporada; esa línea solo entra cuando no sigue un encantamiento real.",
    ["Helm / Cloak – Each set can show, hide or leave untouched the helm and the cloak as it is equipped, chosen in the row's right-click menu, and the row tooltip names the choice"] = "Yelmo / Capa – Cada conjunto puede mostrar, ocultar o dejar intactos el yelmo y la capa al equiparse, elegido en el menú contextual de la fila, y la descripción de la fila nombra la elección",
    ["The set rows can be reordered with the left mouse button held down: a translucent ghost follows the pointer, a line in the accent colour marks where the row will land, and letting go outside the list cancels. Existing sets keep their alphabetical order as the starting point, new ones join at the end."] = "Las filas de conjuntos se pueden reordenar manteniendo pulsado el botón izquierdo del ratón: un fantasma translúcido sigue al puntero, una línea en el color de acento marca dónde aterrizará la fila, y soltar fuera de la lista cancela. Los conjuntos existentes parten de su orden alfabético, los nuevos se añaden al final.",
    ["The red auto-attack blink sits exactly on the icon in the skinned button styles and is cut to the same shape; it used to be drawn for the standard button art and blinked beside the icon."] = "El parpadeo rojo del ataque automático se asienta exactamente sobre el icono en los estilos de botón repintados y se recorta a la misma forma; estaba dibujado para el arte del botón estándar y parpadeaba junto al icono.",
    ["Popup dialogs measure their frame with the font that is really drawn; with long texts the buttons used to hang below the border."] = "Los cuadros de diálogo miden su marco con la fuente que de verdad se dibuja; con textos largos los botones quedaban colgando bajo el borde.",
    ["In your bags: %d"] = "En las bolsas: %d",
    ["In the bank: %d"] = "En el banco: %d",
    ["Item counts in tooltips"] = "Cantidades en las descripciones",
    ["Item tooltips show how many you carry in your bags and how many sit in the bank, as last seen at a banker."] = "Las descripciones de objeto muestran cuántos llevas en las bolsas y cuántos hay en el banco, según la última visita al banquero.",
    ["Fonts"] = "Fuentes",
    ["Colors"] = "Colores",
    ["Module Fonts"] = "Fuentes por módulo",
    ["|cffaaaaaaGive single modules their own font; everything else follows the global font. Changes need a /reload.|r"] = "|cffaaaaaaDa a módulos concretos su propia fuente; todo lo demás sigue la fuente global. Los cambios necesitan /reload.|r",
    ["Button texts (keybind, macro name, count) and the XP bar text."] = "Textos de los botones (tecla, nombre de macro, cantidad) y el texto de la barra de experiencia.",
    ["Name, level, health, cast and aura text on nameplates."] = "Nombre, nivel, salud, texto de lanzamiento y de auras en las placas de nombre.",
    ["Duration, stacks and keybind text on the icons, the strip and the resource bar."] = "Texto de duración, acumulaciones y teclas en los iconos, la tira y la barra de recursos.",
    ["Chat messages, the input box and the tab labels, while the chat module uses the addon font."] = "Mensajes de chat, el cuadro de escritura y las etiquetas de las pestañas, mientras el módulo de chat use la fuente del addon.",
    ["The stats sheet of the modern character panel."] = "La hoja de estadísticas del panel de personaje moderno.",
    ["Requires /reload."] = "Necesita /reload.",
    ["Reduces the chance that your attacks are dodged or parried."] = "Reduce la probabilidad de que tus ataques sean esquivados o parados.",
    ["Dodge and parry reduction"] = "Reducción de esquivar y parar",
    -- Patch notes 1.57.0
    ["Bags & Bank"] = "Bolsas y banco",
    ["Item counts in tooltips – Item tooltips show how many you carry in your bags and how many sit in the bank, as last seen at a banker"] = "Cantidades en las descripciones – Las descripciones de objeto muestran cuántos llevas en las bolsas y cuántos hay en el banco, según la última visita al banquero",
    ["The bank mirror is taken on every banker visit now, with the default bank window and with the bags module switched off alike; it used to fill only while the replacement window was on."] = "El espejo del banco se toma ahora en cada visita al banquero, también con la ventana de banco estándar y con el módulo de bolsas desactivado; antes solo se llenaba mientras la ventana de reemplazo estaba activa.",
    ["The melee section shows expertise the way the game's own sheet does, with both weapons when dual wielding; the tooltip names the dodge and parry reduction in percent along with the rating. Only on clients whose game has the stat."] = "La sección de cuerpo a cuerpo muestra la pericia como la propia hoja del juego, con ambas armas al luchar con dos; la descripción indica la reducción de esquivar y parar en porcentaje junto con la puntuación. Solo en clientes cuyo juego tiene esa estadística.",
    ["Module Fonts – Give single modules their own font: action bars, nameplates, cooldown manager, chat and the stats sheet each take a face of their own, everything else follows the global font"] = "Fuentes por módulo – Da a módulos concretos su propia fuente: barras de acción, placas de nombre, gestor de reutilización, chat y la hoja de estadísticas aceptan cada uno su letra, todo lo demás sigue la fuente global",
    ["Fonts and colors live on two separate tabs now; the class and resource colors moved to their own Colors tab unchanged."] = "Las fuentes y los colores están ahora en dos pestañas separadas; los colores de clase y de recurso pasaron sin cambios a su propia pestaña de colores.",
    ["An imported look string carries the module fonts along, and the action bar buttons keep the game's own lettering until a module font is chosen for them."] = "Una cadena de aspecto importada lleva consigo las fuentes por módulo, y los botones de las barras de acción conservan la letra propia del juego hasta que se les elige una fuente de módulo.",
    -- Patch notes 1.57.1
    ["The form-paging section shows up in Standard mode too. The switch itself already reached the standard main bar; the row that flips it was only drawn in Modern mode, so nobody running the standard bars could find it."] = "La sección contra el cambio de página por formas aparece ahora también en el modo estándar. El interruptor ya alcanzaba la barra principal estándar; su fila solo se dibujaba en el modo moderno, así que nadie con barras estándar podía encontrarla.",
    ["Seven hot paths allocate less memory: unit-frame health text, nameplate number formatting and health smoothing, cooldown-manager scan keys, combat-text throttling, bag refreshes, the arena bar-text hook and the reminder pass all reuse what they used to rebuild, so the garbage collector has less to clean up in combat."] = "Siete rutas calientes reservan menos memoria: el texto de salud de los marcos de unidad, el formato de números y el suavizado de salud de las placas, las claves de exploración del gestor de reutilización, el limitador del texto de combate, el refresco de bolsas, el texto de barras de arena y la pasada de recordatorios reutilizan lo que antes reconstruían; el recolector de basura tiene menos que limpiar en combate.",
    ["The red auto-attack blink sits on the icon in every button style now, the untouched standard button included. The game defines that blink with retail-sized frame art and a single corner anchor, so on the classic button art it hung past the button to the right and bottom."] = "El parpadeo rojo del ataque automático se asienta ahora sobre el icono en todos los estilos de botón, incluido el botón estándar intacto. El juego define ese parpadeo con arte de marco a tamaño de Retail y una sola ancla de esquina, por lo que en el arte clásico sobresalía por la derecha y por abajo.",
-- Trackbars
["Clock"] = "Reloj",
["Start empty"] = "Empezar vacía",
["An empty bar to build from scratch."] = "Una barra vacía para construir desde cero.",
["Top/Bottom info bar"] = "Barra de información superior/inferior",
["Full-width bar with the classic info blocks."] = "Barra a todo lo ancho con los bloques de información clásicos.",
["Minimap companion"] = "Acompañante del minimapa",
["Compact clock and FPS readout."] = "Reloj compacto y lectura de FPS.",
["Micro menu strip"] = "Tira del micromenú",
["Just the micro menu buttons."] = "Solo los botones del micromenú.",
["Bar %d"] = "Barra %d",
["User-built info bars: clock, gold, XP, micro menu and more."] = "Barras de información personalizadas: reloj, oro, EXP, micromenú y más.",
["Server time"] = "Hora del servidor",
["Local time"] = "Hora local",
["fps"] = "fps",
["ms"] = "ms",
["Dur"] = "Dur.",
["Session earned"] = "Ganado en la sesión",
["Session spent"] = "Gastado en la sesión",
["Session profit"] = "Ganancia de la sesión",
["+%d more"] = "+%d más",
["Total"] = "Total",
["Left-Click: bags -- Ctrl+Right-Click: reset session"] = "Clic izquierdo: bolsas -- Ctrl + Clic derecho: restablecer sesión",
["free"] = "libres",
["Max level (Right-Click: reputation)"] = "Nivel máximo (Clic derecho: reputación)",
["XP"] = "EXP",
["No reputation tracked"] = "Ninguna reputación registrada",
["Current"] = "Actual",
["Rested"] = "Descansado",
["Right-Click: toggle XP / reputation"] = "Clic derecho: alternar EXP / reputación",
["Gap"] = "Separación",
["Use accent color"] = "Usar color de acento",
["Paints this block in the interface accent color instead of the color above."] = "Pinta este bloque con el color de acento de la interfaz en lugar del color de arriba.",
["24-hour clock"] = "Reloj de 24 horas",
["Show world latency"] = "Mostrar la latencia de mundo",
["Show free bag slots"] = "Mostrar las ranuras de bolsa libres",
["Short format (gold only)"] = "Formato corto (solo oro)",
["Show coordinates"] = "Mostrar coordenadas",
["|cffaaaaaaBuild your own info bars from blocks: clock, gold, XP, latency, micro menu and more. Create a bar from a template, then stack and order its blocks below.|r"] = "|cffaaaaaaCrea tus propias barras de información a partir de bloques: reloj, oro, EXP, latencia, micromenú y más. Crea una barra desde una plantilla y luego apila y ordena sus bloques abajo.|r",
["Enable Trackbars"] = "Activar Trackbars",
["Create your first bar"] = "Crea tu primera barra",
["|cffaaaaaaPick a template to start with. Every bar stays fully editable afterwards.|r"] = "|cffaaaaaaElige una plantilla para empezar. Cada barra sigue siendo totalmente editable después.|r",
["Bar"] = "Barra",
["New bar..."] = "Nueva barra...",
["Click again to delete"] = "Vuelve a hacer clic para borrar",
["Removes the selected bar and all of its blocks."] = "Elimina la barra seleccionada y todos sus bloques.",
["Bar Settings"] = "Ajustes de la barra",
["Length"] = "Longitud",
["Edge"] = "Borde",
["Edge offset"] = "Desplazamiento del borde",
["Stop moving"] = "Dejar de mover",
["Shows the movers so free-standing bars can be dragged into place."] = "Muestra los movedores para que las barras independientes se puedan arrastrar a su sitio.",
["Distribution"] = "Distribución",
["Auto sizes each block by its content; even split gives every block the same share of the bar."] = "Automático ajusta el tamaño de cada bloque según su contenido; reparto uniforme da a cada bloque la misma parte de la barra.",
["Font scale"] = "Escala de fuente",
["Hide border"] = "Ocultar borde",
["Blocks"] = "Bloques",
["|cffaaaaaaThis bar has no blocks yet -- add one below.|r"] = "|cffaaaaaaEsta barra todavía no tiene bloques -- añade uno abajo.|r",
["Add block..."] = "Añadir bloque...",
["Full width"] = "Ancho completo",
["Custom length"] = "Longitud personalizada",
["Even split"] = "Reparto uniforme",

    -- Patch notes 1.58.0
    ["Trackbars"] = "Trackbars",
    ["Trackbars – Build your own info bars from blocks: clock, gold, XP, latency, micro menu and more"] = "Trackbars – Crea tus propias barras de información con bloques: reloj, oro, EXP, latencia, micromenú y más",
    ["Bars are created from templates: start empty, a full-width info bar pinned to the top or bottom edge, a compact minimap companion, or a micro menu strip. Every bar stays fully editable afterwards."] = "Las barras se crean a partir de plantillas: empezar vacía, una barra de información a ancho completo fijada al borde superior o inferior, un compañero de minimapa compacto o una barra de micromenú. Toda barra sigue siendo totalmente editable después.",
    ["Ten blocks to stack and order: clock, gold, XP and reputation, FPS, latency, durability, free bag slots, zone with coordinates, micro menu, and a spacer."] = "Diez bloques para apilar y ordenar: reloj, oro, EXP y reputación, FPS, latencia, durabilidad, espacios libres de bolsa, zona con coordenadas, micromenú y un separador.",
    ["The gold block tracks what the current session earned and spent, and its tooltip lists the gold of every character on the account, richest first."] = "El bloque de oro registra lo ganado y lo gastado en la sesión actual, y su descripción lista el oro de cada personaje de la cuenta, los más ricos primero.",
    ["The XP block renders a real progress bar with the rested bonus overlaid, and a right-click switches it to the tracked reputation."] = "El bloque de EXP dibuja una barra de progreso real con la bonificación de descanso superpuesta, y un clic derecho lo cambia a la reputación seguida.",
    ["The micro menu opens the spellbook, talents and friends through the game's own buttons, so it works safely in combat and never blocks spell casting."] = "El micromenú abre el libro de hechizos, los talentos y los amigos mediante los propios botones del juego, así que funciona con seguridad en combate y nunca bloquea el lanzamiento de hechizos.",
    ["The module ships disabled: switch it on under HUD in the options window."] = "El módulo viene desactivado: actívalo en HUD dentro de la ventana de opciones.",
-- Resistance verdict
["Resists on average %d%% of matching spell damage against boss enemies."] = "Resiste de media un %d%% del daño de hechizos correspondiente contra jefes.",
["Decent"] = "Aceptable",
["Good"] = "Bueno",
["Very good"] = "Muy bueno",
["Maximum"] = "Máximo",
    -- Patch notes 1.58.1
    ["The resistance tooltips now rate the value: how much matching spell damage you resist on average against boss enemies, by the game's own formula, plus a colored verdict from Low to Maximum."] = "Las descripciones de resistencias ahora valoran el valor: cuánto daño de hechizos correspondiente resistes de media contra jefes, según la fórmula del propio juego, más un veredicto coloreado de Bajo a Máximo.",
    ["Two copies of the same item that differ only in their gems or enchants now swap correctly when switching sets. A regemmed single copy still counts as equipped and is never reported missing. If a set was saved before the gems went in, save it once more while wearing the right copy."] = "Dos copias del mismo objeto que solo se diferencian en gemas o encantamientos ahora se intercambian correctamente al cambiar de conjunto. Una copia única con gemas nuevas sigue contando como equipada y nunca se marca como ausente. Si un conjunto se guardó antes de engarzar las gemas, guárdalo una vez más llevando la copia correcta.",
    ["A sweep over thirteen files cuts memory churn and idle work in hot paths: timer texts only rebuild when their value changes, the trinket queue checks once per second instead of every frame, the arena binds its aura events per zone, and the dark skin, bags, tooltips and class trackers reuse what they already computed."] = "Una pasada por trece archivos reduce el trabajo de memoria y en reposo en las rutas calientes: los textos de tiempo solo se reconstruyen al cambiar su valor, la cola de abalorios comprueba una vez por segundo en lugar de cada fotograma, la arena vincula sus eventos de auras por zona, y el estilo oscuro, las bolsas, las descripciones y los rastreadores de clase reutilizan lo ya calculado.",
["Not enough free bag space to unequip everything."] = "No hay suficiente espacio libre en las bolsas para quitarse todo.",
    -- Patch notes 1.58.2
    ["Empty slots are now part of a set: saving records deliberately bare slots, and equipping strips those pieces into the bags, with a single notice when the bags are too full. Sets saved before this change keep their old behavior, so save a set once more to pick up its empty slots."] = "Los espacios vacíos ahora forman parte del conjunto: al guardar se registran los espacios dejados libres a propósito, y al equipar esas piezas se retiran a las bolsas, con un único aviso si las bolsas están demasiado llenas. Los conjuntos guardados antes de este cambio conservan su comportamiento anterior; guarda un conjunto una vez más para que adopte sus espacios vacíos.",
    ["The unit's level at the name's left edge, coloured by how dangerous it is to you."] = "El nivel de la unidad en el borde izquierdo del nombre, coloreado según lo peligrosa que es para ti.",
    ["Elite and rare tag"] = "Etiqueta de élite y raro",
    ["Adds + for elite, R for rare, R+ for rare elite and B for world bosses. A tagged level turns gold."] = "Añade + para élite, R para raro, R+ para élite raro y B para jefes de mundo. Un nivel etiquetado se vuelve dorado.",
    ["Level text size"] = "Tamaño del texto del nivel",
    ["0 = uses the name's text size."] = "0 = usa el tamaño de texto del nombre.",
    ["Where the row extends as more icons arrive. Left and right apply to a horizontal row above or below the plate. Up and down give a vertical column beside the plate a fixed starting end instead of staying centred."] = "Hacia dónde se extiende la fila cuando llegan más iconos. Izquierda y derecha se aplican a una fila horizontal encima o debajo de la placa. Arriba y abajo dan a una columna vertical junto a la placa un extremo inicial fijo en lugar de mantenerse centrada.",
    ["The icon picker offers the client's complete icon library in a mouse-wheel scrollable grid; the automatic choice and the set's own pieces stay in front."] = "El selector de iconos ofrece la biblioteca de iconos completa del juego en una cuadrícula desplazable con la rueda del ratón; la opción automática y las piezas del conjunto se quedan delante.",
    ["Stripping pieces into the bags claims an empty slot for every piece before anything moves, so switching to a set with bare slots no longer fails with red bag-is-full errors from stale free-space counts or special bags that cannot hold armor."] = "Al desequipar piezas a las bolsas se reserva de antemano un hueco vacío para cada pieza: cambiar a un conjunto con huecos libres ya no falla con errores rojos de bolsa llena por recuentos de espacio anticuados o bolsas especiales que no admiten armadura.",
    ["Show level – The unit's level at the name's left edge, colored by difficulty, with an elite and rare tag, text size and offsets behind its gear"] = "Mostrar el nivel – El nivel de la unidad en el borde izquierdo del nombre, coloreado por dificultad, con etiqueta de élite y raro, tamaño de texto y desplazamientos tras su engranaje",
    ["Growth direction – Decide where an aura row extends as more icons arrive: left or right for a horizontal row, up or down for a column beside the plate"] = "Dirección de crecimiento – Decide hacia dónde se extiende una fila de auras cuando llegan más iconos: izquierda o derecha en una fila horizontal, arriba o abajo en una columna junto a la placa",
    ["Broker plugin"] = "Plugin Broker",
    ["Plugin"] = "Plugin",
    ["No broker plugins found"] = "No se encontraron plugins Broker",
    ["Strip colors"] = "Quitar colores",
    ["Max width"] = "Anchura máxima",
    ["Removes the plugin's own color codes so the text takes the block color."] = "Elimina los códigos de color propios del plugin para que el texto tome el color del bloque.",
    ["0 = automatic width. Above 0 the text is cut off at this width."] = "0 = anchura automática. Por encima de 0, el texto se corta en esta anchura.",
    -- Patch notes 1.59.0
    ["Texts that nothing in the interface looks up any more are gone from all nine languages: option labels from before the nameplate options were rebuilt, and patch notes of versions that have left the in-game list."] = "Los textos que ya nada en la interfaz consulta han desaparecido de los nueve idiomas: etiquetas de opciones anteriores a la reconstrucción de las opciones de placas de nombre y notas de versiones que ya no aparecen en la lista del juego.",
    ["Aura icons no longer flicker. Every aura event on a unit rebuilt each icon from scratch, so the countdown went blank until the next tick, the expiry pulse snapped back to full, and the cooldown sweep restarted. An icon now keeps its state until a genuinely different aura takes its place, and a new aura shows its number in the same frame it appears."] = "Los iconos de auras ya no parpadean. Cada evento de aura en una unidad reconstruía cada icono desde cero, de modo que la cuenta atrás quedaba en blanco hasta el siguiente tic, el pulso de expiración volvía de golpe a opacidad completa y el barrido de reutilización se reiniciaba. Ahora un icono conserva su estado hasta que un aura realmente distinta ocupa su lugar, y un aura nueva muestra su número en el mismo fotograma en que aparece.",
    ["Broker plugin – A block that shows another addon's data object with its icon and text, reacts to clicks and shows its tooltip, with switches to strip the plugin's color codes and cap the width"] = "Plugin Broker – Un bloque que muestra el objeto de datos de otro addon con su icono y su texto, reacciona a los clics y muestra su descripción emergente, con interruptores para eliminar los códigos de color del plugin y limitar el ancho",
    ["Combat Meter"] = "Medidor de combate",
    ["Damage"] = "Daño",
    ["DPS"] = "DPS",
    ["HPS"] = "HPS",
    ["Overall"] = "Total",
    ["Current fight"] = "Combate actual",
    ["Mode, segment and reset"] = "Modo, segmento y reinicio",
    ["Per second"] = "Por segundo",
    ["Share"] = "Porcentaje",
    ["Overhealing"] = "Sobrecuración",
    ["Fight duration"] = "Duración del combate",
    ["Enable combat meter"] = "Activar medidor de combate",
    ["Show rank"] = "Mostrar posición",
    ["Show value in brackets"] = "Mostrar valor entre paréntesis",
    ["Per-second value next to the total. In the per-second modes the brackets show the total instead."] = "Valor por segundo junto al total. En los modos por segundo, el paréntesis muestra el total en su lugar.",
    ["Show percent"] = "Mostrar porcentaje",
    ["Highlight your own bar"] = "Resaltar tu propia barra",
    ["Only in group"] = "Solo en grupo",
    ["Hide out of combat"] = "Ocultar fuera de combate",
    ["Hide delay (seconds)"] = "Retraso de ocultación (segundos)",
    ["Reset overall when joining a new group"] = "Reiniciar el total al unirse a un grupo nuevo",
    -- Patch notes 1.60.0
    ["Combat Meter – A lightweight damage and healing meter as its own HUD module: who did how much, per fight and overall"] = "Medidor de combate – Un medidor ligero de daño y sanación como módulo propio del HUD: quién hizo cuánto, por combate y en total",
    ["Damage taken"] = "Daño recibido",
    ["Deaths"] = "Muertes",
    ["Window %d"] = "Ventana %d",
    ["Segment"] = "Segmento",
    ["Abilities in tooltip"] = "Habilidades en la descripción",
    ["Show class icon"] = "Mostrar icono de clase",
    ["New window"] = "Nueva ventana",
    ["No details yet"] = "Aún sin detalles",
    ["Unknown"] = "Desconocido",
    ["Close window"] = "Cerrar ventana",
    ["Combat Meter %d"] = "Medidor de combate %d",
    ["The engine reads your own combat log and counts, per group member, damage, healing, damage taken, interrupts, dispels and deaths, with a per-ability breakdown behind each. Pets, totems and guardians credit their owner, overhealing stays apart from effective healing, and a feigning hunter is not a death. A fight is group-wide: it opens on your own combat or on the first damage a group member deals, takes the boss name from the encounter events, and closes once nobody in the group is fighting any more. The overall total survives a reload and starts fresh when you join a new group."] = "El motor lee tu propio registro de combate y cuenta, por miembro del grupo, daño, sanación, daño recibido, interrupciones, disipaciones y muertes, cada uno con un desglose por habilidad. Mascotas, tótems y guardianes se acreditan a su dueño, la sobresanación se mantiene aparte de la sanación efectiva, y un cazador fingiendo su muerte no cuenta como muerte. Un combate abarca a todo el grupo: empieza con tu propio combate o con el primer daño que inflige un miembro del grupo, toma el nombre del jefe de los eventos de encuentro y termina cuando nadie del grupo sigue luchando. El total general sobrevive a una recarga y empieza de cero cuando te unes a un grupo nuevo.",
    ["The bars come in class colours with the class icon, rank and name on the left and the total with the per-second value in brackets on the right. Hovering a bar lists the strongest abilities with icon, value and share; the interrupt and dispel modes list what was stopped or removed, and the death mode lists each death with its time and killing blow. Left-click on the title opens the menu, the mouse wheel on the title cycles the eight modes, the wheel over the bars scrolls, the gear opens the options. Right-drag the title to move a window, resize it in edit mode."] = "Las barras usan los colores de clase, con el icono de clase, el puesto y el nombre a la izquierda y el total con el valor por segundo entre paréntesis a la derecha. Al pasar el ratón por una barra se muestran las habilidades más fuertes con icono, valor y porcentaje; los modos de interrupciones y disipaciones muestran qué se detuvo o se eliminó, y el modo de muertes muestra cada muerte con su momento y el golpe mortal. Clic izquierdo en el título abre el menú, la rueda del ratón sobre el título recorre los ocho modos, la rueda sobre las barras desplaza la lista y el engranaje abre las opciones. Arrastra el título con el botón derecho para mover una ventana y cambia su tamaño en el modo de edición.",
    ["Options cover bar height, font size, texture, the class icon, how many abilities the tooltip lists, which parts of the bar text to show, the visibility rules (only in a group, in combat, out of combat with a delay) and the window list."] = "Las opciones cubren la altura de las barras, el tamaño de fuente, la textura, el icono de clase, cuántas habilidades muestra la descripción, qué partes del texto de la barra se muestran, las reglas de visibilidad (solo en grupo, en combate, fuera de combate con retardo) y la lista de ventanas.",
    ["Lock position"] = "Bloquear posición",
    ["Unlock position"] = "Desbloquear posición",
    ["Lightweight damage and healing meter: who did how much, per fight and overall. Left-click the title for mode and segment, mouse wheel on the title cycles modes, the padlock frees a window for dragging."] = "Medidor ligero de daño y sanación: quién hizo cuánto, por combate y en total. Clic izquierdo en el título para modo y segmento, rueda del ratón sobre el título cambia el modo, el candado libera la ventana para arrastrarla.",
    ["Open as many windows as you need: the title menu adds a window for any mode and closes one again, and every window keeps its own mode, segment, position and size while the look and the visibility rules are shared. The padlock in the title bar frees a window for dragging or pins it in place, and the anchor entry in the title menu docks a window to any side of another so the two move as one."] = "Abre tantas ventanas como necesites: el menú del título añade una ventana para cualquier modo y también la cierra, y cada ventana conserva su propio modo, segmento, posición y tamaño mientras el aspecto y las reglas de visibilidad se comparten. El candado de la barra de título libera una ventana para arrastrarla o la fija en su sitio, y la entrada de anclaje del menú del título acopla una ventana a cualquier lado de otra para que ambas se muevan juntas.",
    ["Patch notes of versions that have left the in-game list are gone from all nine languages; nothing the interface shows was affected."] = "Las notas de versiones que ya no aparecen en la lista del juego se han eliminado de los nueve idiomas; nada de lo que muestra la interfaz se vio afectado.",
} end

ns:RegisterLocale("esES", T)
ns:RegisterLocale("esMX", T)   -- same translation serves this client
